          <FilterBar 
            viewFilter={viewFilter} 
            setViewFilter={setViewFilter} 
            term={term}
            setTerm={setTerm}
          />
          <GradeTable viewFilter={viewFilter} term={term} />
        </div>
      </main>
    </div>
  );
};

