interface GradeTableProps {
  viewFilter: ViewFilter;
  term: string;
  selectedClass: string;
}

interface ColumnDef {
  name: string;
  group: 'subjects' | 'qualities' | 'skills';
  subgroup: 'common' | 'specific' | null;
  isComment?: boolean;
}

