              <ChevronDown size={14} className={`transition-transform ${showPrintDropdown ? 'rotate-180' : ''}`} />
            </button>

            {showPrintDropdown && (
              <div className="absolute right-0 mt-2 w-72 bg-white border border-gray-200 rounded-lg shadow-xl z-50 py-1 overflow-hidden">
                <button 
                  onClick={() => {
                    setIsModalOpen(true);
