import React from 'react';
import { X, Printer } from 'lucide-react';
import { SUBJECTS_BY_CLASS, STUDENTS_DATA } from '../constants';

interface ReportPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  studentName?: string;
  currentTerm?: string;
}

const ReportPreviewModal: React.FC<ReportPreviewModalProps> = ({ isOpen, onClose, studentName, currentTerm = 'Cuối kỳ 1' }) => {
  if (!isOpen) return null;

  // Find the student to determine their class and data
  const student = STUDENTS_DATA.find(s => s.name === studentName) || STUDENTS_DATA[0];
  const className = student.className;
  const classSubjects = SUBJECTS_BY_CLASS[className] || SUBJECTS_BY_CLASS['1A2'];

  // Logic to determine which subjects have numeric scores (synchronized with GradeTable.tsx)
  const getScoredSubjectsForTerm = (cls: string, term: string) => {
    // Grade 1 rules
    if (cls === '1A2') {
      if (term === 'Cuối kỳ 1' || term === 'Cuối năm') return ['Tiếng Việt', 'Toán'];
      return [];
    }
    // Grade 5 rules
    if (cls === '5A2') {
      if (term === 'Giữa kỳ 1' || term === 'Giữa kỳ 2') return ['Tiếng Việt', 'Toán'];
      if (term === 'Cuối kỳ 1' || term === 'Cuối năm') return [
        'Tiếng Việt', 
        'Toán', 
        'Ngoại ngữ 1', 
        'Lịch sử và Địa lý', 
        'Khoa học', 
        'Tin học và Công nghệ'
      ];
    }
    return [];
  };

  const currentScoredSubjects = getScoredSubjectsForTerm(className, currentTerm);

  const generateGradeData = (subjName: string, index: number) => {
    const isScored = currentScoredSubjects.includes(subjName);

    // Levels: T (Hoàn thành tốt), H (Hoàn thành), C (Chưa hoàn thành)
    const levels = ['T', 'H'];
    const m1 = levels[index % 2];
    const m2 = levels[(index + 1) % 2];

    // Scores (only for subjects that require them in the current context)
    const d1 = isScored ? (8.5 + (index * 0.3) % 1.5).toFixed(1) : '';
    const d2 = isScored ? (9.0 + (index * 0.4) % 1.0).toFixed(1) : '';

    return { m1, d1, m2, d2 };
  };

  const subjects = classSubjects.map((name, index) => {
    const grades = generateGradeData(name, index);
    return {
      stt: index + 1,
      name: name,
      ...grades,
      note: grades.m2 === 'T' ? 'Nắm vững kiến thức, kỹ năng môn học.' : 'Hoàn thành tốt các yêu cầu môn học.'
    };
  });

  return (
    <div className="fixed inset-0 z-[9999] flex flex-col bg-gray-500/40 backdrop-blur-sm overflow-hidden animate-in fade-in duration-200">
      {/* Modal Header Bar */}
      <div className="bg-white border-b border-gray-200 px-6 py-3 flex items-center justify-between shadow-md sticky top-0 z-10">
        <h2 className="text-gray-800 font-bold text-lg">Xem trước Phiếu điểm - {currentTerm}</h2>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => window.print()}
            className="flex items-center gap-2 px-5 py-2 bg-[#2563eb] text-white rounded-md font-semibold hover:bg-blue-700 transition-colors shadow-sm"
          >
            <Printer size={18} />
            In Phiếu Điểm
          </button>
          <button 
            onClick={onClose}
            className="p-1.5 text-gray-500 hover:text-gray-800 hover:bg-gray-100 rounded-lg transition-all"
          >
            <X size={24} />
          </button>
        </div>
      </div>

      {/* Modal Body - Scrollable Container */}
      <div className="flex-1 overflow-auto p-4 md:p-10 flex justify-center bg-gray-200/50 custom-scrollbar">
        {/* Document Page (A4 Look) */}
        <div className="w-full max-w-[850px] bg-white shadow-2xl p-8 md:p-14 min-h-[1100px] text-gray-900 font-serif leading-relaxed print:shadow-none print:p-0">

          {/* Document Header Section */}
          <div className="text-center mb-8">
            <h1 className="text-xl md:text-2xl font-bold uppercase tracking-wide">PHIẾU ĐÁNH GIÁ HỌC TẬP {currentTerm.toUpperCase()}</h1>
            <p className="italic text-gray-600 font-sans text-sm">Năm học: 2025 - 2026</p>
            <div className="mt-4 text-right text-sm font-sans">
                Ngày xuất: {new Date().toLocaleDateString('vi-VN')}
            </div>
          </div>

          {/* Student Info Grid */}
          <div className="grid grid-cols-1 md:grid-cols-3 border border-gray-300 mb-8 text-[13px] font-sans bg-gray-50/30">
            <div className="p-3 border-r border-b border-gray-300 flex flex-col">
              <span className="text-[10px] uppercase text-gray-500 font-bold mb-1">Họ và tên học sinh</span>
              <span className="font-bold text-sm">{student.name}</span>
            </div>
            <div className="p-3 border-r border-b border-gray-300 flex flex-col">
              <span className="text-[10px] uppercase text-gray-500 font-bold mb-1">Lớp</span>
              <span className="font-bold text-sm">{className}</span>
            </div>
            <div className="p-3 border-b border-gray-300 flex flex-col">
