interface ReportPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  studentName?: string;
  currentTerm?: string;
}

const ReportPreviewModal: React.FC<ReportPreviewModalProps> = ({ isOpen, onClose, studentName, currentTerm = 'Cuối kỳ 1' }) => {
  if (!isOpen) return null;

  // Find the student to determine their class and data
  const student = STUDENTS_DATA.find(s => s.name === studentName) || STUDENTS_DATA[0];
  const className = student.className;
  const classSubjects = SUBJECTS_BY_CLASS[className] || SUBJECTS_BY_CLASS['1A2'];

  // Identify if we are in a Mid-term or End-term
  const isMidTerm = currentTerm.includes('Giữa');
  const termSuffix = currentTerm.includes('1') ? 'I' : 'II';

  // Helper to determine which subjects have numeric scores for a specific term
  const getScoredSubjectsForTerm = (cls: string, term: string) => {
    if (cls === '1A2') {
      if (term === 'Cuối kỳ 1' || term === 'Cuối năm') return ['Tiếng Việt', 'Toán'];
      return [];
    }
    if (cls === '5A2') {
      if (term === 'Giữa kỳ 1' || term === 'Giữa kỳ 2') return ['Tiếng Việt', 'Toán'];
      if (term === 'Cuối kỳ 1' || term === 'Cuối năm') return [
        'Tiếng Việt', 
        'Toán', 
        'Ngoại ngữ 1', 
        'Lịch sử và Địa lý', 
        'Khoa học', 
        'Tin học và Công nghệ'
      ];
    }
    return [];
  };

  // Deterministic value generator to ensure consistency across views
  const getDeterministicValue = (seed: string, offset: number, range: number) => {
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
      hash = (hash << 5) - hash + seed.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash + offset) % range;
  };

  const generateGradeData = (subjName: string) => {
    const seed = `${student.id}-${subjName}`;

    // We always calculate Mid-term values based on the "Mid-term" rule of the relevant semester
    const midTermName = currentTerm.includes('1') ? 'Giữa kỳ 1' : 'Giữa kỳ 2';
    const midTermScored = getScoredSubjectsForTerm(className, midTermName);

    // End-term scored subjects depend on the actual filter
    const endTermScored = getScoredSubjectsForTerm(className, isMidTerm ? (currentTerm.includes('1') ? 'Cuối kỳ 1' : 'Cuối năm') : currentTerm);

    const isMidScored = midTermScored.includes(subjName);
    const isEndScored = endTermScored.includes(subjName);

    // Levels (T: Hoàn thành tốt, H: Hoàn thành)
    const levels = ['T', 'H'];
    const m1 = levels[getDeterministicValue(seed, 10, 2)];
    const m2 = levels[getDeterministicValue(seed, 20, 2)];

    // Mid-term Score (d1): Consistent across all views
    const d1Value = (7.5 + getDeterministicValue(seed, 30, 25) / 10).toFixed(1);
    const d1 = isMidScored ? d1Value : '';

    // End-term Score (d2): Only visible in end-term reports
    const d2Value = (8.0 + getDeterministicValue(seed, 40, 20) / 10).toFixed(1);
    const d2 = (!isMidTerm && isEndScored) ? d2Value : '';

    return { m1, d1, m2, d2 };
  };

  const subjects = classSubjects.map((name, index) => {
    const grades = generateGradeData(name);
    return {
      stt: index + 1,
      name: name,
      ...grades,
      note: grades.m2 === 'T' ? 'Nắm vững kiến thức, kỹ năng môn học.' : 'Hoàn thành tốt các yêu cầu môn học.'
    };
  });

  return (
    <div className="fixed inset-0 z-[9999] flex flex-col bg-gray-500/40 backdrop-blur-sm overflow-hidden animate-in fade-in duration-200">
      {/* Modal Header Bar */}
      <div className="bg-white border-b border-gray-200 px-6 py-3 flex items-center justify-between shadow-md sticky top-0 z-10">
        <h2 className="text-gray-800 font-bold text-lg">Xem trước Phiếu điểm - {currentTerm}</h2>
        <div className="flex items-center gap-3">
