        <div className="w-full max-w-[850px] bg-white shadow-2xl p-8 md:p-14 min-h-[1100px] text-gray-900 font-serif leading-relaxed print:shadow-none print:p-0">

          {/* Document Header Section */}
          <div className="text-center mb-8">
            <h1 className="text-xl md:text-2xl font-bold uppercase tracking-wide">PHIẾU ĐÁNH GIÁ HỌC TẬP {currentTerm.toUpperCase()}</h1>
            <p className="italic text-gray-600 font-sans text-sm">Năm học: 2025 - 2026</p>
            <div className="mt-4 text-right text-sm font-sans">
                Ngày xuất: {new Date().toLocaleDateString('vi-VN')}
