import React from 'react';
import { X, Printer } from 'lucide-react';
import { SUBJECTS_BY_CLASS, STUDENTS_DATA } from '../constants';
import { Student } from '../types';

interface ReportPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedStudents?: Student[];
  currentTerm?: string;
}

const ReportPreviewModal: React.FC<ReportPreviewModalProps> = ({ 
  isOpen, 
  onClose, 
  selectedStudents = [], 
  currentTerm = 'Cuối kỳ 1' 
}) => {
  if (!isOpen) return null;

  // If no students provided (fallback to first student for safety)
  const displayStudents = selectedStudents.length > 0 ? selectedStudents : [STUDENTS_DATA[0]];

  // Identify if we are in a Mid-term or End-term
  const isMidTerm = currentTerm.includes('Giữa');
  const termSuffix = currentTerm.includes('1') ? 'I' : 'II';

  // Helper to determine which subjects have numeric scores for a specific term
  const getScoredSubjectsForTerm = (cls: string, term: string) => {
    if (cls === '1A2') {
      if (term === 'Cuối kỳ 1' || term === 'Cuối năm') return ['Tiếng Việt', 'Toán'];
      return [];
    }
    if (cls === '5A2') {
      if (term === 'Giữa kỳ 1' || term === 'Giữa kỳ 2') return ['Tiếng Việt', 'Toán'];
      if (term === 'Cuối kỳ 1' || term === 'Cuối năm') return [
        'Tiếng Việt', 
        'Toán', 
        'Ngoại ngữ 1', 
        'Lịch sử và Địa lý', 
        'Khoa học', 
        'Tin học và Công nghệ'
      ];
    }
    return [];
  };

  // Deterministic value generator to ensure consistency across views
  const getDeterministicValue = (seed: string, offset: number, range: number) => {
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
      hash = (hash << 5) - hash + seed.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash + offset) % range;
  };

  const generateGradeData = (student: Student, subjName: string) => {
    const seed = `${student.id}-${subjName}`;
    const midTermName = currentTerm.includes('1') ? 'Giữa kỳ 1' : 'Giữa kỳ 2';
    const midTermScored = getScoredSubjectsForTerm(student.className, midTermName);
    const endTermScored = getScoredSubjectsForTerm(student.className, isMidTerm ? (currentTerm.includes('1') ? 'Cuối kỳ 1' : 'Cuối năm') : currentTerm);

    const isMidScored = midTermScored.includes(subjName);
    const isEndScored = endTermScored.includes(subjName);

    const levels = ['T', 'H'];
    const m1 = levels[getDeterministicValue(seed, 10, 2)];
    const m2 = levels[getDeterministicValue(seed, 20, 2)];

    const d1Value = (7.5 + getDeterministicValue(seed, 30, 25) / 10).toFixed(1);
    const d1 = isMidScored ? d1Value : '';

    const d2Value = (8.0 + getDeterministicValue(seed, 40, 20) / 10).toFixed(1);
    const d2 = (!isMidTerm && isEndScored) ? d2Value : '';

    return { m1, d1, m2, d2 };
  };

  const renderStudentReport = (student: Student, index: number) => {
    const className = student.className;
    const classSubjects = SUBJECTS_BY_CLASS[className] || SUBJECTS_BY_CLASS['1A2'];

    const subjects = classSubjects.map((name, idx) => {
      const grades = generateGradeData(student, name);
      return {
        stt: idx + 1,
        name: name,
        ...grades,
        note: grades.m2 === 'T' ? 'Nắm vững kiến thức, kỹ năng môn học.' : 'Hoàn thành tốt các yêu cầu môn học.'
      };
    });

    return (
      <div key={student.id} className={`flex flex-col items-center w-full ${index > 0 ? 'print:break-before-page mt-12 pt-12 border-t-2 border-dashed border-gray-300 print:border-none print:mt-0 print:pt-0' : ''}`}>
        <div className="w-full max-w-[850px] bg-white shadow-2xl p-10 md:p-16 min-h-[1100px] text-gray-900 font-serif leading-relaxed print:shadow-none print:p-0">
          {/* Document Header Section */}
          <div className="text-center mb-12">
            <h2 className="text-sm md:text-base font-bold uppercase tracking-tight mb-0.5">SỞ GIÁO DỤC VÀ ĐÀO TẠO TP.HCM</h2>
            <h2 className="text-sm md:text-base font-bold uppercase tracking-tight border-b border-black inline-block px-4 pb-0.5 mb-8">TRƯỜNG TIỂU HỌC LAM SƠN</h2>

            <h1 className="text-2xl md:text-3xl font-bold uppercase tracking-wide mt-6 mb-2">PHIẾU BÁO KẾT QUẢ HỌC TẬP VÀ RÈN LUYỆN</h1>
            <p className="text-lg font-bold">Năm học: 2025 - 2026</p>
          </div>

          {/* Student Info Section */}
          <div className="mb-10 text-[16px] space-y-2">
            <div className="flex gap-2">
              <span className="font-bold whitespace-nowrap">Họ và tên học sinh:</span>
              <span className="border-b border-gray-400 border-dotted flex-1 pb-px">{student.name}</span>
            </div>
            <div className="flex gap-2 w-1/3">
              <span className="font-bold whitespace-nowrap">Lớp:</span>
              <span className="border-b border-gray-400 border-dotted flex-1 pb-px">{className}</span>
            </div>
          </div>

          <h3 className="font-bold text-sm mb-4 font-sans uppercase text-blue-800">I. Các môn học và hoạt động giáo dục</h3>

          <table className="w-full border-collapse border border-gray-800 text-[13px] font-sans mb-6">
            <thead>
              <tr className="bg-gray-100/50">
                <th rowSpan={2} className="border border-gray-800 p-2 text-center w-10">STT</th>
                <th rowSpan={2} className="border border-gray-800 p-2 text-left">Môn học và hoạt động giáo dục</th>
                <th colSpan={2} className="border border-gray-800 p-1 text-center bg-gray-100">Giữa học kỳ {termSuffix}</th>
                {!isMidTerm && (
                  <th colSpan={2} className="border border-gray-800 p-1 text-center bg-gray-100">Cuối học kỳ {termSuffix}</th>
                )}
                <th rowSpan={2} className={`border border-gray-800 p-2 text-center ${isMidTerm ? 'w-[45%]' : 'w-[25%]'}`}>Nhận xét: Điểm mạnh và các mặt cần rèn luyện</th>
              </tr>
              <tr className="bg-gray-100/50">
                <th className="border border-gray-800 p-1 text-center font-bold w-14 leading-tight">Mức</th>
                <th className="border border-gray-800 p-1 text-center font-bold w-14 leading-tight">Điểm</th>
                {!isMidTerm && (
                  <>
                    <th className="border border-gray-800 p-1 text-center font-bold w-14 leading-tight">Mức</th>
                    <th className="border border-gray-800 p-1 text-center font-bold w-14 leading-tight">Điểm</th>
                  </>
                )}
              </tr>
            </thead>
            <tbody>
              {subjects.map((sub) => (
                <tr key={sub.stt} className="hover:bg-gray-50/50">
                  <td className="border border-gray-800 p-1.5 text-center">{sub.stt}</td>
                  <td className="border border-gray-800 p-1.5 font-medium">{sub.name}</td>
                  <td className="border border-gray-800 p-1.5 text-center font-bold">{sub.m1}</td>
                  <td className="border border-gray-800 p-1.5 text-center font-bold text-blue-700">{sub.d1}</td>
                  {!isMidTerm && (
                    <>
                      <td className="border border-gray-800 p-1.5 text-center font-bold">{sub.m2}</td>
                      <td className="border border-gray-800 p-1.5 text-center font-bold text-blue-700">{sub.d2}</td>
                    </>
                  )}
                  <td className="border border-gray-800 p-1.5 text-[11px] align-top italic text-gray-700">{sub.note}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <div className="text-[11px] italic mb-10 font-sans flex gap-6 text-gray-600">
            <div><b>Mức đạt được:</b> T: Hoàn thành tốt, H: Hoàn thành, C: Chưa hoàn thành</div>
            <div><b>Điểm:</b> Chỉ áp dụng cho các môn kiểm tra định kỳ.</div>
          </div>

          <div className="mb-10 font-sans">
             <h3 className="font-bold text-sm mb-3 uppercase text-blue-800">II. Đánh giá phẩm chất và năng lực</h3>
             <div className="grid grid-cols-2 gap-4">
                <div className="border border-gray-300 p-3 rounded">
                   <div className="text-[10px] font-bold text-gray-500 uppercase mb-2">Năng lực cốt lõi</div>
                   <div className="text-sm">Xếp loại: <span className="font-bold">Tốt</span></div>
                   <div className="text-[11px] mt-1 text-gray-600 italic">Tự chủ, tự học và giao tiếp tốt.</div>
                </div>
                <div className="border border-gray-300 p-3 rounded">
                   <div className="text-[10px] font-bold text-gray-500 uppercase mb-2">Phẩm chất chủ yếu</div>
                   <div className="text-sm">Xếp loại: <span className="font-bold">Tốt</span></div>
                   <div className="text-[11px] mt-1 text-gray-600 italic">Chăm chỉ, trung thực, có trách nhiệm.</div>
                </div>
             </div>
          </div>

          <div className="grid grid-cols-2 gap-10 mt-20 text-center text-sm font-sans">
            <div className="flex flex-col items-center">
              <p className="italic mb-2 text-gray-500">.........., ngày ..... tháng ..... năm 2026</p>
              <p className="font-bold uppercase text-gray-800">PHỤ HUYNH HỌC SINH</p>
              <div className="h-28"></div>
              <p className="font-semibold text-gray-400 italic">(Ký và ghi rõ họ tên)</p>
            </div>
            <div className="flex flex-col items-center">
              <p className="italic mb-2 text-gray-500">TP.HCM, ngày {new Date().getDate()} tháng {new Date().getMonth() + 1} năm {new Date().getFullYear()}</p>
              <p className="font-bold uppercase text-gray-800">GIÁO VIÊN CHỦ NHIỆM</p>
              <div className="h-28"></div>
              <p className="font-bold text-gray-900 border-b border-gray-900 inline-block px-4">Nguyễn Thị Anh</p>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[9999] flex flex-col bg-gray-500/40 backdrop-blur-sm overflow-hidden animate-in fade-in duration-200">
      <div className="bg-white border-b border-gray-200 px-6 py-3 flex items-center justify-between shadow-md sticky top-0 z-10 print:hidden">
        <h2 className="text-gray-800 font-bold text-lg">Xem trước {displayStudents.length} Phiếu điểm - {currentTerm}</h2>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => window.print()}
            className="flex items-center gap-2 px-5 py-2 bg-[#2563eb] text-white rounded-md font-semibold hover:bg-blue-700 transition-colors shadow-sm"
          >
            <Printer size={18} />
            In Phiếu Điểm ({displayStudents.length})
          </button>
          <button 
            onClick={onClose}
            className="p-1.5 text-gray-500 hover:text-gray-800 hover:bg-gray-100 rounded-lg transition-all"
          >
            <X size={24} />
          </button>
        </div>
