          {/* Section II: Qualities and Competencies Table */}
          <div className="mb-10 font-sans">
             <h3 className="font-bold text-sm mb-3 uppercase text-blue-800">II. Đánh giá phẩm chất và năng lực</h3>

             <table className="w-full border-collapse border border-gray-800 text-[13px] font-sans">
