                  </tr>
                  {/* Core Competencies Rows */}
                  {CORE_COMPETENCIES.map((name, idx) => {
                      const { m1, m2, comment } = generateCompetencyData(student, name);
                      return (
                          <tr key={name} className="hover:bg-gray-50/50">
                              <td className="border border-gray-800 p-1.5 text-center text-gray-500 text-[11px]">1.{idx + 1}</td>
