                  })}

                  {/* Specific Competencies Header */}
                  <tr className="bg-gray-50 font-bold">
                      <td className="border border-gray-800 p-1.5 text-center">2</td>
                      <td colSpan={isMidTerm ? 3 : 4} className="border border-gray-800 p-1.5 uppercase text-xs">Năng lực đặc thù</td>
                  </tr>
                  {/* Specific Competencies Rows */}
                  {specificCompetencies.map((name, idx) => {
                      const { m1, m2, comment } = generateCompetencyData(student, name);
                      return (
                          <tr key={name} className="hover:bg-gray-50/50">
                              <td className="border border-gray-800 p-1.5 text-center text-gray-500 text-[11px]">2.{idx + 1}</td>
                              <td className="border border-gray-800 p-1.5 font-medium">{name}</td>
                              <td className="border border-gray-800 p-1.5 text-center font-bold">{m1}</td>
                              {!isMidTerm && <td className="border border-gray-800 p-1.5 text-center font-bold">{m2}</td>}
                              <td className="border border-gray-800 p-1.5 text-[11px] italic text-gray-700">{comment}</td>
