import React, { useState, useMemo, useEffect } from 'react';
import { X, Search } from 'lucide-react';
import { Student } from '../types';
import { STUDENTS_DATA } from '../constants';

interface StudentPrintSelectModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedClass: string;
  currentTerm?: string;
  onConfirm: (selectedStudents: Student[]) => void;
}

const StudentPrintSelectModal: React.FC<StudentPrintSelectModalProps> = ({ 
  isOpen, 
  onClose, 
  selectedClass, 
  currentTerm = 'Cuối kỳ 1',
  onConfirm 
}) => {
  // Initialize local state
  const [year, setYear] = useState('2025-2026');
  const [term, setTerm] = useState(currentTerm);
  const [grade, setGrade] = useState(() => selectedClass.startsWith('5') ? 'Khối 05' : 'Khối 01');
  const [filterClass, setFilterClass] = useState(selectedClass);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Sync state when modal opens or props change
  useEffect(() => {
    if (isOpen) {
      setTerm(currentTerm);
      setFilterClass(selectedClass);
      setGrade(selectedClass.startsWith('5') ? 'Khối 05' : 'Khối 01');
      setSearchTerm('');
      setSelectedIds(new Set());
    }
  }, [isOpen, selectedClass, currentTerm]);

  // Update Class selection when Grade changes
  const handleGradeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newGrade = e.target.value;
    setGrade(newGrade);
    // Simple logic to switch class based on grade for demo purposes
    if (newGrade === 'Khối 01') setFilterClass('1A2');
    else if (newGrade === 'Khối 05') setFilterClass('5A2');
    else setFilterClass(''); 
  };

  const filteredStudents = useMemo(() => {
    return STUDENTS_DATA.filter(s => 
      s.className === filterClass && 
      s.name.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [filterClass, searchTerm]);

  const toggleSelectAll = () => {
    if (selectedIds.size === filteredStudents.length && filteredStudents.length > 0) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(filteredStudents.map(s => s.id)));
    }
  };

  const toggleStudent = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedIds(newSet);
  };

  const handlePrint = () => {
    const selected = filteredStudents.filter(s => selectedIds.has(s.id));
    if (selected.length === 0) {
      alert('Vui lòng chọn ít nhất một học sinh để in.');
      return;
    }
    onConfirm(selected);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white rounded-lg shadow-2xl w-full max-w-5xl overflow-hidden flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="bg-[#4f46e5] px-6 py-3 flex items-center justify-between shrink-0">
          <h2 className="text-white font-semibold text-lg">In phiếu điểm</h2>
          <button onClick={onClose} className="text-white/80 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        {/* Content Section */}
        <div className="p-6 overflow-auto custom-scrollbar flex-1">
          {/* Filters Area */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
             <div className="flex flex-col gap-1.5">
                <label className="text-sm font-medium text-gray-700">Năm học</label>
                <select 
                  value={year}
                  onChange={(e) => setYear(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm outline-none"
                >
                   <option>2025-2026</option>
                   <option>2024-2025</option>
                </select>
             </div>
             <div className="flex flex-col gap-1.5">
                <label className="text-sm font-medium text-gray-700">Học kỳ</label>
                <select 
                  value={term}
                  onChange={(e) => setTerm(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm outline-none"
                >
                   <option>Giữa kỳ 1</option>
                   <option>Cuối kỳ 1</option>
                   <option>Giữa kỳ 2</option>
                   <option>Cuối năm</option>
                </select>
             </div>
             <div className="flex flex-col gap-1.5">
                <label className="text-sm font-medium text-gray-700">Khối</label>
                <select 
                  value={grade}
                  onChange={handleGradeChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm outline-none"
                >
                   <option value="Khối 01">Khối 01</option>
                   <option value="Khối 02">Khối 02</option>
                   <option value="Khối 03">Khối 03</option>
                   <option value="Khối 04">Khối 04</option>
                   <option value="Khối 05">Khối 05</option>
                </select>
             </div>
             <div className="flex flex-col gap-1.5">
                <label className="text-sm font-medium text-gray-700">Lớp</label>
                <select 
                  value={filterClass}
                  onChange={(e) => setFilterClass(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm outline-none"
                >
                   <option value="1A2">1A2</option>
                   <option value="5A2">5A2</option>
                </select>
             </div>
          </div>

          <div className="flex flex-col gap-1.5 mb-6">
            <label className="text-sm font-medium text-gray-700">Tìm kiếm theo tên</label>
            <div className="relative">
              <input 
                type="text"
