                         {group.items.map((name, idx) => {
                             const { m1, m2, comment } = generateCompetencyData(student, name);
                             return (
                                 <tr key={name} className="hover:bg-gray-50/50">
                                     <td className="border border-gray-800 p-1 text-center text-gray-500 text-[10px]">{group.startIdx}.{idx + 1}</td>
                                     <td className="border border-gray-800 p-1 font-medium">{name}</td>
                                     <td className="border border-gray-800 p-1 text-center font-bold">{m1}</td>
                                     {(!isMidTerm || isYearEnd) && <td className="border border-gray-800 p-1 text-center font-bold">{m2}</td>}
                                     <td className="border border-gray-800 p-1 text-[11px] italic text-gray-700">{comment}</td>
                                 </tr>
                             );
