                                         <>
                                            <td className="border border-gray-800 p-1 text-center font-bold">{isMidTerm ? gk1 : ck1}</td>
                                            {(!isMidTerm) && <td className="border border-gray-800 p-1 text-center font-bold">{cn}</td>}
