        "Có cố gắng trong học tập.",
        "Thực hiện đầy đủ yêu cầu."
      ];

      const isGood = getDeterministicValue(seed, 25, 10) > 3;
      const pool = isGood ? goodComments : avgComments;

      return pool[getDeterministicValue(seed, 42, pool.length)];
