                    </>
                ) : (
                    <>
                        <th className="border border-gray-800 p-1 text-center font-bold w-12 text-[11px]">Mức</th>
                        <th className="border border-gray-800 p-1 text-center font-bold w-12 text-[11px]">Điểm</th>
