                {isYearEnd ? (
                    <>
                        <th colSpan={2} className="border border-gray-800 p-1 text-center bg-gray-50">Giữa HK I</th>
                        <th colSpan={2} className="border border-gray-800 p-1 text-center bg-gray-100">Cuối HK I</th>
