                  Phẩm chất chủ yếu
                </th>
              )}

              {viewFilter === 'skills' && (
                <th colSpan={coreSkillCount + 2} className="px-4 py-3 text-center text-xs font-bold text-gray-700 uppercase tracking-wider bg-white border-r border-b border-gray-300">
                  Năng lực cốt lõi
                </th>
