                  )}
                  {isEndOfYearAll && (
                    <>
                       <th rowSpan={2} className="px-2 py-2 text-center text-xs font-bold text-gray-700 uppercase tracking-wider bg-white border-r border-b border-gray-300 min-w-[140px]">
                          Cuối năm
                       </th>
                       <th rowSpan={2} className="px-2 py-2 text-center text-xs font-bold text-gray-700 uppercase tracking-wider bg-white border-r border-b border-gray-300 min-w-[140px]">
                          Đột xuất
                       </th>
                    </>
                  )}
                </>
              )}

              {viewFilter === 'qualities' && (
                currentColumns.map((col, idx) => (
                  <th 
                    key={`quality-only-${idx}`}
                    rowSpan={2}
                    className="px-3 py-3 text-center text-xs font-bold uppercase tracking-wider min-w-[90px] bg-white border-r border-b border-gray-300 align-middle text-emerald-700"
                  >
                    <div className="leading-tight">{col.name}</div>
                    <div className="text-[10px] text-gray-500 font-normal mt-1 normal-case">Mức</div>
                  </th>
                ))
              )}

              {viewFilter === 'skills' && (
                <>
                  <th colSpan={4} className="px-4 py-2 text-center text-xs font-semibold text-gray-700 uppercase tracking-wider bg-white border-r border-b border-gray-300">
                    Năng lực chung
                  </th>
                  <th colSpan={specificSkillCount + 1} className="px-4 py-2 text-center text-xs font-semibold text-gray-700 uppercase tracking-wider bg-white border-r border-b border-gray-300">
                    Năng lực đặc thù
                  </th>
                </>
              )}
            </tr>

            <tr className="border-b-2 border-gray-400">
              {/* Row 3 for Split Headers */}
              {((viewFilter === 'all' || viewFilter === 'subjects') && isSplitActive) && (
                 classSubjects.map((name, idx) => {
                   if (splitSubjects.includes(name)) {
                     return (
                       <React.Fragment key={`sub-header-split-${idx}`}>
                         <th className="px-1 py-2 text-center text-[10px] font-bold text-gray-700 bg-white border-r border-b border-gray-300 min-w-[60px] leading-tight">Mức đạt được</th>
                         <th className="px-1 py-2 text-center text-[10px] font-bold text-gray-700 bg-white border-r border-b border-gray-300 min-w-[60px] leading-tight">Điểm KTĐK</th>
                       </React.Fragment>
                     );
                   }
                   return null;
                 })
              )}

              {(viewFilter === 'all' || viewFilter === 'skills') && (
                <>
                  {(viewFilter === 'all' ? currentColumns.slice(subjectCount + 5) : currentColumns).map((col, idx) => (
                    <th 
                      key={`label-${idx}`} 
                      className={`px-3 py-3 text-center text-xs font-bold uppercase tracking-wider ${col.isComment ? 'min-w-[220px]' : 'min-w-[90px]'} bg-white border-r border-b border-gray-300 text-amber-700`}
                    >
                      <div className="leading-tight">{col.name}</div>
                      {!col.isComment && <div className="text-[10px] text-gray-500 font-normal mt-1 normal-case">Mức</div>}
                    </th>
                  ))}
                </>
              )}
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {filteredStudents.map((student, studentIndex) => (
              <tr key={student.id} className="hover:bg-blue-50/30 transition-colors group">
                <td className="px-4 py-4 text-sm font-medium text-gray-900 sticky left-0 bg-white group-hover:bg-blue-50/30 transition-colors z-10 border-r border-gray-300 align-middle">{student.stt}</td>
                <td className="px-4 py-4 text-sm text-gray-700 sticky left-[50px] bg-white group-hover:bg-blue-50/30 transition-colors z-10 border-r border-gray-300 align-middle">{student.id}</td>
                <td className="px-4 py-4 text-sm font-semibold text-gray-900 sticky left-[150px] bg-white group-hover:bg-blue-50/30 transition-colors z-10 border-r border-gray-300 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)] align-middle">{student.name}</td>

                {/* Subject Body Cells Mapping */}
                {(viewFilter === 'all' || viewFilter === 'subjects') && classSubjects.map((name, idx) => {
                  const isSplit = splitSubjects.includes(name);

                  if (isSplit) {
                    const levels = ['T', 'H', 'C'];
                    const randomLevel = levels[Math.floor(Math.random() * levels.length)];
                    const randomScore = (Math.random() * 5 + 5).toFixed(1);

                    return (
                      <React.Fragment key={`body-split-${idx}`}>
                        <td className={`px-1 py-3 text-center text-sm font-medium text-gray-700 border-r border-gray-300 align-middle ${isLocked ? 'bg-gray-50' : ''}`}>
                          <span className={`inline-flex items-center justify-center w-7 h-7 rounded border border-gray-200 ${isLocked ? 'bg-gray-200 text-gray-500' : 'bg-gray-50'}`}>{randomLevel}</span>
                        </td>
                        <td className={`px-1 py-3 text-center text-sm font-bold border-r border-gray-300 align-middle ${isLocked ? 'text-gray-500 bg-gray-50' : 'text-blue-600'}`}>
                          {randomScore}
                        </td>
                      </React.Fragment>
                    );
                  } else {
                    return (
                      <td key={`body-normal-${idx}`} className={`px-2 py-3 text-center text-sm font-medium text-gray-700 border-r border-gray-300 align-middle ${isLocked ? 'bg-gray-50' : ''}`}>
                        <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg border border-gray-200 ${isLocked ? 'bg-gray-200 text-gray-500' : 'bg-gray-50'}`}>
                          {student.parent === 'T' ? 'T' : 'H'}
                        </span>
                      </td>
                    );
                  }
                })}

                {/* Qualities & Skills mapping in 'all' view */}
                {viewFilter === 'all' && currentColumns.slice(subjectCount).map((col, idx) => (
                  <td key={`all-view-extra-${idx}`} className={`px-2 py-3 text-center text-sm font-medium text-gray-700 border-r border-gray-300 ${col.isComment ? 'align-top' : 'align-middle'} ${isLocked ? 'bg-gray-50' : ''}`}>
                      {col.isComment ? (
                        <CommentInput placeholder="Nhận xét..." readOnly={isLocked} />
                      ) : (
                        <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg border border-gray-200 ${isLocked ? 'bg-gray-200 text-gray-500' : 'bg-gray-50'}`}>
                          Đ
                        </span>
                      )}
                  </td>
                ))}

                {/* Qualities or Skills mapping in specific views */}
                {(viewFilter === 'qualities' || viewFilter === 'skills') && currentColumns.map((col, idx) => (
                   <td key={`spec-view-cell-${idx}`} className={`px-2 py-3 text-center text-sm font-medium text-gray-700 border-r border-gray-300 ${col.isComment ? 'align-top' : 'align-middle'} ${isLocked ? 'bg-gray-50' : ''}`}>
                      {col.isComment ? (
                        <CommentInput placeholder="Nhận xét..." readOnly={isLocked} />
                      ) : (
                        <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg border border-gray-200 ${isLocked ? 'bg-gray-200 text-gray-500' : 'bg-gray-50'}`}>
                          Đ
                        </span>
                      )}
                  </td>
                ))}

                {isEndOfYearAll && (
                  <>
                    <td className={`px-2 py-3 text-center border-r border-gray-300 align-middle ${isLocked ? 'bg-gray-50' : ''}`}>
                      <span className={`font-bold text-sm ${isLocked ? 'text-gray-400' : 'text-red-500'}`}>
                        {['X', 'T', 'H', 'C', 'H'][studentIndex % 5]}
                      </span>
                    </td>
                    <td className={`px-2 py-3 text-center border-r border-gray-300 align-middle ${isLocked ? 'bg-gray-50' : ''}`}>
                      <RewardCell />
                    </td>
                    <td className={`px-2 py-3 text-center border-r border-gray-300 align-middle ${isLocked ? 'bg-gray-50' : ''}`}>
                      <RewardCell />
                    </td>
                    <td className={`px-2 py-3 text-center border-r border-gray-300 align-middle ${isLocked ? 'bg-gray-50' : ''}`}>
                      <div className="flex justify-center">
                         <input 
                            type="checkbox" 
                            disabled={isLocked}
                            className={`w-5 h-5 rounded border-gray-300 focus:ring-blue-500 ${isLocked ? 'text-gray-400 cursor-not-allowed' : 'text-blue-600 cursor-pointer'}`} 
                          />
                      </div>
                    </td>
                  </>
                )}

                {viewFilter !== 'skills' && (
                  <td className={`px-2 py-3 border-l border-gray-300 align-top ${isLocked ? 'bg-gray-50' : ''}`}>
                    <CommentInput initialValue={student.status} placeholder="Nhập nhận xét..." readOnly={isLocked} />
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default GradeTable;

import React, { useState, useRef, useEffect } from 'react';
import { ViewFilter, Student } from '../types';
import { STUDENTS_DATA } from '../constants';
import { ChevronDown, Printer, FileText, FileSpreadsheet, Lock, Unlock, AlertTriangle, CheckCircle, X } from 'lucide-react';
import ReportPreviewModal from './ReportPreviewModal';
import StudentPrintSelectModal from './StudentPrintSelectModal';

interface FilterBarProps {
  viewFilter: ViewFilter;
  setViewFilter: (filter: ViewFilter) => void;
  term: string;
  setTerm: (term: string) => void;
  selectedClass: string;
  setSelectedClass: (className: string) => void;
  isLocked?: boolean;
  setIsLocked?: (locked: boolean) => void;
}

const FilterBar: React.FC<FilterBarProps> = ({ 
  viewFilter, 
  setViewFilter, 
  term, 
  setTerm, 
  selectedClass, 
  setSelectedClass,
  isLocked = false,
  setIsLocked
}) => {
  const [showPrintDropdown, setShowPrintDropdown] = useState(false);
  const [isPrintSelectOpen, setIsPrintSelectOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [selectedStudents, setSelectedStudents] = useState<Student[]>([]);

  // Modal states
  const [showLockModal, setShowLockModal] = useState(false);
  const [showUnlockModal, setShowUnlockModal] = useState(false);

  const dropdownRef = useRef<HTMLDivElement>(null);

  const tabs: { label: string; value: ViewFilter }[] = [
    { value: 'all', label: 'Tất cả thông tin' },
    { value: 'skills', label: 'Năng lực' },
    { value: 'qualities', label: 'Phẩm chất' },
  ];

  const filteredStudents = STUDENTS_DATA.filter(s => s.className === selectedClass);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowPrintDropdown(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleConfirmStudents = (students: Student[]) => {
    if (students.length > 0) {
      setSelectedStudents(students);
      setIsPrintSelectOpen(false);
      setIsPreviewOpen(true);
    }
  };

  const handleLockClick = () => {
    setShowLockModal(true);
  };

  const confirmLock = () => {
    setIsLocked?.(true);
    setShowLockModal(false);
  };

  const handleUnlockClick = () => {
    // Logic gửi yêu cầu lên server sẽ ở đây
    setShowUnlockModal(true);
  };

  const closeUnlockModal = () => {
    setShowUnlockModal(false);
    // Giả lập admin duyệt yêu cầu mở khóa ngay lập tức để người dùng có thể test lại
    setIsLocked?.(false);
  };

  return (
    <div className="flex flex-col gap-5 mb-2 relative">
       {/* ROW 1: Filters (Left) & Print Dropdown (Right) */}
       <div className="flex flex-wrap items-end justify-between gap-4">
          {/* Filters Group */}
          <div className="flex flex-wrap gap-4">
              <div className="flex flex-col gap-1">
                <label className="text-xs font-semibold text-gray-600">Năm học</label>
                <select className="px-3 py-2 border border-gray-300 rounded bg-white text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 w-32 shadow-sm">
                   <option>2025-2026</option>
                   <option>2024-2025</option>
                </select>
              </div>
              <div className="flex flex-col gap-1">
                <label className="text-xs font-semibold text-gray-600">Học kỳ</label>
                <select 
                    className="px-3 py-2 border border-gray-300 rounded bg-white text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 w-40 shadow-sm"
                    value={term}
                    onChange={(e) => setTerm(e.target.value)}
                >
                   <option>Giữa kỳ 1</option>
                   <option>Cuối kỳ 1</option>
                   <option>Giữa kỳ 2</option>
                   <option>Cuối năm</option>
                </select>
              </div>
              <div className="flex flex-col gap-1">
                <label className="text-xs font-semibold text-gray-600">Tên lớp</label>
                <select 
                    className="px-3 py-2 border border-gray-300 rounded bg-white text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 w-24 shadow-sm"
                    value={selectedClass}
                    onChange={(e) => setSelectedClass(e.target.value)}
                >
                   <option value="1A2">1A2</option>
                   <option value="5A2">5A2</option>
                </select>
              </div>
          </div>

          {/* Right Side Actions */}
          <div className="flex items-center gap-2">
            {/* In Phieu Diem Button - Only visible in 'all' tab */}
            {viewFilter === 'all' && (
              <button 
                  onClick={() => setIsPrintSelectOpen(true)}
                  className="flex items-center gap-2 px-4 py-2 bg-white text-blue-600 border border-blue-600 rounded hover:bg-blue-50 transition-all shadow-sm text-sm font-medium"
              >
                  <Printer size={18} />
                  <span>In phiếu điểm</span>
              </button>
            )}

            {/* Print Dropdown Button */}
            <div className="relative" ref={dropdownRef}>
              <button 
                onClick={() => setShowPrintDropdown(!showPrintDropdown)}
                className="flex items-center gap-2 px-4 py-2 bg-white text-[#16a34a] border border-[#16a34a] rounded hover:bg-green-50 transition-all shadow-sm text-sm font-medium"
              >
                <Printer size={18} />
                <span>Xuất excel</span>
              </button>

            </div>
          </div>
       </div>

       {/* ROW 2: Tabs (Left) and Action Buttons (Right) */}
       <div className="flex flex-col md:flex-row justify-between items-end border-b border-gray-200">
          <div className="flex gap-6 overflow-x-auto no-scrollbar w-full md:w-auto -mb-[1px]">
            {tabs.map((tab) => (
                <button
                  key={tab.value}
                  onClick={() => setViewFilter(tab.value)}
                  className={`
                    pb-3 text-sm font-medium whitespace-nowrap border-b-2 transition-all
                    ${viewFilter === tab.value 
                      ? 'border-blue-600 text-blue-600' 
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'}
                  `}
                >
                  {tab.label}
                </button>
            ))}
          </div>

          <div className="flex gap-2 mb-3 overflow-x-auto w-full md:w-auto justify-start md:justify-end pt-2 md:pt-0">
             {viewFilter === 'all' && (
                <>
                    <button 
                        disabled={isLocked}
                        className={`px-4 py-2 text-white rounded font-medium transition-colors text-sm shadow-sm whitespace-nowrap ${isLocked ? 'bg-gray-400 cursor-not-allowed' : 'bg-[#22c55e] hover:bg-green-600'}`}
                    >
                        Đồng bộ điểm
                    </button>

                    {isLocked ? (
                      <button 
                          onClick={handleUnlockClick}
                          className="px-4 py-2 bg-amber-500 text-white rounded font-medium hover:bg-amber-600 transition-colors text-sm shadow-sm whitespace-nowrap flex items-center gap-2"
                      >
                          <Unlock size={16} />
                          Hủy chốt sổ
                      </button>
                    ) : (
                      <button 
                          onClick={handleLockClick}
                          className="px-4 py-2 bg-[#ef4444] text-white rounded font-medium hover:bg-red-600 transition-colors text-sm shadow-sm whitespace-nowrap flex items-center gap-2"
                      >
                          <Lock size={16} />
                          Chốt sổ
                      </button>
                    )}
                </>
             )}
             <button className="px-4 py-2 bg-[#6366f1] text-white rounded font-medium hover:bg-indigo-600 transition-colors text-sm shadow-sm whitespace-nowrap">
                Lịch sử chỉnh sửa
             </button>
             <button 
                disabled={isLocked}
                className={`px-6 py-2 text-white rounded font-medium transition-colors text-sm shadow-sm whitespace-nowrap ${isLocked ? 'bg-gray-400 cursor-not-allowed' : 'bg-[#6366f1] hover:bg-indigo-600'}`}
             >
                Lưu
             </button>
          </div>
       </div>

       {/* ROW 3: Stats and Notes */}
       <div className="mt-2 text-sm flex justify-between items-start">
          <div>
            <div className="font-bold text-gray-800">Số học sinh: {filteredStudents.length}</div>
            <div className="text-red-500 text-xs mt-1">
               ( Thầy Cô nhấn vào tab Năng lực hoặc Phẩm chất để nhập đánh giá và nhận xét)
            </div>
            <div className="text-red-500 text-xs">
               ( Thầy Cô nhấn vào tab Tất cả thông tin để nhập Nhận xét/ Nhận xét in học bạ và thực hiện Chốt sổ / Đồng bộ điểm )
            </div>
          </div>
          {isLocked && (
            <div className="px-3 py-1 bg-red-100 text-red-700 rounded border border-red-200 text-xs font-bold flex items-center gap-1">
              <Lock size={12} />
              Sổ đã chốt - Không thể chỉnh sửa
            </div>
          )}
       </div>

       {/* Selection Modal */}
       <StudentPrintSelectModal 
          isOpen={isPrintSelectOpen}
          onClose={() => setIsPrintSelectOpen(false)}
          selectedClass={selectedClass}
          onConfirm={handleConfirmStudents}
          term={term}
          onTermChange={setTerm}
       />

       {/* Preview Modal */}
       <ReportPreviewModal 
          isOpen={isPreviewOpen} 
          onClose={() => {
            setIsPreviewOpen(false);
            setIsPrintSelectOpen(true);
          }} 
          selectedStudents={selectedStudents}
          currentTerm={term}
       />

        {/* Lock Confirmation Modal */}
        {showLockModal && (
           <div className="fixed inset-0 z-[1001] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
             <div className="bg-white rounded-lg shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100">
               <div className="p-6 text-center">
                 <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                   <AlertTriangle className="text-red-600" size={32} />
                 </div>
                 <h3 className="text-lg font-bold text-gray-900 mb-2">Xác nhận chốt sổ</h3>
                 <p className="text-gray-600 text-sm mb-6">
                   Bạn có chắc chắn muốn chốt sổ điểm này không? Sau khi chốt, bạn và các giáo viên khác sẽ <span className="font-bold text-red-600">không thể chỉnh sửa</span> dữ liệu cho đến khi mở khóa lại.
                 </p>
                 <div className="flex gap-3 justify-center">
                   <button 
                     onClick={() => setShowLockModal(false)}
                     className="px-4 py-2 bg-gray-100 text-gray-700 rounded hover:bg-gray-200 transition-colors text-sm font-medium"
                   >
                     Hủy bỏ
                   </button>
                   <button 
                     onClick={confirmLock}
                     className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 transition-colors text-sm font-medium"
                   >
                     Đồng ý chốt sổ
                   </button>
                 </div>
               </div>
             </div>
           </div>
        )}

        {/* Unlock Request Success Modal */}
        {showUnlockModal && (
           <div className="fixed inset-0 z-[1001] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
             <div className="bg-white rounded-lg shadow-2xl w-full max-w-sm overflow-hidden transform transition-all scale-100">
               <div className="bg-amber-500 h-2 w-full"></div>
               <div className="p-6 text-center">
                 <div className="flex justify-end absolute top-3 right-3">
                    <button onClick={closeUnlockModal} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                 </div>
                 <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                   <CheckCircle className="text-green-600" size={32} />
                 </div>
                 <h3 className="text-lg font-bold text-gray-900 mb-2">Thành công</h3>
                 <p className="text-gray-700 font-medium mb-6">
                   Đã gửi yêu cầu hủy chốt sổ.
                 </p>
                 <button 
                   onClick={closeUnlockModal}
                   className="w-full px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-sm font-medium"
                 >
                   Đóng
                 </button>
               </div>
             </div>
           </div>
        )}
    </div>
  );
};

