                <button 
                    className="px-4 py-2 bg-[#22c55e] text-white rounded font-medium hover:bg-green-600 transition-colors text-sm shadow-sm whitespace-nowrap"
                >
                    Đồng bộ điểm
                </button>
             )}
             <button className="px-4 py-2 bg-[#6366f1] text-white rounded font-medium hover:bg-indigo-600 transition-colors text-sm shadow-sm whitespace-nowrap">
                Lịch sử chỉnh sửa
             </button>
             <button 
                className="px-6 py-2 bg-[#6366f1] text-white rounded font-medium hover:bg-indigo-600 transition-colors text-sm shadow-sm whitespace-nowrap"
             >
                Lưu
             </button>
          </div>
       </div>

       {/* ROW 3: Stats and Notes */}
       <div className="mt-2 text-sm flex justify-between items-start">
          <div>
            <div className="font-bold text-gray-800">Số học sinh: {filteredStudents.length}</div>
            <div className="text-red-500 text-xs mt-1">
               ( Thầy Cô nhấn vào tab Năng lực hoặc Phẩm chất để nhập đánh giá và nhận xét)
            </div>
            <div className="text-red-500 text-xs">
               ( Thầy Cô nhấn vào tab Tất cả thông tin để nhập Nhận xét/ Nhận xét in học bạ và thực hiện Chốt sổ / Đồng bộ điểm )
            </div>
          </div>
       </div>

       {/* Selection Modal */}
       <StudentPrintSelectModal 
          isOpen={isPrintSelectOpen}
          onClose={() => setIsPrintSelectOpen(false)}
          selectedClass={selectedClass}
          onConfirm={handleConfirmStudents}
          term={term}
          onTermChange={setTerm}
       />

       {/* Preview Modal */}
       <ReportPreviewModal 
          isOpen={isPreviewOpen} 
          onClose={() => {
            setIsPreviewOpen(false);
            setIsPrintSelectOpen(true);
          }} 
          selectedStudents={selectedStudents}
          currentTerm={term}
       />
    </div>
  );
};

export default FilterBar;

import React from 'react';
import { STUDENTS_DATA, SUBJECTS_BY_CLASS } from '../constants';
import { ViewFilter } from '../types';
import CommentInput from './CommentInput';

interface GradeTableProps {
  viewFilter: ViewFilter;
  term: string;
  selectedClass: string;
}

interface ColumnDef {
  name: string;
  group: 'subjects' | 'qualities' | 'skills';
  subgroup: 'common' | 'specific' | null;
  isComment?: boolean;
}

const GradeTable: React.FC<GradeTableProps> = ({ viewFilter, term, selectedClass }) => {
  const filteredStudents = STUDENTS_DATA.filter(s => s.className === selectedClass);
  const classSubjects = SUBJECTS_BY_CLASS[selectedClass] || SUBJECTS_BY_CLASS['1A2'];

  // Determine split subjects based on class and term
  const getSplitSubjects = () => {
    if (selectedClass === '1A2' && term === 'Cuối kỳ 1') {
      return ['Tiếng Việt', 'Toán'];
    }
    if (selectedClass === '5A2') {
      if (term === 'Giữa kỳ 1') return ['Tiếng Việt', 'Toán'];
      if (term === 'Cuối kỳ 1') return [
        'Tiếng Việt', 
        'Toán', 
        'Ngoại ngữ 1', 
        'Lịch sử và Địa lý', 
        'Khoa học', 
        'Tin học và Công nghệ'
      ];
    }
    return [];
  };

  const splitSubjects = getSplitSubjects();
  const isSplitActive = splitSubjects.length > 0;

  const commonSkills: ColumnDef[] = [
    { name: 'Tự chủ và tự học', group: 'skills', subgroup: 'common' },
    { name: 'Giao tiếp và hợp tác', group: 'skills', subgroup: 'common' },
    { name: 'Giải quyết vấn đề và sáng tạo', group: 'skills', subgroup: 'common' },
