                    >
                        Đồng bộ điểm
                    </button>

                    {isLocked ? (
                      <button 
                          onClick={handleUnlockClick}
                          className="px-4 py-2 bg-amber-500 text-white rounded font-medium hover:bg-amber-600 transition-colors text-sm shadow-sm whitespace-nowrap flex items-center gap-2"
