               <div className="p-8 flex flex-col items-center">
                 {/* Icon */}
                 <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center mb-4">
                    <LockOpen className="text-red-700" size={32} strokeWidth={1.5} />
