                    <LockOpen className="text-red-700" size={32} strokeWidth={1.5} />
                 </div>

                 {/* Title */}
                 <h3 className="text-xl font-bold text-red-900 mb-2 uppercase tracking-wide">YÊU CẦU MỞ KHÓA</h3>

                 {/* Context Info */}
