                     Hủy bỏ
                   </button>
                   <button 
                     onClick={handleSendUnlockRequest}
                     className="flex-1 py-2.5 bg-[#85b995] text-white rounded-lg hover:bg-[#6da880] transition-colors text-sm font-bold shadow-sm"
