                     Gửi yêu cầu
                   </button>
                 </div>
               </div>
             </div>
           </div>
        )}

        {/* 2. Unlock Request Success Modal */}
        {showUnlockSuccessModal && (
           <div className="fixed inset-0 z-[1002] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
