                 <span className="p-1.5 bg-slate-800/50 rounded-md border border-slate-700/50 text-blue-400">
                    {group.icon}
                 </span>
                 <span className="text-xs font-bold uppercase tracking-wider">{group.title}</span>
              </div>

              {/* Items Container with Guideline */}
              <div className="relative ml-5 pl-4 border-l border-slate-700/50 space-y-1">
                {group.items.map((item) => {
                  const isActive = activePage === item.id;
                  return (
                    <button
                      key={item.id}
                      onClick={() => {
                          setActivePage(item.id);
                          if (window.innerWidth < 1024) setIsCollapsed(true);
                      }}
                      className={`group w-full flex items-center text-left py-2.5 px-3 rounded-md transition-all duration-200 text-sm font-medium leading-5 relative
                        ${isActive 
                          ? 'bg-blue-600 text-white shadow-md shadow-blue-900/20' 
                          : 'text-slate-400 hover:text-slate-100 hover:bg-slate-800/60'
                        }`}
                    >
                      {/* Active Indicator Line (Left border effect) - Optional visual flair */}
                      {isActive && (
                        <span className="absolute -left-[17px] top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.6)]"></span>
                      )}

                      {/* Hover dot for non-active items */}
                      {!isActive && (
                         <span className="absolute -left-[17px] top-1/2 -translate-y-1/2 w-1.5 h-1.5 rounded-full bg-slate-600 opacity-0 group-hover:opacity-100 transition-opacity"></span>
                      )}

                      <span>{item.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </nav>

        {/* Bottom Footer (Optional) */}
        <div className="absolute bottom-0 left-0 right-0 p-4 border-t border-slate-800 bg-[#0f172a] text-center">
            <p className="text-[10px] text-slate-600">Phiên bản 2.0.5</p>
        </div>
      </div>

      {/* Overlay for mobile */}
      {!isCollapsed && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-[2px] z-40 lg:hidden transition-opacity duration-300"
          onClick={() => setIsCollapsed(true)}
        />
      )}
    </>
  );
};

