                   onClick={handleCloseSuccessModal}
                   className="px-10 py-3 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-base font-bold min-w-[140px]"
                 >
                   OK
                 </button>
             </div>
           </div>
        )}
    </div>
  );
};

