                              </p>
                           </div>
                        </td>
                    </tr>
                  )}
               </tbody>
            </table>
         </div>
      </div>

      {/* Import Modal */}
      <CommentBankImportModal 
        isOpen={showImportModal}
        onClose={() => setShowImportModal(false)}
        importData={importData}
        onConfirm={handleConfirmImport}
        isLoading={isImporting}
      />

    </div>
  );
};

