  const [newContent, setNewContent] = useState('');

  // Inline Edit State
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editLevel, setEditLevel] = useState<'T' | 'H' | 'C'>('T');
  const [editContent, setEditContent] = useState('');

  // Dummy Data State
  const [comments, setComments] = useState<CommentItem[]>([
    { id: 1, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'T', content: 'Em tính toán nhanh, chính xác, hiểu bài tốt.' },
    { id: 2, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'H', content: 'Em nắm được kiến thức cơ bản, cần cẩn thận hơn khi tính toán.' },
    { id: 3, grade: 'Khối 04', subject: 'Tiếng Việt', term: 'Cuối kỳ 1', level: 'T', content: 'Đọc to, rõ ràng, diễn cảm. Chữ viết đẹp.' },
    { id: 4, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'T', content: 'Vocabulary retention is excellent. Participates actively.' },
    { id: 5, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'H', content: 'Good effort in speaking activities. Needs to work on spelling.' },
    { id: 6, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'C', content: 'Cần ôn lại bảng cửu chương.' },
  ]);

  // Import/Export States
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showImportModal, setShowImportModal] = useState(false);
  const [importData, setImportData] = useState<ImportRow[]>([]);
  const [isImporting, setIsImporting] = useState(false);

  // --- DERIVED STATE & EFFECTS ---

  // Get available Grades based on User Assignments
  const availableGrades = useMemo(() => {
    return Object.keys(currentUser.assignments).sort();
  }, [currentUser]);

  // Update Subject List when Grade Changes
  const availableSubjects = useMemo(() => {
    if (!selectedGrade) return [];
    return currentUser.assignments[selectedGrade] || [];
  }, [selectedGrade, currentUser]);

  // Auto-select Grade if user only has 1
  useEffect(() => {
    if (availableGrades.length > 0 && !availableGrades.includes(selectedGrade)) {
        setSelectedGrade(availableGrades[0]);
    }
  }, [availableGrades]);

  // Auto-select Subject if only 1 exists for the grade
  useEffect(() => {
    if (availableSubjects.length > 0) {
        // If current subject is not in the new list, select the first one
        if (!availableSubjects.includes(selectedSubject)) {
            setSelectedSubject(availableSubjects[0]);
        }
    } else {
        setSelectedSubject('');
    }
  }, [availableSubjects, selectedGrade]);


  // Filter AND Sort Comments
  const processedComments = useMemo(() => {
    // 1. Filter
    const filtered = comments.filter(c => {
        const matchGrade = c.grade === selectedGrade;
        const matchSubject = c.subject === selectedSubject;
        // In real app, match Term too if needed, here strict matching grade/subject
        const matchSearch = c.content.toLowerCase().includes(searchTerm.toLowerCase());
        return matchGrade && matchSubject && matchSearch;
    });

    // 2. Sort Logic
    // Priority 1: Level (T -> H -> C)
    // Priority 2: ID Descending (Newest first)
    return filtered.sort((a, b) => {
        const levelPriority: Record<string, number> = { 'T': 1, 'H': 2, 'C': 3 };

        const priorityA = levelPriority[a.level] || 4;
        const priorityB = levelPriority[b.level] || 4;

        if (priorityA !== priorityB) {
            return priorityA - priorityB; // Ascending priority (1, 2, 3)
        }

        // If levels are same, sort by ID descending (newest first)
        return b.id - a.id;
    });
  }, [comments, selectedGrade, selectedSubject, searchTerm]);

  // --- HANDLERS ---

  const handleDownloadTemplate = () => {
    const fileName = `Mau_Nhan_Xet_${currentUser.name.replace(/\s/g, '_')}_${selectedGrade}.xlsx`;
    alert(`Đang tải xuống file mẫu: ${fileName}\n\n(File này sẽ được điền sẵn thông tin:\nKhối: ${selectedGrade}\nMôn: ${selectedSubject}\nHọc kỳ: ${term})`);
  };

  const handleTriggerUpload = () => {
    if (fileInputRef.current) {
        fileInputRef.current.value = ''; // Reset
        fileInputRef.current.click();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const mockParsedRows: ImportRow[] = [];

      for (let i = 0; i < 50; i++) {
          const hasData = i < 5 || (i > 10 && i < 13);
          const isError = i === 12;

          const grade = selectedGrade;
          const subject = selectedSubject;
          const t = term;

          let level = '';
          let content = '';

          if (hasData) {
              level = i % 2 === 0 ? 'T' : 'H';
              content = `Nhận xét mẫu import dòng số ${i+1} cho môn ${subject}`;

              if (isError) {
                  level = 'T';
                  content = '';
              }
          }

          if (!level && !content) continue;

          let isValid = true;
          let error = '';

          if (level && !content) {
              isValid = false;
              error = 'Thiếu nội dung nhận xét';
          } else if (!level && content) {
               isValid = false;
               error = 'Thiếu mức độ (T/H/C)';
          }

          mockParsedRows.push({
              index: i,
              grade,
              subject,
              term: t,
              level,
              content,
              isValid,
              error
          });
      }

      setImportData(mockParsedRows);
      setShowImportModal(true);
  };

  const handleConfirmImport = () => {
      setIsImporting(true);
      setTimeout(() => {
          const newComments = importData
            .filter(r => r.isValid)
            .map((r, idx) => ({
                id: Date.now() + idx,
                grade: r.grade,
                subject: r.subject,
                term: r.term,
                level: r.level as any,
                content: r.content
            }));

          setComments([...newComments, ...comments]);
          setIsImporting(false);
          setShowImportModal(false);
      }, 1000);
  };

  // --- INLINE ADD HANDLERS ---
  const handleAddNewClick = () => {
    // If we are adding new, close edit mode if open
    setEditingId(null);
    setIsAddingNew(true);
    setNewLevel('T');
    setNewContent('');
  };

  const handleSaveNew = () => {
    if (!newContent.trim()) {
      alert("Vui lòng nhập nội dung nhận xét");
      return;
    }
    const newId = Date.now();
    const newComment: CommentItem = {
      id: newId,
      grade: selectedGrade,
      subject: selectedSubject,
      term: term,
      level: newLevel,
      content: newContent
    };

    setComments([newComment, ...comments]); 
    setIsAddingNew(false);
  };

  // --- INLINE EDIT HANDLERS ---
  const handleEditClick = (comment: CommentItem) => {
    // If adding new, close it
    setIsAddingNew(false);

    setEditingId(comment.id);
    setEditLevel(comment.level);
    setEditContent(comment.content);
  };

  const handleUpdateComment = () => {
     if (!editContent.trim()) {
        alert("Vui lòng nhập nội dung nhận xét");
        return;
     }

     setComments(prevComments => prevComments.map(c => 
        c.id === editingId 
        ? { ...c, level: editLevel, content: editContent }
        : c
     ));

     setEditingId(null);
  };

  const handleCancelEdit = () => {
     setEditingId(null);
  };

  const handleDelete = (id: number) => {
    if (confirm('Bạn có chắc chắn muốn xóa nhận xét này?')) {
        setComments(comments.filter(c => c.id !== id));
        if (editingId === id) {
            setEditingId(null);
        }
    }
  };

  return (
    <div className="flex flex-col h-full bg-gray-50/50">

      {/* 1. Header & Configuration */}
      <div className="bg-white border-b border-gray-200 p-6 shadow-sm">
         <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
             <div>
                <h1 className="text-2xl font-bold text-gray-800">Ngân hàng Nhận xét Cá nhân</h1>
                <p className="text-sm text-gray-500 mt-1">Quản lý kho nhận xét mẫu cho <span className="font-semibold text-blue-700">{currentUser.name}</span></p>
             </div>
             <div className="flex items-center gap-3 bg-blue-50 px-4 py-2 rounded-lg border border-blue-100">
                <span className="text-sm font-medium text-blue-800">Ưu tiên nguồn gợi ý:</span>
                <button 
                    onClick={() => setUseSystemBank(!useSystemBank)}
                    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${useSystemBank ? 'bg-gray-300' : 'bg-blue-600'}`}
                >
                    <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${useSystemBank ? 'translate-x-1' : 'translate-x-6'}`} />
                </button>
                <span className={`text-sm font-bold ${!useSystemBank ? 'text-blue-700' : 'text-gray-500'}`}>Cá nhân</span>
                <span className="text-gray-300">|</span>
                <span className={`text-sm font-bold ${useSystemBank ? 'text-gray-700' : 'text-gray-400'}`}>Hệ thống</span>
             </div>
         </div>

         {/* Filters */}
         <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Năm học</label>
               <select className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                  <option>2025-2026</option>
                  <option>2024-2025</option>
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Khối lớp</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedGrade}
                 onChange={(e) => setSelectedGrade(e.target.value)}
               >
                  {availableGrades.map(g => <option key={g} value={g}>{g}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Môn học</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedSubject}
                 onChange={(e) => setSelectedSubject(e.target.value)}
               >
                  {availableSubjects.map(s => <option key={s} value={s}>{s}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Học kỳ</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                 value={term}
                 onChange={(e) => setTerm(e.target.value)}
               >
                  <option>Giữa kỳ 1</option>
                  <option>Cuối kỳ 1</option>
                  <option>Giữa kỳ 2</option>
                  <option>Cuối năm</option>
               </select>
            </div>
         </div>
      </div>

      {/* 2. Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row justify-between items-center gap-4">
         {/* Search */}
         <div className="relative w-full md:w-96">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Tìm kiếm nội dung nhận xét..."
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-full focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
         </div>

         {/* Actions */}
         <div className="flex items-center gap-3 w-full md:w-auto">
             <button 
                onClick={handleDownloadTemplate}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-50 transition-colors whitespace-nowrap"
             >
                <Download size={16} />
                <span>Tải file mẫu</span>
             </button>
             <button 
                onClick={handleTriggerUpload}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Upload size={16} />
                <span>Tải lên & Cập nhật</span>
             </button>
             <input type="file" ref={fileInputRef} className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />

             <button 
                onClick={handleAddNewClick}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Plus size={16} />
                <span>Thêm mới</span>
             </button>
         </div>
      </div>

      {/* 3. Data Table */}
      <div className="flex-1 overflow-auto custom-scrollbar px-6 pb-6">
         <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden min-h-[400px]">
            <table className="w-full text-left border-collapse">
               <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold sticky top-0 z-10">
                  <tr>
                     <th className="px-6 py-4 w-16 text-center border-b">STT</th>
                     <th className="px-6 py-4 w-32 border-b">Mức độ</th>
                     <th className="px-6 py-4 border-b">Nội dung nhận xét</th>
                     <th className="px-6 py-4 w-32 text-center border-b">Hành động</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-gray-100">
                  {/* INLINE ADD ROW - ALWAYS AT TOP */}
                  {isAddingNew && (
                    <tr className="bg-blue-50 animate-in fade-in slide-in-from-top-2 duration-300 border-b border-blue-100 shadow-inner">
                      <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">#</td>
                      <td className="px-6 py-4">
                          <select 
                            className="w-full p-2 border border-gray-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                            value={newLevel}
                            onChange={(e) => setNewLevel(e.target.value as any)}
                          >
                            <option value="T">T</option>
                            <option value="H">H</option>
                            <option value="C">C</option>
                          </select>
                      </td>
                      <td className="px-6 py-4">
                          <input 
                            type="text"
                            autoFocus
                            className="w-full p-2 border border-blue-300 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white placeholder-gray-400 font-medium"
                            placeholder="Nhập nội dung nhận xét..."
                            value={newContent}
                            onChange={(e) => setNewContent(e.target.value)}
                            onKeyDown={(e) => {
                                if(e.key === 'Enter') handleSaveNew();
                                if(e.key === 'Escape') setIsAddingNew(false);
                            }}
                          />
                      </td>
                      <td className="px-6 py-4 text-center">
                          <div className="flex items-center justify-center gap-2">
                              <button onClick={handleSaveNew} className="p-2 text-white bg-green-500 hover:bg-green-600 rounded-lg transition-colors shadow-sm" title="Lưu">
                                  <Check size={16} />
                              </button>
                              <button onClick={() => setIsAddingNew(false)} className="p-2 text-gray-600 bg-white border border-gray-300 hover:bg-gray-100 rounded-lg transition-colors shadow-sm" title="Hủy">
                                  <X size={16} />
                              </button>
                          </div>
                      </td>
                    </tr>
                  )}

                  {processedComments.length > 0 ? (
                    processedComments.map((comment, index) => {
                      const isEditing = comment.id === editingId;

                      if (isEditing) {
                          return (
                              <tr key={comment.id} className="bg-yellow-50 border-b border-yellow-100 animate-in fade-in">
                                  <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                                  <td className="px-6 py-4">
                                      <select 
                                        className="w-full p-2 border border-gray-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-yellow-500 outline-none bg-white text-gray-700"
                                        value={editLevel}
                                        onChange={(e) => setEditLevel(e.target.value as any)}
                                      >
                                        <option value="T">T</option>
                                        <option value="H">H</option>
                                        <option value="C">C</option>
                                      </select>
                                  </td>
                                  <td className="px-6 py-4">
                                      <input 
                                        type="text"
                                        autoFocus
                                        className="w-full p-2 border border-yellow-300 rounded-md text-sm focus:ring-2 focus:ring-yellow-500 outline-none bg-white font-medium"
                                        value={editContent}
                                        onChange={(e) => setEditContent(e.target.value)}
                                        onKeyDown={(e) => {
                                            if(e.key === 'Enter') handleUpdateComment();
                                            if(e.key === 'Escape') handleCancelEdit();
                                        }}
                                      />
                                  </td>
                                  <td className="px-6 py-4 text-center">
                                      <div className="flex items-center justify-center gap-2">
                                          <button 
                                            onClick={handleUpdateComment} 
                                            className="p-2 text-white bg-green-500 hover:bg-green-600 rounded-lg transition-colors shadow-sm"
                                            title="Lưu thay đổi"
                                          >
                                              <Save size={16} />
                                          </button>
                                          <button 
                                            onClick={handleCancelEdit} 
                                            className="p-2 text-gray-600 bg-white border border-gray-300 hover:bg-gray-100 rounded-lg transition-colors shadow-sm"
                                            title="Hủy bỏ"
                                          >
                                              <X size={16} />
                                          </button>
                                      </div>
                                  </td>
                              </tr>
                          );
                      }

                      return (
                        <tr key={comment.id} className="hover:bg-blue-50/50 transition-colors group">
                           <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                           <td className="px-6 py-4">
                              <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg text-sm font-bold border ${
                                comment.level === 'T' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                comment.level === 'H' ? 'bg-cyan-50 text-cyan-700 border-cyan-200' :
                                'bg-orange-50 text-orange-700 border-orange-200'
                              }`}>
                                 {comment.level}
                              </span>
                           </td>
                           <td className="px-6 py-4 text-sm text-gray-800 leading-relaxed font-medium">
                              {comment.content}
                           </td>
                           <td className="px-6 py-4 text-center">
                              <div className="flex items-center justify-center gap-2">
                                 <button 
                                    onClick={() => handleEditClick(comment)}
                                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                    title="Chỉnh sửa"
                                 >
                                    <Edit size={16} />
                                 </button>
                                 <button 
                                    onClick={() => handleDelete(comment.id)}
                                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Xóa"
                                 >
                                    <Trash2 size={16} />
                                 </button>
                              </div>
                           </td>
                        </tr>
                      );
                    })
                  ) : (
                    !isAddingNew && (
                        <tr>
                            <td colSpan={4} className="px-6 py-20 text-center">
                            <div className="flex flex-col items-center justify-center text-gray-400">
                                <Info size={48} className="mb-4 text-gray-300" />
                                <p className="text-lg font-medium text-gray-500">Chưa có dữ liệu nhận xét</p>
                                <p className="text-sm mt-1 max-w-sm mx-auto">
                                    Vui lòng "Thêm mới" hoặc sử dụng chức năng "Tải lên" để nhập dữ liệu từ Excel cho môn <span className="font-bold text-gray-600">{selectedSubject}</span>.
                                </p>
                            </div>
                            </td>
                        </tr>
                    )
                  )}
               </tbody>
            </table>
         </div>
      </div>

      {/* Import Modal */}
      <CommentBankImportModal 
        isOpen={showImportModal}
        onClose={() => setShowImportModal(false)}
        importData={importData}
        onConfirm={handleConfirmImport}
        isLoading={isImporting}
      />

    </div>
  );
};

export default CommentBank;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserConfig, CommentItem, ImportRow } from '../types';
import { Download, Upload, Search, Trash2, Edit, Plus, Info, Check, X, Save } from 'lucide-react';
import CommentBankImportModal from './CommentBankImportModal';

interface CommentBankProps {
  currentUser: UserConfig;
}

const CommentBank: React.FC<CommentBankProps> = ({ currentUser }) => {
  // --- STATE ---
  const [selectedGrade, setSelectedGrade] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>('');
  const [term, setTerm] = useState('Cuối kỳ 1');
  const [useSystemBank, setUseSystemBank] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Inline Add State
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [newLevel, setNewLevel] = useState<'T' | 'H' | 'C'>('T');
  const [newContent, setNewContent] = useState('');

  // Inline Edit State
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editLevel, setEditLevel] = useState<'T' | 'H' | 'C'>('T');
  const [editContent, setEditContent] = useState('');

  // Dummy Data State
  const [comments, setComments] = useState<CommentItem[]>([
    { id: 1, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'T', content: 'Em tính toán nhanh, chính xác, hiểu bài tốt.' },
    { id: 2, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'H', content: 'Em nắm được kiến thức cơ bản, cần cẩn thận hơn khi tính toán.' },
    { id: 3, grade: 'Khối 04', subject: 'Tiếng Việt', term: 'Cuối kỳ 1', level: 'T', content: 'Đọc to, rõ ràng, diễn cảm. Chữ viết đẹp.' },
    { id: 4, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'T', content: 'Vocabulary retention is excellent. Participates actively.' },
    { id: 5, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'H', content: 'Good effort in speaking activities. Needs to work on spelling.' },
    { id: 6, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'C', content: 'Cần ôn lại bảng cửu chương.' },
  ]);

  // Import/Export States
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showImportModal, setShowImportModal] = useState(false);
  const [importData, setImportData] = useState<ImportRow[]>([]);
  const [isImporting, setIsImporting] = useState(false);

  // --- DERIVED STATE & EFFECTS ---

  // Get available Grades based on User Assignments
  const availableGrades = useMemo(() => {
    return Object.keys(currentUser.assignments).sort();
  }, [currentUser]);

  // Update Subject List when Grade Changes
  const availableSubjects = useMemo(() => {
    if (!selectedGrade) return [];
    return currentUser.assignments[selectedGrade] || [];
  }, [selectedGrade, currentUser]);

  // Auto-select Grade if user only has 1
  useEffect(() => {
    if (availableGrades.length > 0 && !availableGrades.includes(selectedGrade)) {
        setSelectedGrade(availableGrades[0]);
    }
  }, [availableGrades]);

  // Auto-select Subject if only 1 exists for the grade
  useEffect(() => {
    if (availableSubjects.length > 0) {
        // If current subject is not in the new list, select the first one
        if (!availableSubjects.includes(selectedSubject)) {
            setSelectedSubject(availableSubjects[0]);
        }
    } else {
        setSelectedSubject('');
    }
  }, [availableSubjects, selectedGrade]);


  // Filter AND Sort Comments
  const processedComments = useMemo(() => {
    // 1. Filter
    const filtered = comments.filter(c => {
        const matchGrade = c.grade === selectedGrade;
        const matchSubject = c.subject === selectedSubject;
        // In real app, match Term too if needed, here strict matching grade/subject
        const matchSearch = c.content.toLowerCase().includes(searchTerm.toLowerCase());
        return matchGrade && matchSubject && matchSearch;
    });

    // 2. Sort Logic
    // Priority 1: Level (T -> H -> C)
    // Priority 2: ID Descending (Newest first)
    return filtered.sort((a, b) => {
        const levelPriority: Record<string, number> = { 'T': 1, 'H': 2, 'C': 3 };

        const priorityA = levelPriority[a.level] || 4;
        const priorityB = levelPriority[b.level] || 4;

        if (priorityA !== priorityB) {
            return priorityA - priorityB; // Ascending priority (1, 2, 3)
        }

        // If levels are same, sort by ID descending (newest first)
        return b.id - a.id;
    });
  }, [comments, selectedGrade, selectedSubject, searchTerm]);

  // --- HANDLERS ---

  const handleDownloadTemplate = () => {
    const fileName = `Mau_Nhan_Xet_${currentUser.name.replace(/\s/g, '_')}_${selectedGrade}.xlsx`;
    alert(`Đang tải xuống file mẫu: ${fileName}\n\n(File này sẽ được điền sẵn thông tin:\nKhối: ${selectedGrade}\nMôn: ${selectedSubject}\nHọc kỳ: ${term})`);
  };

  const handleTriggerUpload = () => {
    if (fileInputRef.current) {
        fileInputRef.current.value = ''; // Reset
        fileInputRef.current.click();
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const mockParsedRows: ImportRow[] = [];

      for (let i = 0; i < 50; i++) {
          const hasData = i < 5 || (i > 10 && i < 13);
          const isError = i === 12;

          const grade = selectedGrade;
          const subject = selectedSubject;
          const t = term;

          let level = '';
          let content = '';

          if (hasData) {
              level = i % 2 === 0 ? 'T' : 'H';
              content = `Nhận xét mẫu import dòng số ${i+1} cho môn ${subject}`;

              if (isError) {
                  level = 'T';
                  content = '';
              }
          }

          if (!level && !content) continue;

          let isValid = true;
          let error = '';

          if (level && !content) {
              isValid = false;
              error = 'Thiếu nội dung nhận xét';
          } else if (!level && content) {
               isValid = false;
               error = 'Thiếu mức độ (T/H/C)';
          }

          mockParsedRows.push({
              index: i,
              grade,
              subject,
              term: t,
              level,
              content,
              isValid,
              error
          });
      }

      setImportData(mockParsedRows);
      setShowImportModal(true);
  };

  const handleConfirmImport = () => {
      setIsImporting(true);
      setTimeout(() => {
          const newComments = importData
            .filter(r => r.isValid)
            .map((r, idx) => ({
                id: Date.now() + idx,
                grade: r.grade,
                subject: r.subject,
                term: r.term,
                level: r.level as any,
                content: r.content
            }));

          setComments([...newComments, ...comments]);
          setIsImporting(false);
          setShowImportModal(false);
      }, 1000);
  };

  // --- INLINE ADD HANDLERS ---
  const handleAddNewClick = () => {
    // If we are adding new, close edit mode if open
    setEditingId(null);
    setIsAddingNew(true);
    setNewLevel('T');
    setNewContent('');
  };

  const handleSaveNew = () => {
    if (!newContent.trim()) {
      alert("Vui lòng nhập nội dung nhận xét");
      return;
    }
    const newId = Date.now();
    const newComment: CommentItem = {
      id: newId,
      grade: selectedGrade,
      subject: selectedSubject,
      term: term,
      level: newLevel,
      content: newContent
    };

    setComments([newComment, ...comments]); 
    setIsAddingNew(false);
  };

  // --- INLINE EDIT HANDLERS ---
  const handleEditClick = (comment: CommentItem) => {
    // If adding new, close it
    setIsAddingNew(false);

    setEditingId(comment.id);
    setEditLevel(comment.level);
    setEditContent(comment.content);
  };

  const handleUpdateComment = () => {
     if (!editContent.trim()) {
        alert("Vui lòng nhập nội dung nhận xét");
        return;
     }

     setComments(prevComments => prevComments.map(c => 
        c.id === editingId 
        ? { ...c, level: editLevel, content: editContent }
        : c
     ));

     setEditingId(null);
  };

  const handleCancelEdit = () => {
     setEditingId(null);
  };

  const handleDelete = (id: number) => {
    if (confirm('Bạn có chắc chắn muốn xóa nhận xét này?')) {
        setComments(comments.filter(c => c.id !== id));
        if (editingId === id) {
            setEditingId(null);
        }
    }
  };

  return (
    <div className="flex flex-col h-full bg-gray-50/50">

      {/* 1. Header & Configuration */}
      <div className="bg-white border-b border-gray-200 p-6 shadow-sm">
         <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
             <div>
                <h1 className="text-2xl font-bold text-gray-800">Ngân hàng Nhận xét Cá nhân</h1>
                <p className="text-sm text-gray-500 mt-1">Quản lý kho nhận xét mẫu cho <span className="font-semibold text-blue-700">{currentUser.name}</span></p>
             </div>
             <div className="flex items-center gap-3 bg-blue-50 px-4 py-2 rounded-lg border border-blue-100">
                <span className="text-sm font-medium text-blue-800">Ưu tiên nguồn gợi ý:</span>
                <button 
                    onClick={() => setUseSystemBank(!useSystemBank)}
                    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${useSystemBank ? 'bg-gray-300' : 'bg-blue-600'}`}
                >
                    <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${useSystemBank ? 'translate-x-1' : 'translate-x-6'}`} />
                </button>
                <span className={`text-sm font-bold ${!useSystemBank ? 'text-blue-700' : 'text-gray-500'}`}>Cá nhân</span>
                <span className="text-gray-300">|</span>
                <span className={`text-sm font-bold ${useSystemBank ? 'text-gray-700' : 'text-gray-400'}`}>Hệ thống</span>
             </div>
         </div>

         {/* Filters */}
         <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Năm học</label>
               <select className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                  <option>2025-2026</option>
                  <option>2024-2025</option>
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Khối lớp</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedGrade}
                 onChange={(e) => setSelectedGrade(e.target.value)}
               >
                  {availableGrades.map(g => <option key={g} value={g}>{g}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Môn học</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedSubject}
                 onChange={(e) => setSelectedSubject(e.target.value)}
               >
                  {availableSubjects.map(s => <option key={s} value={s}>{s}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Học kỳ</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                 value={term}
                 onChange={(e) => setTerm(e.target.value)}
               >
                  <option>Giữa kỳ 1</option>
                  <option>Cuối kỳ 1</option>
                  <option>Giữa kỳ 2</option>
                  <option>Cuối năm</option>
               </select>
            </div>
         </div>
      </div>

      {/* 2. Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row justify-between items-center gap-4">
         {/* Search */}
         <div className="relative w-full md:w-96">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Tìm kiếm nội dung nhận xét..."
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-full focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
         </div>

         {/* Actions */}
         <div className="flex items-center gap-3 w-full md:w-auto">
             <button 
                onClick={handleDownloadTemplate}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-50 transition-colors whitespace-nowrap"
             >
                <Download size={16} />
                <span>Tải file mẫu</span>
             </button>
             <button 
                onClick={handleTriggerUpload}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Upload size={16} />
                <span>Tải lên & Cập nhật</span>
             </button>
             <input type="file" ref={fileInputRef} className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />

             <button 
                onClick={handleAddNewClick}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Plus size={16} />
                <span>Thêm mới</span>
             </button>
         </div>
      </div>

      {/* 3. Data Table */}
      <div className="flex-1 overflow-auto custom-scrollbar px-6 pb-6">
         <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden min-h-[400px]">
            <table className="w-full text-left border-collapse">
               <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold sticky top-0 z-10">
                  <tr>
                     <th className="px-6 py-4 w-16 text-center border-b">STT</th>
                     <th className="px-6 py-4 w-32 border-b">Mức độ</th>
                     <th className="px-6 py-4 border-b">Nội dung nhận xét</th>
                     <th className="px-6 py-4 w-32 text-center border-b">Hành động</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-gray-100">
                  {/* INLINE ADD ROW - ALWAYS AT TOP */}
                  {isAddingNew && (
                    <tr className="bg-blue-50 animate-in fade-in slide-in-from-top-2 duration-300 border-b border-blue-100 shadow-inner">
                      <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">#</td>
                      <td className="px-6 py-4">
                          <select 
                            className="w-full p-2 border border-gray-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                            value={newLevel}
                            onChange={(e) => setNewLevel(e.target.value as any)}
                          >
                            <option value="T">T</option>
                            <option value="H">H</option>
                            <option value="C">C</option>
                          </select>
                      </td>
                      <td className="px-6 py-4">
                          <input 
                            type="text"
                            autoFocus
                            className="w-full p-2 border border-blue-300 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white placeholder-gray-400 font-medium"
                            placeholder="Nhập nội dung nhận xét..."
                            value={newContent}
                            onChange={(e) => setNewContent(e.target.value)}
                            onKeyDown={(e) => {
                                if(e.key === 'Enter') handleSaveNew();
                                if(e.key === 'Escape') setIsAddingNew(false);
                            }}
                          />
                      </td>
                      <td className="px-6 py-4 text-center">
                          <div className="flex items-center justify-center gap-2">
                              <button onClick={handleSaveNew} className="p-2 text-white bg-green-500 hover:bg-green-600 rounded-lg transition-colors shadow-sm" title="Lưu">
                                  <Check size={16} />
                              </button>
                              <button onClick={() => setIsAddingNew(false)} className="p-2 text-gray-600 bg-white border border-gray-300 hover:bg-gray-100 rounded-lg transition-colors shadow-sm" title="Hủy">
                                  <X size={16} />
                              </button>
                          </div>
                      </td>
                    </tr>
                  )}

                  {processedComments.length > 0 ? (
                    processedComments.map((comment, index) => {
                      const isEditing = comment.id === editingId;

                      if (isEditing) {
                          return (
                              <tr key={comment.id} className="bg-white border-b border-gray-100 animate-in fade-in">
                                  <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                                  <td className="px-6 py-4">
                                      <select 
                                        className="w-full p-2 border border-blue-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                                        value={editLevel}
                                        onChange={(e) => setEditLevel(e.target.value as any)}
                                      >
                                        <option value="T">T</option>
                                        <option value="H">H</option>
                                        <option value="C">C</option>
                                      </select>
                                  </td>
                                  <td className="px-6 py-4">
                                      <input 
                                        type="text"
                                        autoFocus
                                        className="w-full p-2 border border-blue-400 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white font-medium text-gray-800"
                                        value={editContent}
                                        onChange={(e) => setEditContent(e.target.value)}
                                        onKeyDown={(e) => {
                                            if(e.key === 'Enter') handleUpdateComment();
                                            if(e.key === 'Escape') handleCancelEdit();
                                        }}
                                      />
                                  </td>
                                  <td className="px-6 py-4 text-center">
                                      <div className="flex items-center justify-center gap-3">
                                          <button 
                                            onClick={handleUpdateComment} 
                                            className="p-1.5 text-green-600 hover:text-green-700 hover:bg-green-50 rounded transition-colors"
                                            title="Lưu thay đổi"
                                          >
                                              <Save size={20} />
                                          </button>
                                          <button 
                                            onClick={handleCancelEdit} 
                                            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-50 rounded transition-colors"
                                            title="Hủy bỏ"
                                          >
                                              <X size={20} />
                                          </button>
                                      </div>
                                  </td>
                              </tr>
                          );
                      }

                      return (
                        <tr key={comment.id} className="hover:bg-blue-50/50 transition-colors group">
                           <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                           <td className="px-6 py-4">
                              <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg text-sm font-bold border ${
                                comment.level === 'T' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                comment.level === 'H' ? 'bg-cyan-50 text-cyan-700 border-cyan-200' :
                                'bg-orange-50 text-orange-700 border-orange-200'
                              }`}>
                                 {comment.level}
                              </span>
                           </td>
                           <td className="px-6 py-4 text-sm text-gray-800 leading-relaxed font-medium">
                              {comment.content}
                           </td>
                           <td className="px-6 py-4 text-center">
                              <div className="flex items-center justify-center gap-2">
                                 <button 
                                    onClick={() => handleEditClick(comment)}
                                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                    title="Chỉnh sửa"
                                 >
                                    <Edit size={16} />
                                 </button>
                                 <button 
                                    onClick={() => handleDelete(comment.id)}
                                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Xóa"
                                 >
                                    <Trash2 size={16} />
                                 </button>
                              </div>
                           </td>
                        </tr>
                      );
                    })
                  ) : (
                    !isAddingNew && (
                        <tr>
                            <td colSpan={4} className="px-6 py-20 text-center">
                            <div className="flex flex-col items-center justify-center text-gray-400">
                                <Info size={48} className="mb-4 text-gray-300" />
                                <p className="text-lg font-medium text-gray-500">Chưa có dữ liệu nhận xét</p>
                                <p className="text-sm mt-1 max-w-sm mx-auto">
                                    Vui lòng "Thêm mới" hoặc sử dụng chức năng "Tải lên" để nhập dữ liệu từ Excel cho môn <span className="font-bold text-gray-600">{selectedSubject}</span>.
                                </p>
                            </div>
                            </td>
                        </tr>
                    )
                  )}
               </tbody>
            </table>
         </div>
      </div>

      {/* Import Modal */}
      <CommentBankImportModal 
        isOpen={showImportModal}
        onClose={() => setShowImportModal(false)}
        importData={importData}
        onConfirm={handleConfirmImport}
        isLoading={isImporting}
      />

    </div>
  );
};

export default CommentBank;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserConfig, CommentItem, ImportRow } from '../types';
import { Download, Upload, Search, Trash2, Edit, Plus, Info, Check, X, Save } from 'lucide-react';
import CommentBankImportModal from './CommentBankImportModal';
import * as XLSX from 'xlsx';

interface CommentBankProps {
  currentUser: UserConfig;
}

const CommentBank: React.FC<CommentBankProps> = ({ currentUser }) => {
  // --- STATE ---
  const [selectedGrade, setSelectedGrade] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>('');
  const [term, setTerm] = useState('Cuối kỳ 1');
  const [useSystemBank, setUseSystemBank] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Inline Add State
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [newLevel, setNewLevel] = useState<'T' | 'H' | 'C'>('T');
  const [newContent, setNewContent] = useState('');

  // Inline Edit State
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editLevel, setEditLevel] = useState<'T' | 'H' | 'C'>('T');
  const [editContent, setEditContent] = useState('');

  // Dummy Data State
  const [comments, setComments] = useState<CommentItem[]>([
    { id: 1, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'T', content: 'Em tính toán nhanh, chính xác, hiểu bài tốt.' },
    { id: 2, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'H', content: 'Em nắm được kiến thức cơ bản, cần cẩn thận hơn khi tính toán.' },
    { id: 3, grade: 'Khối 04', subject: 'Tiếng Việt', term: 'Cuối kỳ 1', level: 'T', content: 'Đọc to, rõ ràng, diễn cảm. Chữ viết đẹp.' },
    { id: 4, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'T', content: 'Vocabulary retention is excellent. Participates actively.' },
    { id: 5, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'H', content: 'Good effort in speaking activities. Needs to work on spelling.' },
    { id: 6, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'C', content: 'Cần ôn lại bảng cửu chương.' },
  ]);

  // Import/Export States
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showImportModal, setShowImportModal] = useState(false);
  const [importData, setImportData] = useState<ImportRow[]>([]);
  const [isImporting, setIsImporting] = useState(false);

  // --- DERIVED STATE & EFFECTS ---

  // Get available Grades based on User Assignments
  const availableGrades = useMemo(() => {
    return Object.keys(currentUser.assignments).sort();
  }, [currentUser]);

  // Update Subject List when Grade Changes
  const availableSubjects = useMemo(() => {
    if (!selectedGrade) return [];
    return currentUser.assignments[selectedGrade] || [];
  }, [selectedGrade, currentUser]);

  // Auto-select Grade if user only has 1
  useEffect(() => {
    if (availableGrades.length > 0 && !availableGrades.includes(selectedGrade)) {
        setSelectedGrade(availableGrades[0]);
    }
  }, [availableGrades]);

  // Auto-select Subject if only 1 exists for the grade
  useEffect(() => {
    if (availableSubjects.length > 0) {
        // If current subject is not in the new list, select the first one
        if (!availableSubjects.includes(selectedSubject)) {
            setSelectedSubject(availableSubjects[0]);
        }
    } else {
        setSelectedSubject('');
    }
  }, [availableSubjects, selectedGrade]);


  // Filter AND Sort Comments
  const processedComments = useMemo(() => {
    // 1. Filter
    const filtered = comments.filter(c => {
        const matchGrade = c.grade === selectedGrade;
        const matchSubject = c.subject === selectedSubject;
        // In real app, match Term too if needed, here strict matching grade/subject
        const matchSearch = c.content.toLowerCase().includes(searchTerm.toLowerCase());
        return matchGrade && matchSubject && matchSearch;
    });

    // 2. Sort Logic
    // Priority 1: Level (T -> H -> C)
    // Priority 2: ID Descending (Newest first)
    return filtered.sort((a, b) => {
        const levelPriority: Record<string, number> = { 'T': 1, 'H': 2, 'C': 3 };

        const priorityA = levelPriority[a.level] || 4;
        const priorityB = levelPriority[b.level] || 4;

        if (priorityA !== priorityB) {
            return priorityA - priorityB; // Ascending priority (1, 2, 3)
        }

        // If levels are same, sort by ID descending (newest first)
        return b.id - a.id;
    });
  }, [comments, selectedGrade, selectedSubject, searchTerm]);

  // --- HANDLERS ---

  // 1. HANDLE DOWNLOAD TEMPLATE (Context-aware)
  const handleDownloadTemplate = () => {
    if (!selectedGrade || !selectedSubject) {
        alert("Vui lòng chọn Khối và Môn học trước khi tải mẫu.");
        return;
    }

    // Prepare data rows with pre-filled context
    const rows = [];
    for (let i = 1; i <= 50; i++) {
        rows.push({
            'STT': i,
            'Khối': selectedGrade,
            'Môn học': selectedSubject,
            'Học kỳ': term,
            'Mức độ (T/H/C)': '', // User fills this
            'Nội dung nhận xét': '' // User fills this
        });
    }

    // Create workbook and worksheet
    const worksheet = XLSX.utils.json_to_sheet(rows);

    // Set column widths for better UX
    const wscols = [
        { wch: 5 },  // STT
        { wch: 10 }, // Khối
        { wch: 20 }, // Môn
        { wch: 15 }, // Học kỳ
        { wch: 15 }, // Mức độ
        { wch: 60 }  // Nội dung
    ];
    worksheet['!cols'] = wscols;

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Mau_Nhan_Xet");

    // Generate filename
    const safeName = currentUser.name.replace(/[^a-zA-Z0-9]/g, '_');
    const fileName = `Mau_${safeName}_${selectedGrade}_${selectedSubject}.xlsx`;

    // Trigger download
    XLSX.writeFile(workbook, fileName);
  };

  const handleTriggerUpload = () => {
    if (fileInputRef.current) {
        fileInputRef.current.value = ''; // Reset
        fileInputRef.current.click();
    }
  };

  // 2. HANDLE FILE UPLOAD & PREVIEW (Client-side Parsing)
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();

      reader.onload = (evt) => {
          const bstr = evt.target?.result;
          if (!bstr) return;

          try {
              // Read the workbook
              const wb = XLSX.read(bstr, { type: 'binary' });

              // Get first sheet
              const wsname = wb.SheetNames[0];
              const ws = wb.Sheets[wsname];

              // Convert to JSON
              const jsonData = XLSX.utils.sheet_to_json(ws);

              // Validate and Map Data
              const parsedRows: ImportRow[] = jsonData.map((row: any, index: number) => {
                  // Map keys based on Template headers
                  const grade = row['Khối'] || selectedGrade;
                  const subject = row['Môn học'] || selectedSubject;
                  const t = row['Học kỳ'] || term;
                  const rawLevel = row['Mức độ (T/H/C)'];
                  const content = row['Nội dung nhận xét'];

                  // Validation Logic
                  let isValid = true;
                  let error = '';

                  // Check Level
                  let level = '';
                  if (rawLevel) {
                      const cleanLevel = String(rawLevel).trim().toUpperCase();
                      if (['T', 'H', 'C'].includes(cleanLevel)) {
                          level = cleanLevel;
                      } else {
                          isValid = false;
                          error = 'Mức độ không hợp lệ (Phải là T, H hoặc C)';
                      }
                  } else {
                      // Check if content exists but level missing
                      if (content) {
                          isValid = false;
                          error = 'Thiếu mức độ';
                      } else {
                          // Empty row
                          isValid = false; 
                      }
                  }

                  // Check Content
                  if (!content && level) {
                      isValid = false;
                      error = 'Thiếu nội dung nhận xét';
                  }

                  // Skip completely empty rows from being "invalid" - just mark them invalid but maybe filter them out? 
                  // For now, if both missing, we consider it an empty trail row if it was read
                  if (!rawLevel && !content) {
                      isValid = false;
                      error = 'Dòng trống';
                  }

                  return {
                      index,
                      grade,
                      subject,
                      term: t,
                      level,
                      content: content || '',
                      isValid,
                      error
                  };
              });

              // Filter out completely empty rows (often Excel reads trailing empty rows)
              const nonEmptyRows = parsedRows.filter(r => r.error !== 'Dòng trống');

              if (nonEmptyRows.length === 0) {
                  alert("File không có dữ liệu hợp lệ hoặc cấu trúc cột không đúng.");
                  return;
              }

              setImportData(nonEmptyRows);
              setShowImportModal(true);

          } catch (error) {
              console.error("Error reading file:", error);
              alert("Đã xảy ra lỗi khi đọc file Excel. Vui lòng đảm bảo file đúng định dạng.");
          }
      };

      reader.readAsBinaryString(file);
  };

  const handleConfirmImport = () => {
      setIsImporting(true);

      // Simulate API call delay
      setTimeout(() => {
          const newComments = importData
            .filter(r => r.isValid)
            .map((r, idx) => ({
                id: Date.now() + idx, // Simple unique ID generation
                grade: r.grade,
                subject: r.subject,
                term: r.term,
                level: r.level as any,
                content: r.content
            }));

          if (newComments.length === 0) {
              alert("Không có dữ liệu hợp lệ để lưu.");
              setIsImporting(false);
              return;
          }

          // Merge with existing comments (newest first logic handled by Sort in useMemo)
          setComments(prev => [...newComments, ...prev]);

          setIsImporting(false);
          setShowImportModal(false);
          setImportData([]); // Clear buffer
      }, 800);
  };

  // --- INLINE ADD HANDLERS ---
  const handleAddNewClick = () => {
    // If we are adding new, close edit mode if open
    setEditingId(null);
    setIsAddingNew(true);
    setNewLevel('T');
    setNewContent('');
  };

  const handleSaveNew = () => {
    if (!newContent.trim()) {
      alert("Vui lòng nhập nội dung nhận xét");
      return;
    }
    const newId = Date.now();
    const newComment: CommentItem = {
      id: newId,
      grade: selectedGrade,
      subject: selectedSubject,
      term: term,
      level: newLevel,
      content: newContent
    };

    setComments([newComment, ...comments]); 
    setIsAddingNew(false);
  };

  // --- INLINE EDIT HANDLERS ---
  const handleEditClick = (comment: CommentItem) => {
    // If adding new, close it
    setIsAddingNew(false);

    setEditingId(comment.id);
    setEditLevel(comment.level);
    setEditContent(comment.content);
  };

  const handleUpdateComment = () => {
     if (!editContent.trim()) {
        alert("Vui lòng nhập nội dung nhận xét");
        return;
     }

     setComments(prevComments => prevComments.map(c => 
        c.id === editingId 
        ? { ...c, level: editLevel, content: editContent }
        : c
     ));

     setEditingId(null);
  };

  const handleCancelEdit = () => {
     setEditingId(null);
  };

  const handleDelete = (id: number) => {
    if (confirm('Bạn có chắc chắn muốn xóa nhận xét này?')) {
        setComments(comments.filter(c => c.id !== id));
        if (editingId === id) {
            setEditingId(null);
        }
    }
  };

  return (
    <div className="flex flex-col h-full bg-gray-50/50">

      {/* 1. Header & Configuration */}
      <div className="bg-white border-b border-gray-200 p-6 shadow-sm">
         <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
             <div>
                <h1 className="text-2xl font-bold text-gray-800">Ngân hàng Nhận xét Cá nhân</h1>
                <p className="text-sm text-gray-500 mt-1">Quản lý kho nhận xét mẫu cho <span className="font-semibold text-blue-700">{currentUser.name}</span></p>
             </div>
             <div className="flex items-center gap-3 bg-blue-50 px-4 py-2 rounded-lg border border-blue-100">
                <span className="text-sm font-medium text-blue-800">Ưu tiên nguồn gợi ý:</span>
                <button 
                    onClick={() => setUseSystemBank(!useSystemBank)}
                    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${useSystemBank ? 'bg-gray-300' : 'bg-blue-600'}`}
                >
                    <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${useSystemBank ? 'translate-x-1' : 'translate-x-6'}`} />
                </button>
                <span className={`text-sm font-bold ${!useSystemBank ? 'text-blue-700' : 'text-gray-500'}`}>Cá nhân</span>
                <span className="text-gray-300">|</span>
                <span className={`text-sm font-bold ${useSystemBank ? 'text-gray-700' : 'text-gray-400'}`}>Hệ thống</span>
             </div>
         </div>

         {/* Filters */}
         <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Năm học</label>
               <select className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                  <option>2025-2026</option>
                  <option>2024-2025</option>
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Khối lớp</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedGrade}
                 onChange={(e) => setSelectedGrade(e.target.value)}
               >
                  {availableGrades.map(g => <option key={g} value={g}>{g}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Môn học</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedSubject}
                 onChange={(e) => setSelectedSubject(e.target.value)}
               >
                  {availableSubjects.map(s => <option key={s} value={s}>{s}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Học kỳ</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                 value={term}
                 onChange={(e) => setTerm(e.target.value)}
               >
                  <option>Giữa kỳ 1</option>
                  <option>Cuối kỳ 1</option>
                  <option>Giữa kỳ 2</option>
                  <option>Cuối năm</option>
               </select>
            </div>
         </div>
      </div>

      {/* 2. Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row justify-between items-center gap-4">
         {/* Search */}
         <div className="relative w-full md:w-96">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Tìm kiếm nội dung nhận xét..."
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-full focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
         </div>

         {/* Actions */}
         <div className="flex items-center gap-3 w-full md:w-auto">
             <button 
                onClick={handleDownloadTemplate}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-50 transition-colors whitespace-nowrap"
             >
                <Download size={16} />
                <span>Tải file mẫu</span>
             </button>
             <button 
                onClick={handleTriggerUpload}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Upload size={16} />
                <span>Tải lên & Cập nhật</span>
             </button>
             <input type="file" ref={fileInputRef} className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />

             <button 
                onClick={handleAddNewClick}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Plus size={16} />
                <span>Thêm mới</span>
             </button>
         </div>
      </div>

      {/* 3. Data Table */}
      <div className="flex-1 overflow-auto custom-scrollbar px-6 pb-6">
         <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden min-h-[400px]">
            <table className="w-full text-left border-collapse">
               <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold sticky top-0 z-10">
                  <tr>
                     <th className="px-6 py-4 w-16 text-center border-b">STT</th>
                     <th className="px-6 py-4 w-32 border-b">Mức độ</th>
                     <th className="px-6 py-4 border-b">Nội dung nhận xét</th>
                     <th className="px-6 py-4 w-32 text-center border-b">Hành động</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-gray-100">
                  {/* INLINE ADD ROW - ALWAYS AT TOP */}
                  {isAddingNew && (
                    <tr className="bg-blue-50 animate-in fade-in slide-in-from-top-2 duration-300 border-b border-blue-100 shadow-inner">
                      <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">#</td>
                      <td className="px-6 py-4">
                          <select 
                            className="w-full p-2 border border-gray-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                            value={newLevel}
                            onChange={(e) => setNewLevel(e.target.value as any)}
                          >
                            <option value="T">T</option>
                            <option value="H">H</option>
                            <option value="C">C</option>
                          </select>
                      </td>
                      <td className="px-6 py-4">
                          <input 
                            type="text"
                            autoFocus
                            className="w-full p-2 border border-blue-300 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white placeholder-gray-400 font-medium"
                            placeholder="Nhập nội dung nhận xét..."
                            value={newContent}
                            onChange={(e) => setNewContent(e.target.value)}
                            onKeyDown={(e) => {
                                if(e.key === 'Enter') handleSaveNew();
                                if(e.key === 'Escape') setIsAddingNew(false);
                            }}
                          />
                      </td>
                      <td className="px-6 py-4 text-center">
                          <div className="flex items-center justify-center gap-2">
                              <button onClick={handleSaveNew} className="p-2 text-white bg-green-500 hover:bg-green-600 rounded-lg transition-colors shadow-sm" title="Lưu">
                                  <Check size={16} />
                              </button>
                              <button onClick={() => setIsAddingNew(false)} className="p-2 text-gray-600 bg-white border border-gray-300 hover:bg-gray-100 rounded-lg transition-colors shadow-sm" title="Hủy">
                                  <X size={16} />
                              </button>
                          </div>
                      </td>
                    </tr>
                  )}

                  {processedComments.length > 0 ? (
                    processedComments.map((comment, index) => {
                      const isEditing = comment.id === editingId;

                      if (isEditing) {
                          return (
                              <tr key={comment.id} className="bg-white border-b border-gray-100 animate-in fade-in">
                                  <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                                  <td className="px-6 py-4">
                                      <select 
                                        className="w-full p-2 border border-blue-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                                        value={editLevel}
                                        onChange={(e) => setEditLevel(e.target.value as any)}
                                      >
                                        <option value="T">T</option>
                                        <option value="H">H</option>
                                        <option value="C">C</option>
                                      </select>
                                  </td>
                                  <td className="px-6 py-4">
                                      <input 
                                        type="text"
                                        autoFocus
                                        className="w-full p-2 border border-blue-400 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white font-medium text-gray-800"
                                        value={editContent}
                                        onChange={(e) => setEditContent(e.target.value)}
                                        onKeyDown={(e) => {
                                            if(e.key === 'Enter') handleUpdateComment();
                                            if(e.key === 'Escape') handleCancelEdit();
                                        }}
                                      />
                                  </td>
                                  <td className="px-6 py-4 text-center">
                                      <div className="flex items-center justify-center gap-3">
                                          <button 
                                            onClick={handleUpdateComment} 
                                            className="p-1.5 text-green-600 hover:text-green-700 hover:bg-green-50 rounded transition-colors"
                                            title="Lưu thay đổi"
                                          >
                                              <Save size={20} />
                                          </button>
                                          <button 
                                            onClick={handleCancelEdit} 
                                            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-50 rounded transition-colors"
                                            title="Hủy bỏ"
                                          >
                                              <X size={20} />
                                          </button>
                                      </div>
                                  </td>
                              </tr>
                          );
                      }

                      return (
                        <tr key={comment.id} className="hover:bg-blue-50/50 transition-colors group">
                           <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                           <td className="px-6 py-4">
                              <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg text-sm font-bold border ${
                                comment.level === 'T' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                comment.level === 'H' ? 'bg-cyan-50 text-cyan-700 border-cyan-200' :
                                'bg-orange-50 text-orange-700 border-orange-200'
                              }`}>
                                 {comment.level}
                              </span>
                           </td>
                           <td className="px-6 py-4 text-sm text-gray-800 leading-relaxed font-medium">
                              {comment.content}
                           </td>
                           <td className="px-6 py-4 text-center">
                              <div className="flex items-center justify-center gap-2">
                                 <button 
                                    onClick={() => handleEditClick(comment)}
                                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                    title="Chỉnh sửa"
                                 >
                                    <Edit size={16} />
                                 </button>
                                 <button 
                                    onClick={() => handleDelete(comment.id)}
                                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Xóa"
                                 >
                                    <Trash2 size={16} />
                                 </button>
                              </div>
                           </td>
                        </tr>
                      );
                    })
                  ) : (
                    !isAddingNew && (
                        <tr>
                            <td colSpan={4} className="px-6 py-20 text-center">
                            <div className="flex flex-col items-center justify-center text-gray-400">
                                <Info size={48} className="mb-4 text-gray-300" />
                                <p className="text-lg font-medium text-gray-500">Chưa có dữ liệu nhận xét</p>
                                <p className="text-sm mt-1 max-w-sm mx-auto">
                                    Vui lòng "Thêm mới" hoặc sử dụng chức năng "Tải lên" để nhập dữ liệu từ Excel cho môn <span className="font-bold text-gray-600">{selectedSubject}</span>.
                                </p>
                            </div>
                            </td>
                        </tr>
                    )
                  )}
               </tbody>
            </table>
         </div>
      </div>

      {/* Import Modal */}
      <CommentBankImportModal 
        isOpen={showImportModal}
        onClose={() => setShowImportModal(false)}
        importData={importData}
        onConfirm={handleConfirmImport}
        isLoading={isImporting}
      />

    </div>
  );
};

export default CommentBank;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserConfig, CommentItem, ImportRow } from '../types';
import { Download, Upload, Search, Trash2, Edit, Plus, Info, Check, X, Save } from 'lucide-react';
import CommentBankImportModal from './CommentBankImportModal';
import * as XLSX from 'xlsx';

interface CommentBankProps {
  currentUser: UserConfig;
}

const CommentBank: React.FC<CommentBankProps> = ({ currentUser }) => {
  // --- STATE ---
  const [selectedGrade, setSelectedGrade] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>('');
  const [term, setTerm] = useState('Cuối kỳ 1');
  const [useSystemBank, setUseSystemBank] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Inline Add State
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [newLevel, setNewLevel] = useState<'T' | 'H' | 'C'>('T');
  const [newContent, setNewContent] = useState('');

  // Inline Edit State
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editLevel, setEditLevel] = useState<'T' | 'H' | 'C'>('T');
  const [editContent, setEditContent] = useState('');

  // Dummy Data State
  const [comments, setComments] = useState<CommentItem[]>([
    { id: 1, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'T', content: 'Em tính toán nhanh, chính xác, hiểu bài tốt.' },
    { id: 2, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'H', content: 'Em nắm được kiến thức cơ bản, cần cẩn thận hơn khi tính toán.' },
    { id: 3, grade: 'Khối 04', subject: 'Tiếng Việt', term: 'Cuối kỳ 1', level: 'T', content: 'Đọc to, rõ ràng, diễn cảm. Chữ viết đẹp.' },
    { id: 4, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'T', content: 'Vocabulary retention is excellent. Participates actively.' },
    { id: 5, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'H', content: 'Good effort in speaking activities. Needs to work on spelling.' },
    { id: 6, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'C', content: 'Cần ôn lại bảng cửu chương.' },
  ]);

  // Import/Export States
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showImportModal, setShowImportModal] = useState(false);
  const [importData, setImportData] = useState<ImportRow[]>([]);
  const [isImporting, setIsImporting] = useState(false);

  // --- DERIVED STATE & EFFECTS ---

  // Get available Grades based on User Assignments
  const availableGrades = useMemo(() => {
    return Object.keys(currentUser.assignments).sort();
  }, [currentUser]);

  // Update Subject List when Grade Changes
  const availableSubjects = useMemo(() => {
    if (!selectedGrade) return [];
    return currentUser.assignments[selectedGrade] || [];
  }, [selectedGrade, currentUser]);

  // Auto-select Grade if user only has 1
  useEffect(() => {
    if (availableGrades.length > 0 && !availableGrades.includes(selectedGrade)) {
        setSelectedGrade(availableGrades[0]);
    }
  }, [availableGrades]);

  // Auto-select Subject if only 1 exists for the grade
  useEffect(() => {
    if (availableSubjects.length > 0) {
        // If current subject is not in the new list, select the first one
        if (!availableSubjects.includes(selectedSubject)) {
            setSelectedSubject(availableSubjects[0]);
        }
    } else {
        setSelectedSubject('');
    }
  }, [availableSubjects, selectedGrade]);


  // Filter AND Sort Comments
  const processedComments = useMemo(() => {
    // 1. Filter
    const filtered = comments.filter(c => {
        const matchGrade = c.grade === selectedGrade;
        const matchSubject = c.subject === selectedSubject;
        // In real app, match Term too if needed, here strict matching grade/subject
        const matchSearch = c.content.toLowerCase().includes(searchTerm.toLowerCase());
        return matchGrade && matchSubject && matchSearch;
    });

    // 2. Sort Logic
    // Priority 1: Level (T -> H -> C)
    // Priority 2: ID Descending (Newest first)
    return filtered.sort((a, b) => {
        const levelPriority: Record<string, number> = { 'T': 1, 'H': 2, 'C': 3 };

        const priorityA = levelPriority[a.level] || 4;
        const priorityB = levelPriority[b.level] || 4;

        if (priorityA !== priorityB) {
            return priorityA - priorityB; // Ascending priority (1, 2, 3)
        }

        // If levels are same, sort by ID descending (newest first)
        return b.id - a.id;
    });
  }, [comments, selectedGrade, selectedSubject, searchTerm]);

  // --- HANDLERS ---

  // 1. HANDLE DOWNLOAD TEMPLATE (Context-aware + Append Mode)
  const handleDownloadTemplate = () => {
    if (!selectedGrade || !selectedSubject) {
        alert("Vui lòng chọn Khối và Môn học trước khi tải mẫu.");
        return;
    }

    // Step 1: Get Existing Data for current context (Ignoring search term to export all relevant data)
    const existingData = comments.filter(c => 
        c.grade === selectedGrade && 
        c.subject === selectedSubject && 
        c.term === term
    );

    const rows = [];
    let currentRowIndex = 1;

    // Step 2: Write Existing Data
    existingData.forEach(item => {
        rows.push({
            'STT': currentRowIndex++,
            'Khối': item.grade,
            'Môn học': item.subject,
            'Học kỳ': item.term,
            'Mức độ (T/H/C)': item.level,
            'Nội dung nhận xét': item.content
        });
    });

    // Step 3: Append 50 Empty Rows with Context
    for (let i = 0; i < 50; i++) {
        rows.push({
            'STT': currentRowIndex++,
            'Khối': selectedGrade,
            'Môn học': selectedSubject,
            'Học kỳ': term,
            'Mức độ (T/H/C)': '', 
            'Nội dung nhận xét': '' 
        });
    }

    // Create workbook and worksheet
    const worksheet = XLSX.utils.json_to_sheet(rows);

    // Set column widths for better UX
    const wscols = [
        { wch: 5 },  // STT
        { wch: 10 }, // Khối
        { wch: 20 }, // Môn
        { wch: 15 }, // Học kỳ
        { wch: 15 }, // Mức độ
        { wch: 60 }  // Nội dung
    ];
    worksheet['!cols'] = wscols;

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Mau_Nhan_Xet");

    // Generate filename
    const safeName = currentUser.name.replace(/[^a-zA-Z0-9]/g, '_');
    const fileName = `Mau_${safeName}_${selectedGrade}_${selectedSubject}.xlsx`;

    // Trigger download
    XLSX.writeFile(workbook, fileName);
  };

  const handleTriggerUpload = () => {
    if (fileInputRef.current) {
        fileInputRef.current.value = ''; // Reset
        fileInputRef.current.click();
    }
  };

  // 2. HANDLE FILE UPLOAD & PREVIEW (3-Layer Filtering)
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();

      reader.onload = (evt) => {
          const bstr = evt.target?.result;
          if (!bstr) return;

          try {
              // Read the workbook
              const wb = XLSX.read(bstr, { type: 'binary' });
              const wsname = wb.SheetNames[0];
              const ws = wb.Sheets[wsname];
              const jsonData = XLSX.utils.sheet_to_json(ws);

              // --- DEDUPLICATION PREPARATION ---
              // Helper to generate signature: Grade|Subject|Term|Level|Content(normalized)
              const normalize = (str: string) => str ? String(str).trim().toLowerCase() : '';
              const generateSig = (g: string, s: string, t: string, l: string, c: string) => 
                  `${g}|${s}|${t}|${l}|${normalize(c)}`;

              // 1. Create Set of signatures from CURRENT DB (Layer 2: System Duplicate Filter)
              // We filter by the uploaded row's context later, but it's faster to verify against full DB or filtered DB.
              // Let's verify against ALL comments to prevent accidental dupes across different terms if needed, 
              // but prompt implies checking against "CurrentDB" (likely active context). 
              // However, strictly checking exact match of Grade/Sub/Term/Level/Content is safe globally.
              const existingSignatures = new Set(
                  comments.map(c => generateSig(c.grade, c.subject, c.term, c.level, c.content))
              );

              // 2. Create Set for tracking dupes WITHIN the file (Layer 3: File Duplicate Filter)
              const fileSignatures = new Set<string>();

              const parsedRows: ImportRow[] = [];

              jsonData.forEach((row: any, index: number) => {
                  // Map keys
                  const grade = row['Khối'] || selectedGrade;
                  const subject = row['Môn học'] || selectedSubject;
                  const t = row['Học kỳ'] || term;
                  const rawLevel = row['Mức độ (T/H/C)'];
                  const content = row['Nội dung nhận xét'];

                  // --- LAYER 1: EMPTY FILTER ---
                  // Logic: If both Level and Content are missing => Empty row => Skip
                  if (!rawLevel && !content) return; 

                  let level = '';
                  let isValid = true;
                  let error = '';

                  // Basic Validation
                  if (rawLevel) {
                      const cleanLevel = String(rawLevel).trim().toUpperCase();
                      if (['T', 'H', 'C'].includes(cleanLevel)) {
                          level = cleanLevel;
                      } else {
                          isValid = false;
                          error = 'Mức độ không hợp lệ (Phải là T, H hoặc C)';
                      }
                  } else {
                       if (content) { isValid = false; error = 'Thiếu mức độ'; }
                       else { return; } // Should be caught by top check
                  }

                  if (!content && level) {
                      isValid = false;
                      error = 'Thiếu nội dung nhận xét';
                  }

                  // --- LAYER 2 & 3: DUPLICATE FILTERS ---
                  // Only run duplicate checks if the row is syntactically valid so far (has content & level)
                  if (isValid) {
                      const sig = generateSig(grade, subject, t, level, content);

                      // Layer 2: Check System DB
                      if (existingSignatures.has(sig)) {
                          return; // SKIP: Already exists in system
                      }

                      // Layer 3: Check File Duplicates
                      if (fileSignatures.has(sig)) {
                          return; // SKIP: Duplicate within file
                      }

                      // Mark as seen in file
                      fileSignatures.add(sig);
                  }

                  // If we reached here, it's either a NEW valid row OR a row with Syntax Error (but not a duplicate)
                  parsedRows.push({
                      index,
                      grade,
                      subject,
                      term: t,
                      level,
                      content: content || '',
                      isValid,
                      error
                  });
              });

              if (parsedRows.length === 0) {
                  alert("Không tìm thấy dữ liệu mới. Tất cả các câu trong file đều đã tồn tại trên hệ thống hoặc file rỗng.");
                  return;
              }

              setImportData(parsedRows);
              setShowImportModal(true);

          } catch (error) {
              console.error("Error reading file:", error);
              alert("Đã xảy ra lỗi khi đọc file Excel. Vui lòng đảm bảo file đúng định dạng.");
          }
      };

      reader.readAsBinaryString(file);
  };

  const handleConfirmImport = () => {
      setIsImporting(true);

      // Simulate API call delay
      setTimeout(() => {
          const newComments = importData
            .filter(r => r.isValid)
            .map((r, idx) => ({
                id: Date.now() + idx, // Simple unique ID generation
                grade: r.grade,
                subject: r.subject,
                term: r.term,
                level: r.level as any,
                content: r.content
            }));

          if (newComments.length === 0) {
              alert("Không có dữ liệu hợp lệ để lưu.");
              setIsImporting(false);
              return;
          }

          // Merge with existing comments (newest first logic handled by Sort in useMemo)
          setComments(prev => [...newComments, ...prev]);

          setIsImporting(false);
          setShowImportModal(false);
          setImportData([]); // Clear buffer
      }, 800);
  };

  // --- INLINE ADD HANDLERS ---
  const handleAddNewClick = () => {
    // If we are adding new, close edit mode if open
    setEditingId(null);
    setIsAddingNew(true);
    setNewLevel('T');
    setNewContent('');
  };

  const handleSaveNew = () => {
    if (!newContent.trim()) {
      alert("Vui lòng nhập nội dung nhận xét");
      return;
    }
    const newId = Date.now();
    const newComment: CommentItem = {
      id: newId,
      grade: selectedGrade,
      subject: selectedSubject,
      term: term,
      level: newLevel,
      content: newContent
    };

    setComments([newComment, ...comments]); 
    setIsAddingNew(false);
  };

  // --- INLINE EDIT HANDLERS ---
  const handleEditClick = (comment: CommentItem) => {
    // If adding new, close it
    setIsAddingNew(false);

    setEditingId(comment.id);
    setEditLevel(comment.level);
    setEditContent(comment.content);
  };

  const handleUpdateComment = () => {
     if (!editContent.trim()) {
        alert("Vui lòng nhập nội dung nhận xét");
        return;
     }

     setComments(prevComments => prevComments.map(c => 
        c.id === editingId 
        ? { ...c, level: editLevel, content: editContent }
        : c
     ));

     setEditingId(null);
  };

  const handleCancelEdit = () => {
     setEditingId(null);
  };

  const handleDelete = (id: number) => {
    if (confirm('Bạn có chắc chắn muốn xóa nhận xét này?')) {
        setComments(comments.filter(c => c.id !== id));
        if (editingId === id) {
            setEditingId(null);
        }
    }
  };

  return (
    <div className="flex flex-col h-full bg-gray-50/50">

      {/* 1. Header & Configuration */}
      <div className="bg-white border-b border-gray-200 p-6 shadow-sm">
         <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
             <div>
                <h1 className="text-2xl font-bold text-gray-800">Ngân hàng Nhận xét Cá nhân</h1>
                <p className="text-sm text-gray-500 mt-1">Quản lý kho nhận xét mẫu cho <span className="font-semibold text-blue-700">{currentUser.name}</span></p>
             </div>
             <div className="flex items-center gap-3 bg-blue-50 px-4 py-2 rounded-lg border border-blue-100">
                <span className="text-sm font-medium text-blue-800">Ưu tiên nguồn gợi ý:</span>
                <button 
                    onClick={() => setUseSystemBank(!useSystemBank)}
                    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${useSystemBank ? 'bg-gray-300' : 'bg-blue-600'}`}
                >
                    <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${useSystemBank ? 'translate-x-1' : 'translate-x-6'}`} />
                </button>
                <span className={`text-sm font-bold ${!useSystemBank ? 'text-blue-700' : 'text-gray-500'}`}>Cá nhân</span>
                <span className="text-gray-300">|</span>
                <span className={`text-sm font-bold ${useSystemBank ? 'text-gray-700' : 'text-gray-400'}`}>Hệ thống</span>
             </div>
         </div>

         {/* Filters */}
         <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Năm học</label>
               <select className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                  <option>2025-2026</option>
                  <option>2024-2025</option>
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Khối lớp</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedGrade}
                 onChange={(e) => setSelectedGrade(e.target.value)}
               >
                  {availableGrades.map(g => <option key={g} value={g}>{g}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Môn học</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedSubject}
                 onChange={(e) => setSelectedSubject(e.target.value)}
               >
                  {availableSubjects.map(s => <option key={s} value={s}>{s}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Học kỳ</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                 value={term}
                 onChange={(e) => setTerm(e.target.value)}
               >
                  <option>Giữa kỳ 1</option>
                  <option>Cuối kỳ 1</option>
                  <option>Giữa kỳ 2</option>
                  <option>Cuối năm</option>
               </select>
            </div>
         </div>
      </div>

      {/* 2. Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row justify-between items-center gap-4">
         {/* Search */}
         <div className="relative w-full md:w-96">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Tìm kiếm nội dung nhận xét..."
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-full focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
         </div>

         {/* Actions */}
         <div className="flex items-center gap-3 w-full md:w-auto">
             <button 
                onClick={handleDownloadTemplate}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-50 transition-colors whitespace-nowrap"
             >
                <Download size={16} />
                <span>Tải file mẫu</span>
             </button>
             <button 
                onClick={handleTriggerUpload}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Upload size={16} />
                <span>Tải lên & Cập nhật</span>
             </button>
             <input type="file" ref={fileInputRef} className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />

             <button 
                onClick={handleAddNewClick}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Plus size={16} />
                <span>Thêm mới</span>
             </button>
         </div>
      </div>

      {/* 3. Data Table */}
      <div className="flex-1 overflow-auto custom-scrollbar px-6 pb-6">
         <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden min-h-[400px]">
            <table className="w-full text-left border-collapse">
               <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold sticky top-0 z-10">
                  <tr>
                     <th className="px-6 py-4 w-16 text-center border-b">STT</th>
                     <th className="px-6 py-4 w-32 border-b">Mức độ</th>
                     <th className="px-6 py-4 border-b">Nội dung nhận xét</th>
                     <th className="px-6 py-4 w-32 text-center border-b">Hành động</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-gray-100">
                  {/* INLINE ADD ROW - ALWAYS AT TOP */}
                  {isAddingNew && (
                    <tr className="bg-blue-50 animate-in fade-in slide-in-from-top-2 duration-300 border-b border-blue-100 shadow-inner">
                      <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">#</td>
                      <td className="px-6 py-4">
                          <select 
                            className="w-full p-2 border border-gray-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                            value={newLevel}
                            onChange={(e) => setNewLevel(e.target.value as any)}
                          >
                            <option value="T">T</option>
                            <option value="H">H</option>
                            <option value="C">C</option>
                          </select>
                      </td>
                      <td className="px-6 py-4">
                          <input 
                            type="text"
                            autoFocus
                            className="w-full p-2 border border-blue-300 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white placeholder-gray-400 font-medium"
                            placeholder="Nhập nội dung nhận xét..."
                            value={newContent}
                            onChange={(e) => setNewContent(e.target.value)}
                            onKeyDown={(e) => {
                                if(e.key === 'Enter') handleSaveNew();
                                if(e.key === 'Escape') setIsAddingNew(false);
                            }}
                          />
                      </td>
                      <td className="px-6 py-4 text-center">
                          <div className="flex items-center justify-center gap-2">
                              <button onClick={handleSaveNew} className="p-2 text-white bg-green-500 hover:bg-green-600 rounded-lg transition-colors shadow-sm" title="Lưu">
                                  <Check size={16} />
                              </button>
                              <button onClick={() => setIsAddingNew(false)} className="p-2 text-gray-600 bg-white border border-gray-300 hover:bg-gray-100 rounded-lg transition-colors shadow-sm" title="Hủy">
                                  <X size={16} />
                              </button>
                          </div>
                      </td>
                    </tr>
                  )}

                  {processedComments.length > 0 ? (
                    processedComments.map((comment, index) => {
                      const isEditing = comment.id === editingId;

                      if (isEditing) {
                          return (
                              <tr key={comment.id} className="bg-white border-b border-gray-100 animate-in fade-in">
                                  <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                                  <td className="px-6 py-4">
                                      <select 
                                        className="w-full p-2 border border-blue-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                                        value={editLevel}
                                        onChange={(e) => setEditLevel(e.target.value as any)}
                                      >
                                        <option value="T">T</option>
                                        <option value="H">H</option>
                                        <option value="C">C</option>
                                      </select>
                                  </td>
                                  <td className="px-6 py-4">
                                      <input 
                                        type="text"
                                        autoFocus
                                        className="w-full p-2 border border-blue-400 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white font-medium text-gray-800"
                                        value={editContent}
                                        onChange={(e) => setEditContent(e.target.value)}
                                        onKeyDown={(e) => {
                                            if(e.key === 'Enter') handleUpdateComment();
                                            if(e.key === 'Escape') handleCancelEdit();
                                        }}
                                      />
                                  </td>
                                  <td className="px-6 py-4 text-center">
                                      <div className="flex items-center justify-center gap-3">
                                          <button 
                                            onClick={handleUpdateComment} 
                                            className="p-1.5 text-green-600 hover:text-green-700 hover:bg-green-50 rounded transition-colors"
                                            title="Lưu thay đổi"
                                          >
                                              <Save size={20} />
                                          </button>
                                          <button 
                                            onClick={handleCancelEdit} 
                                            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-50 rounded transition-colors"
                                            title="Hủy bỏ"
                                          >
                                              <X size={20} />
                                          </button>
                                      </div>
                                  </td>
                              </tr>
                          );
                      }

                      return (
                        <tr key={comment.id} className="hover:bg-blue-50/50 transition-colors group">
                           <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                           <td className="px-6 py-4">
                              <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg text-sm font-bold border ${
                                comment.level === 'T' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                comment.level === 'H' ? 'bg-cyan-50 text-cyan-700 border-cyan-200' :
                                'bg-orange-50 text-orange-700 border-orange-200'
                              }`}>
                                 {comment.level}
                              </span>
                           </td>
                           <td className="px-6 py-4 text-sm text-gray-800 leading-relaxed font-medium">
                              {comment.content}
                           </td>
                           <td className="px-6 py-4 text-center">
                              <div className="flex items-center justify-center gap-2">
                                 <button 
                                    onClick={() => handleEditClick(comment)}
                                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                    title="Chỉnh sửa"
                                 >
                                    <Edit size={16} />
                                 </button>
                                 <button 
                                    onClick={() => handleDelete(comment.id)}
                                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Xóa"
                                 >
                                    <Trash2 size={16} />
                                 </button>
                              </div>
                           </td>
                        </tr>
                      );
                    })
                  ) : (
                    !isAddingNew && (
                        <tr>
                            <td colSpan={4} className="px-6 py-20 text-center">
                            <div className="flex flex-col items-center justify-center text-gray-400">
                                <Info size={48} className="mb-4 text-gray-300" />
                                <p className="text-lg font-medium text-gray-500">Chưa có dữ liệu nhận xét</p>
                                <p className="text-sm mt-1 max-w-sm mx-auto">
                                    Vui lòng "Thêm mới" hoặc sử dụng chức năng "Tải lên" để nhập dữ liệu từ Excel cho môn <span className="font-bold text-gray-600">{selectedSubject}</span>.
                                </p>
                            </div>
                            </td>
                        </tr>
                    )
                  )}
               </tbody>
            </table>
         </div>
      </div>

      {/* Import Modal */}
      <CommentBankImportModal 
        isOpen={showImportModal}
        onClose={() => setShowImportModal(false)}
        importData={importData}
        onConfirm={handleConfirmImport}
        isLoading={isImporting}
      />

    </div>
  );
};

export default CommentBank;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserConfig, CommentItem, ImportRow } from '../types';
import { Download, Upload, Search, Trash2, Edit, Plus, Info, Check, X, Save } from 'lucide-react';
import CommentBankImportModal from './CommentBankImportModal';
import * as XLSX from 'xlsx';

interface CommentBankProps {
  currentUser: UserConfig;
}

const CommentBank: React.FC<CommentBankProps> = ({ currentUser }) => {
  // --- STATE ---
  const [selectedGrade, setSelectedGrade] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>('');
  const [term, setTerm] = useState('Cuối kỳ 1');
  const [useSystemBank, setUseSystemBank] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Inline Add State
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [newLevel, setNewLevel] = useState<'T' | 'H' | 'C'>('T');
  const [newContent, setNewContent] = useState('');

  // Inline Edit State
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editLevel, setEditLevel] = useState<'T' | 'H' | 'C'>('T');
  const [editContent, setEditContent] = useState('');

  // Dummy Data State
  const [comments, setComments] = useState<CommentItem[]>([
    { id: 1, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'T', content: 'Em tính toán nhanh, chính xác, hiểu bài tốt.' },
    { id: 2, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'H', content: 'Em nắm được kiến thức cơ bản, cần cẩn thận hơn khi tính toán.' },
    { id: 3, grade: 'Khối 04', subject: 'Tiếng Việt', term: 'Cuối kỳ 1', level: 'T', content: 'Đọc to, rõ ràng, diễn cảm. Chữ viết đẹp.' },
    { id: 4, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'T', content: 'Vocabulary retention is excellent. Participates actively.' },
    { id: 5, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'H', content: 'Good effort in speaking activities. Needs to work on spelling.' },
    { id: 6, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'C', content: 'Cần ôn lại bảng cửu chương.' },
  ]);

  // Import/Export States
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showImportModal, setShowImportModal] = useState(false);
  const [importData, setImportData] = useState<ImportRow[]>([]);
  const [isImporting, setIsImporting] = useState(false);

  // --- DERIVED STATE & EFFECTS ---

  // Get available Grades based on User Assignments
  const availableGrades = useMemo(() => {
    return Object.keys(currentUser.assignments).sort();
  }, [currentUser]);

  // Update Subject List when Grade Changes
  const availableSubjects = useMemo(() => {
    if (!selectedGrade) return [];
    return currentUser.assignments[selectedGrade] || [];
  }, [selectedGrade, currentUser]);

  // Auto-select Grade if user only has 1
  useEffect(() => {
    if (availableGrades.length > 0 && !availableGrades.includes(selectedGrade)) {
        setSelectedGrade(availableGrades[0]);
    }
  }, [availableGrades]);

  // Auto-select Subject if only 1 exists for the grade
  useEffect(() => {
    if (availableSubjects.length > 0) {
        // If current subject is not in the new list, select the first one
        if (!availableSubjects.includes(selectedSubject)) {
            setSelectedSubject(availableSubjects[0]);
        }
    } else {
        setSelectedSubject('');
    }
  }, [availableSubjects, selectedGrade]);


  // Filter AND Sort Comments
  const processedComments = useMemo(() => {
    // 1. Filter
    const filtered = comments.filter(c => {
        const matchGrade = c.grade === selectedGrade;
        const matchSubject = c.subject === selectedSubject;
        // In real app, match Term too if needed, here strict matching grade/subject
        const matchSearch = c.content.toLowerCase().includes(searchTerm.toLowerCase());
        return matchGrade && matchSubject && matchSearch;
    });

    // 2. Sort Logic
    // Priority 1: Level (T -> H -> C)
    // Priority 2: ID Descending (Newest first)
    return filtered.sort((a, b) => {
        const levelPriority: Record<string, number> = { 'T': 1, 'H': 2, 'C': 3 };

        const priorityA = levelPriority[a.level] || 4;
        const priorityB = levelPriority[b.level] || 4;

        if (priorityA !== priorityB) {
            return priorityA - priorityB; // Ascending priority (1, 2, 3)
        }

        // If levels are same, sort by ID descending (newest first)
        return b.id - a.id;
    });
  }, [comments, selectedGrade, selectedSubject, searchTerm]);

  // --- HANDLERS ---

  // 1. HANDLE DOWNLOAD TEMPLATE (Context-aware + Append Mode + Dropdown + Filename)
  const handleDownloadTemplate = () => {
    if (!selectedGrade || !selectedSubject) {
        alert("Vui lòng chọn Khối và Môn học trước khi tải mẫu.");
        return;
    }

    // Step 1: Get Existing Data for current context (Ignoring search term to export all relevant data)
    const existingData = comments.filter(c => 
        c.grade === selectedGrade && 
        c.subject === selectedSubject && 
        c.term === term
    );

    const rows = [];
    let currentRowIndex = 1;

    // Step 2: Write Existing Data
    existingData.forEach(item => {
        rows.push({
            'STT': currentRowIndex++,
            'Khối': item.grade,
            'Môn học': item.subject,
            'Học kỳ': item.term,
            'Mức độ (T/H/C)': item.level,
            'Nội dung nhận xét': item.content
        });
    });

    // Step 3: Append 50 Empty Rows with Context
    for (let i = 0; i < 50; i++) {
        rows.push({
            'STT': currentRowIndex++,
            'Khối': selectedGrade,
            'Môn học': selectedSubject,
            'Học kỳ': term,
            'Mức độ (T/H/C)': '', 
            'Nội dung nhận xét': '' 
        });
    }

    // Create workbook and worksheet
    const worksheet = XLSX.utils.json_to_sheet(rows);

    // Set column widths for better UX
    const wscols = [
        { wch: 5 },  // STT
        { wch: 10 }, // Khối
        { wch: 20 }, // Môn
        { wch: 15 }, // Học kỳ
        { wch: 15 }, // Mức độ (Col E)
        { wch: 60 }  // Nội dung
    ];
    worksheet['!cols'] = wscols;

    // --- ADD DATA VALIDATION (DROPDOWN) ---
    // Target: Column E (Mức độ), starting from row 2
    const endRow = rows.length + 1;
    const validationRange = `E2:E${endRow}`;

    // Note: SheetJS Community uses '!dataValidation' key
    // We cast to any to avoid TS errors if types aren't perfect
    (worksheet as any)['!dataValidation'] = [
      {
        sqref: validationRange,
        type: 'list',
        operator: 'equal',
        formula1: '"T,H,C"', // The allowed values
        showErrorMessage: true,
        errorTitle: 'Giá trị không hợp lệ',
        error: 'Vui lòng chọn T, H hoặc C từ danh sách.',
      }
    ];

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Mau_Nhan_Xet");

    // --- GENERATE FILENAME ---
    // Function to remove Vietnamese tones and standardise string
    const removeVietnameseTones = (str: string) => {
        return str
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/đ/g, 'd').replace(/Đ/g, 'D')
            .replace(/\s+/g, '_'); // Replace spaces with underscore
    };

    const cleanGrade = removeVietnameseTones(selectedGrade); // e.g., "Khoi_04"
    const cleanSubject = removeVietnameseTones(selectedSubject).replace(/_/g, ''); // e.g., "TiengViet" (remove underscores for subject)

    // Format: Mau_Nhan_Xet_Khoi_XX_Mon_TenMon.xlsx
    const fileName = `Mau_Nhan_Xet_${cleanGrade}_Mon_${cleanSubject}.xlsx`;

    // Trigger download
    XLSX.writeFile(workbook, fileName);
  };

  const handleTriggerUpload = () => {
    if (fileInputRef.current) {
        fileInputRef.current.value = ''; // Reset
        fileInputRef.current.click();
    }
  };

  // 2. HANDLE FILE UPLOAD & PREVIEW (3-Layer Filtering)
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();

      reader.onload = (evt) => {
          const bstr = evt.target?.result;
          if (!bstr) return;

          try {
              // Read the workbook
              const wb = XLSX.read(bstr, { type: 'binary' });
              const wsname = wb.SheetNames[0];
              const ws = wb.Sheets[wsname];
              const jsonData = XLSX.utils.sheet_to_json(ws);

              // --- DEDUPLICATION PREPARATION ---
              // Helper to generate signature: Grade|Subject|Term|Level|Content(normalized)
              const normalize = (str: string) => str ? String(str).trim().toLowerCase() : '';
              const generateSig = (g: string, s: string, t: string, l: string, c: string) => 
                  `${g}|${s}|${t}|${l}|${normalize(c)}`;

              // 1. Create Set of signatures from CURRENT DB (Layer 2: System Duplicate Filter)
              // We filter by the uploaded row's context later, but it's faster to verify against full DB or filtered DB.
              // Let's verify against ALL comments to prevent accidental dupes across different terms if needed, 
              // but prompt implies checking against "CurrentDB" (likely active context). 
              // However, strictly checking exact match of Grade/Sub/Term/Level/Content is safe globally.
              const existingSignatures = new Set(
                  comments.map(c => generateSig(c.grade, c.subject, c.term, c.level, c.content))
              );

              // 2. Create Set for tracking dupes WITHIN the file (Layer 3: File Duplicate Filter)
              const fileSignatures = new Set<string>();

              const parsedRows: ImportRow[] = [];

              jsonData.forEach((row: any, index: number) => {
                  // Map keys
                  const grade = row['Khối'] || selectedGrade;
                  const subject = row['Môn học'] || selectedSubject;
                  const t = row['Học kỳ'] || term;
                  const rawLevel = row['Mức độ (T/H/C)'];
                  const content = row['Nội dung nhận xét'];

                  // --- LAYER 1: EMPTY FILTER ---
                  // Logic: If both Level and Content are missing => Empty row => Skip
                  if (!rawLevel && !content) return; 

                  let level = '';
                  let isValid = true;
                  let error = '';

                  // Basic Validation
                  if (rawLevel) {
                      const cleanLevel = String(rawLevel).trim().toUpperCase();
                      if (['T', 'H', 'C'].includes(cleanLevel)) {
                          level = cleanLevel;
                      } else {
                          isValid = false;
                          error = 'Mức độ không hợp lệ (Phải là T, H hoặc C)';
                      }
                  } else {
                       if (content) { isValid = false; error = 'Thiếu mức độ'; }
                       else { return; } // Should be caught by top check
                  }

                  if (!content && level) {
                      isValid = false;
                      error = 'Thiếu nội dung nhận xét';
                  }

                  // --- LAYER 2 & 3: DUPLICATE FILTERS ---
                  // Only run duplicate checks if the row is syntactically valid so far (has content & level)
                  if (isValid) {
                      const sig = generateSig(grade, subject, t, level, content);

                      // Layer 2: Check System DB
                      if (existingSignatures.has(sig)) {
                          return; // SKIP: Already exists in system
                      }

                      // Layer 3: Check File Duplicates
                      if (fileSignatures.has(sig)) {
                          return; // SKIP: Duplicate within file
                      }

                      // Mark as seen in file
                      fileSignatures.add(sig);
                  }

                  // If we reached here, it's either a NEW valid row OR a row with Syntax Error (but not a duplicate)
                  parsedRows.push({
                      index,
                      grade,
                      subject,
                      term: t,
                      level,
                      content: content || '',
                      isValid,
                      error
                  });
              });

              if (parsedRows.length === 0) {
                  alert("Không tìm thấy dữ liệu mới. Tất cả các câu trong file đều đã tồn tại trên hệ thống hoặc file rỗng.");
                  return;
              }

              setImportData(parsedRows);
              setShowImportModal(true);

          } catch (error) {
              console.error("Error reading file:", error);
              alert("Đã xảy ra lỗi khi đọc file Excel. Vui lòng đảm bảo file đúng định dạng.");
          }
      };

      reader.readAsBinaryString(file);
  };

  const handleConfirmImport = () => {
      setIsImporting(true);

      // Simulate API call delay
      setTimeout(() => {
          const newComments = importData
            .filter(r => r.isValid)
            .map((r, idx) => ({
                id: Date.now() + idx, // Simple unique ID generation
                grade: r.grade,
                subject: r.subject,
                term: r.term,
                level: r.level as any,
                content: r.content
            }));

          if (newComments.length === 0) {
              alert("Không có dữ liệu hợp lệ để lưu.");
              setIsImporting(false);
              return;
          }

          // Merge with existing comments (newest first logic handled by Sort in useMemo)
          setComments(prev => [...newComments, ...prev]);

          setIsImporting(false);
          setShowImportModal(false);
          setImportData([]); // Clear buffer
      }, 800);
  };

  // --- INLINE ADD HANDLERS ---
  const handleAddNewClick = () => {
    // If we are adding new, close edit mode if open
    setEditingId(null);
    setIsAddingNew(true);
    setNewLevel('T');
    setNewContent('');
  };

  const handleSaveNew = () => {
    if (!newContent.trim()) {
      alert("Vui lòng nhập nội dung nhận xét");
      return;
    }
    const newId = Date.now();
    const newComment: CommentItem = {
      id: newId,
      grade: selectedGrade,
      subject: selectedSubject,
      term: term,
      level: newLevel,
      content: newContent
    };

    setComments([newComment, ...comments]); 
    setIsAddingNew(false);
  };

  // --- INLINE EDIT HANDLERS ---
  const handleEditClick = (comment: CommentItem) => {
    // If adding new, close it
    setIsAddingNew(false);

    setEditingId(comment.id);
    setEditLevel(comment.level);
    setEditContent(comment.content);
  };

  const handleUpdateComment = () => {
     if (!editContent.trim()) {
        alert("Vui lòng nhập nội dung nhận xét");
        return;
     }

     setComments(prevComments => prevComments.map(c => 
        c.id === editingId 
        ? { ...c, level: editLevel, content: editContent }
        : c
     ));

     setEditingId(null);
  };

  const handleCancelEdit = () => {
     setEditingId(null);
  };

  const handleDelete = (id: number) => {
    if (confirm('Bạn có chắc chắn muốn xóa nhận xét này?')) {
        setComments(comments.filter(c => c.id !== id));
        if (editingId === id) {
            setEditingId(null);
        }
    }
  };

  return (
    <div className="flex flex-col h-full bg-gray-50/50">

      {/* 1. Header & Configuration */}
      <div className="bg-white border-b border-gray-200 p-6 shadow-sm">
         <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
             <div>
                <h1 className="text-2xl font-bold text-gray-800">Ngân hàng Nhận xét Cá nhân</h1>
                <p className="text-sm text-gray-500 mt-1">Quản lý kho nhận xét mẫu cho <span className="font-semibold text-blue-700">{currentUser.name}</span></p>
             </div>
             <div className="flex items-center gap-3 bg-blue-50 px-4 py-2 rounded-lg border border-blue-100">
                <span className="text-sm font-medium text-blue-800">Ưu tiên nguồn gợi ý:</span>
                <button 
                    onClick={() => setUseSystemBank(!useSystemBank)}
                    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${useSystemBank ? 'bg-gray-300' : 'bg-blue-600'}`}
                >
                    <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${useSystemBank ? 'translate-x-1' : 'translate-x-6'}`} />
                </button>
                <span className={`text-sm font-bold ${!useSystemBank ? 'text-blue-700' : 'text-gray-500'}`}>Cá nhân</span>
                <span className="text-gray-300">|</span>
                <span className={`text-sm font-bold ${useSystemBank ? 'text-gray-700' : 'text-gray-400'}`}>Hệ thống</span>
             </div>
         </div>

         {/* Filters */}
         <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Năm học</label>
               <select className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                  <option>2025-2026</option>
                  <option>2024-2025</option>
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Khối lớp</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedGrade}
                 onChange={(e) => setSelectedGrade(e.target.value)}
               >
                  {availableGrades.map(g => <option key={g} value={g}>{g}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Môn học</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedSubject}
                 onChange={(e) => setSelectedSubject(e.target.value)}
               >
                  {availableSubjects.map(s => <option key={s} value={s}>{s}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Học kỳ</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                 value={term}
                 onChange={(e) => setTerm(e.target.value)}
               >
                  <option>Giữa kỳ 1</option>
                  <option>Cuối kỳ 1</option>
                  <option>Giữa kỳ 2</option>
                  <option>Cuối năm</option>
               </select>
            </div>
         </div>
      </div>

      {/* 2. Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row justify-between items-center gap-4">
         {/* Search */}
         <div className="relative w-full md:w-96">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Tìm kiếm nội dung nhận xét..."
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-full focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
         </div>

         {/* Actions */}
         <div className="flex items-center gap-3 w-full md:w-auto">
             <button 
                onClick={handleDownloadTemplate}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-50 transition-colors whitespace-nowrap"
             >
                <Download size={16} />
                <span>Tải file mẫu</span>
             </button>
             <button 
                onClick={handleTriggerUpload}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Upload size={16} />
                <span>Tải lên & Cập nhật</span>
             </button>
             <input type="file" ref={fileInputRef} className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />

             <button 
                onClick={handleAddNewClick}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Plus size={16} />
                <span>Thêm mới</span>
             </button>
         </div>
      </div>

      {/* 3. Data Table */}
      <div className="flex-1 overflow-auto custom-scrollbar px-6 pb-6">
         <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden min-h-[400px]">
            <table className="w-full text-left border-collapse">
               <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold sticky top-0 z-10">
                  <tr>
                     <th className="px-6 py-4 w-16 text-center border-b">STT</th>
                     <th className="px-6 py-4 w-32 border-b">Mức độ</th>
                     <th className="px-6 py-4 border-b">Nội dung nhận xét</th>
                     <th className="px-6 py-4 w-32 text-center border-b">Hành động</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-gray-100">
                  {/* INLINE ADD ROW - ALWAYS AT TOP */}
                  {isAddingNew && (
                    <tr className="bg-blue-50 animate-in fade-in slide-in-from-top-2 duration-300 border-b border-blue-100 shadow-inner">
                      <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">#</td>
                      <td className="px-6 py-4">
                          <select 
                            className="w-full p-2 border border-gray-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                            value={newLevel}
                            onChange={(e) => setNewLevel(e.target.value as any)}
                          >
                            <option value="T">T</option>
                            <option value="H">H</option>
                            <option value="C">C</option>
                          </select>
                      </td>
                      <td className="px-6 py-4">
                          <input 
                            type="text"
                            autoFocus
                            className="w-full p-2 border border-blue-300 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white placeholder-gray-400 font-medium"
                            placeholder="Nhập nội dung nhận xét..."
                            value={newContent}
                            onChange={(e) => setNewContent(e.target.value)}
                            onKeyDown={(e) => {
                                if(e.key === 'Enter') handleSaveNew();
                                if(e.key === 'Escape') setIsAddingNew(false);
                            }}
                          />
                      </td>
                      <td className="px-6 py-4 text-center">
                          <div className="flex items-center justify-center gap-2">
                              <button onClick={handleSaveNew} className="p-2 text-white bg-green-500 hover:bg-green-600 rounded-lg transition-colors shadow-sm" title="Lưu">
                                  <Check size={16} />
                              </button>
                              <button onClick={() => setIsAddingNew(false)} className="p-2 text-gray-600 bg-white border border-gray-300 hover:bg-gray-100 rounded-lg transition-colors shadow-sm" title="Hủy">
                                  <X size={16} />
                              </button>
                          </div>
                      </td>
                    </tr>
                  )}

                  {processedComments.length > 0 ? (
                    processedComments.map((comment, index) => {
                      const isEditing = comment.id === editingId;

                      if (isEditing) {
                          return (
                              <tr key={comment.id} className="bg-white border-b border-gray-100 animate-in fade-in">
                                  <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                                  <td className="px-6 py-4">
                                      <select 
                                        className="w-full p-2 border border-blue-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                                        value={editLevel}
                                        onChange={(e) => setEditLevel(e.target.value as any)}
                                      >
                                        <option value="T">T</option>
                                        <option value="H">H</option>
                                        <option value="C">C</option>
                                      </select>
                                  </td>
                                  <td className="px-6 py-4">
                                      <input 
                                        type="text"
                                        autoFocus
                                        className="w-full p-2 border border-blue-400 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white font-medium text-gray-800"
                                        value={editContent}
                                        onChange={(e) => setEditContent(e.target.value)}
                                        onKeyDown={(e) => {
                                            if(e.key === 'Enter') handleUpdateComment();
                                            if(e.key === 'Escape') handleCancelEdit();
                                        }}
                                      />
                                  </td>
                                  <td className="px-6 py-4 text-center">
                                      <div className="flex items-center justify-center gap-3">
                                          <button 
                                            onClick={handleUpdateComment} 
                                            className="p-1.5 text-green-600 hover:text-green-700 hover:bg-green-50 rounded transition-colors"
                                            title="Lưu thay đổi"
                                          >
                                              <Save size={20} />
                                          </button>
                                          <button 
                                            onClick={handleCancelEdit} 
                                            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-50 rounded transition-colors"
                                            title="Hủy bỏ"
                                          >
                                              <X size={20} />
                                          </button>
                                      </div>
                                  </td>
                              </tr>
                          );
                      }

                      return (
                        <tr key={comment.id} className="hover:bg-blue-50/50 transition-colors group">
                           <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">{index + 1}</td>
                           <td className="px-6 py-4">
                              <span className={`inline-flex items-center justify-center w-8 h-8 rounded-lg text-sm font-bold border ${
                                comment.level === 'T' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                comment.level === 'H' ? 'bg-cyan-50 text-cyan-700 border-cyan-200' :
                                'bg-orange-50 text-orange-700 border-orange-200'
                              }`}>
                                 {comment.level}
                              </span>
                           </td>
                           <td className="px-6 py-4 text-sm text-gray-800 leading-relaxed font-medium">
                              {comment.content}
                           </td>
                           <td className="px-6 py-4 text-center">
                              <div className="flex items-center justify-center gap-2">
                                 <button 
                                    onClick={() => handleEditClick(comment)}
                                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                    title="Chỉnh sửa"
                                 >
                                    <Edit size={16} />
                                 </button>
                                 <button 
                                    onClick={() => handleDelete(comment.id)}
                                    className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Xóa"
                                 >
                                    <Trash2 size={16} />
                                 </button>
                              </div>
                           </td>
                        </tr>
                      );
                    })
                  ) : (
                    !isAddingNew && (
                        <tr>
                            <td colSpan={4} className="px-6 py-20 text-center">
                            <div className="flex flex-col items-center justify-center text-gray-400">
                                <Info size={48} className="mb-4 text-gray-300" />
                                <p className="text-lg font-medium text-gray-500">Chưa có dữ liệu nhận xét</p>
                                <p className="text-sm mt-1 max-w-sm mx-auto">
                                    Vui lòng "Thêm mới" hoặc sử dụng chức năng "Tải lên" để nhập dữ liệu từ Excel cho môn <span className="font-bold text-gray-600">{selectedSubject}</span>.
                                </p>
                            </div>
                            </td>
                        </tr>
                    )
                  )}
               </tbody>
            </table>
         </div>
      </div>

      {/* Import Modal */}
      <CommentBankImportModal 
        isOpen={showImportModal}
        onClose={() => setShowImportModal(false)}
        importData={importData}
        onConfirm={handleConfirmImport}
        isLoading={isImporting}
      />

    </div>
  );
};

export default CommentBank;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserConfig, CommentItem, ImportRow } from '../types';
import { Download, Upload, Search, Trash2, Edit, Plus, Info, Check, X, Save, AlertTriangle } from 'lucide-react';
import CommentBankImportModal from './CommentBankImportModal';
import * as XLSX from 'xlsx';

interface CommentBankProps {
  currentUser: UserConfig;
}

const CommentBank: React.FC<CommentBankProps> = ({ currentUser }) => {
  // --- STATE ---
  const [selectedGrade, setSelectedGrade] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>('');
  const [term, setTerm] = useState('Cuối kỳ 1');
  const [useSystemBank, setUseSystemBank] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Inline Add State
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [newLevel, setNewLevel] = useState<'T' | 'H' | 'C'>('T');
  const [newContent, setNewContent] = useState('');

  // Inline Edit State
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editLevel, setEditLevel] = useState<'T' | 'H' | 'C'>('T');
  const [editContent, setEditContent] = useState('');

  // Delete Modal State
  const [deleteModal, setDeleteModal] = useState<{ isOpen: boolean; id: number | null }>({ isOpen: false, id: null });

  // Dummy Data State
  const [comments, setComments] = useState<CommentItem[]>([
    { id: 1, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'T', content: 'Em tính toán nhanh, chính xác, hiểu bài tốt.' },
    { id: 2, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'H', content: 'Em nắm được kiến thức cơ bản, cần cẩn thận hơn khi tính toán.' },
    { id: 3, grade: 'Khối 04', subject: 'Tiếng Việt', term: 'Cuối kỳ 1', level: 'T', content: 'Đọc to, rõ ràng, diễn cảm. Chữ viết đẹp.' },
    { id: 4, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'T', content: 'Vocabulary retention is excellent. Participates actively.' },
    { id: 5, grade: 'Khối 03', subject: 'Tiếng Anh', term: 'Cuối kỳ 1', level: 'H', content: 'Good effort in speaking activities. Needs to work on spelling.' },
    { id: 6, grade: 'Khối 04', subject: 'Toán', term: 'Cuối kỳ 1', level: 'C', content: 'Cần ôn lại bảng cửu chương.' },
  ]);

  // Import/Export States
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showImportModal, setShowImportModal] = useState(false);
  const [importData, setImportData] = useState<ImportRow[]>([]);
  const [isImporting, setIsImporting] = useState(false);

  // --- DERIVED STATE & EFFECTS ---

  // Get available Grades based on User Assignments
  const availableGrades = useMemo(() => {
    return Object.keys(currentUser.assignments).sort();
  }, [currentUser]);

  // Update Subject List when Grade Changes
  const availableSubjects = useMemo(() => {
    if (!selectedGrade) return [];
    return currentUser.assignments[selectedGrade] || [];
  }, [selectedGrade, currentUser]);

  // Auto-select Grade if user only has 1
  useEffect(() => {
    if (availableGrades.length > 0 && !availableGrades.includes(selectedGrade)) {
        setSelectedGrade(availableGrades[0]);
    }
  }, [availableGrades]);

  // Auto-select Subject if only 1 exists for the grade
  useEffect(() => {
    if (availableSubjects.length > 0) {
        // If current subject is not in the new list, select the first one
        if (!availableSubjects.includes(selectedSubject)) {
            setSelectedSubject(availableSubjects[0]);
        }
    } else {
        setSelectedSubject('');
    }
  }, [availableSubjects, selectedGrade]);


  // Filter AND Sort Comments
  const processedComments = useMemo(() => {
    // 1. Filter
    const filtered = comments.filter(c => {
        const matchGrade = c.grade === selectedGrade;
        const matchSubject = c.subject === selectedSubject;
        // In real app, match Term too if needed, here strict matching grade/subject
        const matchSearch = c.content.toLowerCase().includes(searchTerm.toLowerCase());
        return matchGrade && matchSubject && matchSearch;
    });

    // 2. Sort Logic
    // Priority 1: Level (T -> H -> C)
    // Priority 2: ID Descending (Newest first)
    return filtered.sort((a, b) => {
        const levelPriority: Record<string, number> = { 'T': 1, 'H': 2, 'C': 3 };

        const priorityA = levelPriority[a.level] || 4;
        const priorityB = levelPriority[b.level] || 4;

        if (priorityA !== priorityB) {
            return priorityA - priorityB; // Ascending priority (1, 2, 3)
        }

        // If levels are same, sort by ID descending (newest first)
        return b.id - a.id;
    });
  }, [comments, selectedGrade, selectedSubject, searchTerm]);

  // --- HANDLERS ---

  // 1. HANDLE DOWNLOAD TEMPLATE (Context-aware + Append Mode + Dropdown + Filename)
  const handleDownloadTemplate = () => {
    if (!selectedGrade || !selectedSubject) {
        alert("Vui lòng chọn Khối và Môn học trước khi tải mẫu.");
        return;
    }

    // Step 1: Get Existing Data for current context (Ignoring search term to export all relevant data)
    const existingData = comments.filter(c => 
        c.grade === selectedGrade && 
        c.subject === selectedSubject && 
        c.term === term
    );

    const rows = [];
    let currentRowIndex = 1;

    // Step 2: Write Existing Data
    existingData.forEach(item => {
        rows.push({
            'STT': currentRowIndex++,
            'Khối': item.grade,
            'Môn học': item.subject,
            'Học kỳ': item.term,
            'Mức độ (T/H/C)': item.level,
            'Nội dung nhận xét': item.content
        });
    });

    // Step 3: Append 50 Empty Rows with Context
    for (let i = 0; i < 50; i++) {
        rows.push({
            'STT': currentRowIndex++,
            'Khối': selectedGrade,
            'Môn học': selectedSubject,
            'Học kỳ': term,
            'Mức độ (T/H/C)': '', 
            'Nội dung nhận xét': '' 
        });
    }

    // Create workbook and worksheet
    const worksheet = XLSX.utils.json_to_sheet(rows);

    // Set column widths for better UX
    const wscols = [
        { wch: 5 },  // STT
        { wch: 10 }, // Khối
        { wch: 20 }, // Môn
        { wch: 15 }, // Học kỳ
        { wch: 15 }, // Mức độ (Col E)
        { wch: 60 }  // Nội dung
    ];
    worksheet['!cols'] = wscols;

    // --- ADD DATA VALIDATION (DROPDOWN) ---
    // Target: Column E (Mức độ), starting from row 2
    const endRow = rows.length + 1;
    const validationRange = `E2:E${endRow}`;

    // Note: SheetJS Community uses '!dataValidation' key
    // We cast to any to avoid TS errors if types aren't perfect
    (worksheet as any)['!dataValidation'] = [
      {
        sqref: validationRange,
        type: 'list',
        operator: 'equal',
        formula1: '"T,H,C"', // The allowed values
        showErrorMessage: true,
        errorTitle: 'Giá trị không hợp lệ',
        error: 'Vui lòng chọn T, H hoặc C từ danh sách.',
      }
    ];

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Mau_Nhan_Xet");

    // --- GENERATE FILENAME ---
    const removeVietnameseTones = (str: string) => {
        return str
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/đ/g, 'd').replace(/Đ/g, 'D')
            .replace(/\s+/g, '_'); 
    };

    const cleanGrade = removeVietnameseTones(selectedGrade);
    const cleanSubject = removeVietnameseTones(selectedSubject).replace(/_/g, '');

    // Format: Mau_Nhan_Xet_Khoi_XX_Mon_TenMon.xlsx
    const fileName = `Mau_Nhan_Xet_${cleanGrade}_Mon_${cleanSubject}.xlsx`;

    // Trigger download
    XLSX.writeFile(workbook, fileName);
  };

  const handleTriggerUpload = () => {
    if (fileInputRef.current) {
        fileInputRef.current.value = ''; // Reset
        fileInputRef.current.click();
    }
  };

  // 2. HANDLE FILE UPLOAD & PREVIEW (3-Layer Filtering)
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();

      reader.onload = (evt) => {
          const bstr = evt.target?.result;
          if (!bstr) return;

          try {
              // Read the workbook
              const wb = XLSX.read(bstr, { type: 'binary' });
              const wsname = wb.SheetNames[0];
              const ws = wb.Sheets[wsname];
              const jsonData = XLSX.utils.sheet_to_json(ws);

              // Deduplication Preparation
              const normalize = (str: string) => str ? String(str).trim().toLowerCase() : '';
              const generateSig = (g: string, s: string, t: string, l: string, c: string) => 
                  `${g}|${s}|${t}|${l}|${normalize(c)}`;

              const existingSignatures = new Set(
                  comments.map(c => generateSig(c.grade, c.subject, c.term, c.level, c.content))
              );
              const fileSignatures = new Set<string>();
              const parsedRows: ImportRow[] = [];

              jsonData.forEach((row: any, index: number) => {
                  const grade = row['Khối'] || selectedGrade;
                  const subject = row['Môn học'] || selectedSubject;
                  const t = row['Học kỳ'] || term;
                  const rawLevel = row['Mức độ (T/H/C)'];
                  const content = row['Nội dung nhận xét'];

                  // Layer 1: Empty Filter
                  if (!rawLevel && !content) return; 

                  let level = '';
                  let isValid = true;
                  let error = '';

                  // Basic Validation
                  if (rawLevel) {
                      const cleanLevel = String(rawLevel).trim().toUpperCase();
                      if (['T', 'H', 'C'].includes(cleanLevel)) {
                          level = cleanLevel;
                      } else {
                          isValid = false;
                          error = 'Mức độ không hợp lệ (Phải là T, H hoặc C)';
                      }
                  } else {
                       if (content) { isValid = false; error = 'Thiếu mức độ'; }
                       else { return; } 
                  }

                  if (!content && level) {
                      isValid = false;
                      error = 'Thiếu nội dung nhận xét';
                  }

                  // Layers 2 & 3: Duplicate Filters
                  if (isValid) {
                      const sig = generateSig(grade, subject, t, level, content);
                      if (existingSignatures.has(sig)) return; // System dupe
                      if (fileSignatures.has(sig)) return; // File dupe
                      fileSignatures.add(sig);
                  }

                  parsedRows.push({
                      index,
                      grade,
                      subject,
                      term: t,
                      level,
                      content: content || '',
                      isValid,
                      error
                  });
              });

              if (parsedRows.length === 0) {
                  alert("Không tìm thấy dữ liệu mới. Tất cả các câu trong file đều đã tồn tại trên hệ thống hoặc file rỗng.");
                  return;
              }

              setImportData(parsedRows);
              setShowImportModal(true);

          } catch (error) {
              console.error("Error reading file:", error);
              alert("Đã xảy ra lỗi khi đọc file Excel. Vui lòng đảm bảo file đúng định dạng.");
          }
      };

      reader.readAsBinaryString(file);
  };

  const handleConfirmImport = () => {
      setIsImporting(true);
      setTimeout(() => {
          const newComments = importData
            .filter(r => r.isValid)
            .map((r, idx) => ({
                id: Date.now() + idx,
                grade: r.grade,
                subject: r.subject,
                term: r.term,
                level: r.level as any,
                content: r.content
            }));

          if (newComments.length === 0) {
              alert("Không có dữ liệu hợp lệ để lưu.");
              setIsImporting(false);
              return;
          }

          setComments(prev => [...newComments, ...prev]);
          setIsImporting(false);
          setShowImportModal(false);
          setImportData([]); 
      }, 800);
  };

  // --- INLINE ADD HANDLERS ---
  const handleAddNewClick = () => {
    setEditingId(null);
    setIsAddingNew(true);
    setNewLevel('T');
    setNewContent('');
  };

  const handleSaveNew = () => {
    if (!newContent.trim()) {
      alert("Vui lòng nhập nội dung nhận xét");
      return;
    }
    const newId = Date.now();
    const newComment: CommentItem = {
      id: newId,
      grade: selectedGrade,
      subject: selectedSubject,
      term: term,
      level: newLevel,
      content: newContent
    };

    setComments([newComment, ...comments]); 
    setIsAddingNew(false);
  };

  // --- INLINE EDIT HANDLERS ---
  const handleEditClick = (comment: CommentItem) => {
    setIsAddingNew(false);
    setEditingId(comment.id);
    setEditLevel(comment.level);
    setEditContent(comment.content);
  };

  const handleUpdateComment = () => {
     if (!editContent.trim()) {
        alert("Vui lòng nhập nội dung nhận xét");
        return;
     }

     setComments(prevComments => prevComments.map(c => 
        c.id === editingId 
        ? { ...c, level: editLevel, content: editContent }
        : c
     ));

     setEditingId(null);
  };

  const handleCancelEdit = () => {
     setEditingId(null);
  };

  // --- DELETE HANDLERS ---
  const handleDeleteClick = (id: number) => {
    setDeleteModal({ isOpen: true, id });
  };

  const handleConfirmDelete = () => {
    if (deleteModal.id !== null) {
        setComments(comments.filter(c => c.id !== deleteModal.id));
        if (editingId === deleteModal.id) {
            setEditingId(null);
        }
    }
    setDeleteModal({ isOpen: false, id: null });
  };

  return (
    <div className="flex flex-col h-full bg-gray-50/50">

      {/* 1. Header & Configuration */}
      <div className="bg-white border-b border-gray-200 p-6 shadow-sm shrink-0">
         <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
             <div>
                <h1 className="text-2xl font-bold text-gray-800">Ngân hàng Nhận xét Cá nhân</h1>
                <p className="text-sm text-gray-500 mt-1">Quản lý kho nhận xét mẫu cho <span className="font-semibold text-blue-700">{currentUser.name}</span></p>
             </div>
             <div className="flex items-center gap-3 bg-blue-50 px-4 py-2 rounded-lg border border-blue-100">
                <span className="text-sm font-medium text-blue-800">Ưu tiên nguồn gợi ý:</span>
                <button 
                    onClick={() => setUseSystemBank(!useSystemBank)}
                    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${useSystemBank ? 'bg-gray-300' : 'bg-blue-600'}`}
                >
                    <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${useSystemBank ? 'translate-x-1' : 'translate-x-6'}`} />
                </button>
                <span className={`text-sm font-bold ${!useSystemBank ? 'text-blue-700' : 'text-gray-500'}`}>Cá nhân</span>
                <span className="text-gray-300">|</span>
                <span className={`text-sm font-bold ${useSystemBank ? 'text-gray-700' : 'text-gray-400'}`}>Hệ thống</span>
             </div>
         </div>

         {/* Filters */}
         <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Năm học</label>
               <select className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                  <option>2025-2026</option>
                  <option>2024-2025</option>
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Khối lớp</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedGrade}
                 onChange={(e) => setSelectedGrade(e.target.value)}
               >
                  {availableGrades.map(g => <option key={g} value={g}>{g}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Môn học</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                 value={selectedSubject}
                 onChange={(e) => setSelectedSubject(e.target.value)}
               >
                  {availableSubjects.map(s => <option key={s} value={s}>{s}</option>)}
               </select>
            </div>
            <div className="flex flex-col gap-1.5">
               <label className="text-xs font-bold text-gray-500 uppercase tracking-wide">Học kỳ</label>
               <select 
                 className="input-field border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                 value={term}
                 onChange={(e) => setTerm(e.target.value)}
               >
                  <option>Giữa kỳ 1</option>
                  <option>Cuối kỳ 1</option>
                  <option>Giữa kỳ 2</option>
                  <option>Cuối năm</option>
               </select>
            </div>
         </div>
      </div>

      {/* 2. Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row justify-between items-center gap-4 shrink-0">
         {/* Search */}
         <div className="relative w-full md:w-96">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Tìm kiếm nội dung nhận xét..."
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-full focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
         </div>

         {/* Actions */}
         <div className="flex items-center gap-3 w-full md:w-auto">
             <button 
                onClick={handleDownloadTemplate}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-50 transition-colors whitespace-nowrap"
             >
                <Download size={16} />
                <span>Tải file mẫu</span>
             </button>
             <button 
                onClick={handleTriggerUpload}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Upload size={16} />
                <span>Tải lên & Cập nhật</span>
             </button>
             <input type="file" ref={fileInputRef} className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />

             <button 
                onClick={handleAddNewClick}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors shadow-sm whitespace-nowrap"
             >
                <Plus size={16} />
                <span>Thêm mới</span>
             </button>
         </div>
      </div>

      {/* 3. Data Table - Updated for Sticky Header */}
      <div className="flex-1 flex flex-col min-h-0 px-6 pb-6">
         <div className="flex-1 overflow-auto custom-scrollbar bg-white border border-gray-200 rounded-xl shadow-sm relative">
            <table className="w-full text-left border-collapse">
               <thead className="bg-gray-50 text-gray-600 uppercase text-xs font-bold sticky top-0 z-10 shadow-sm">
                  <tr>
                     <th className="px-6 py-4 w-16 text-center border-b bg-gray-50">STT</th>
                     <th className="px-6 py-4 w-32 border-b bg-gray-50">Mức độ</th>
                     <th className="px-6 py-4 border-b bg-gray-50">Nội dung nhận xét</th>
                     <th className="px-6 py-4 w-32 text-center border-b bg-gray-50">Hành động</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-gray-100">
                  {/* INLINE ADD ROW - ALWAYS AT TOP */}
                  {isAddingNew && (
                    <tr className="bg-blue-50 animate-in fade-in slide-in-from-top-2 duration-300 border-b border-blue-100 shadow-inner">
                      <td className="px-6 py-4 text-center text-sm text-gray-500 font-medium">#</td>
                      <td className="px-6 py-4">
                          <select 
                            className="w-full p-2 border border-gray-300 rounded-md text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none bg-white text-gray-700"
                            value={newLevel}
                            onChange={(e) => setNewLevel(e.target.value as any)}
                          >
                            <option value="T">T</option>
                            <option value="H">H</option>
                            <option value="C">C</option>
                          </select>
                      </td>
                      <td className="px-6 py-4">
                          <input 
                            type="text"
                            autoFocus
                            className="w-full p-2 border border-blue-300 rounded-md text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white placeholder-gray-400 font-medium"
                            placeholder="Nhập nội dung nhận xét..."
                            value={newContent}
                            onChange={(e) => setNewContent(e.target.value)}
                            onKeyDown={(e) => {
                                if(e.key === 'Enter') handleSaveNew();
                                if(e.key === 'Escape') setIsAddingNew(false);
                            }}
                          />
                      </td>
                      <td className="px-6 py-4 text-center">
                          <div className="flex items-center justify-center gap-2">
                              <button onClick={handleSaveNew} className="p-2 text-white bg-green-500 hover:bg-green-600 rounded-lg transition-colors shadow-sm" title="Lưu">
                                  <Check size={16} />
                              </button>
                              <button onClick={() => setIsAddingNew(false)} className="p-2 text-gray-600 bg-white border border-gray-300 hover:bg-gray-100 rounded-lg transition-colors shadow-sm" title="Hủy">
                                  <X size={16} />
                              </button>
                          </div>
                      </td>
