                                    title="Xóa"
                                 >
                                    <Trash2 size={16} />
                                 </button>
                              </div>
                           </td>
                        </tr>
                      );
                    })
                  ) : (
                    !isAddingNew && (
                        <tr>
                            <td colSpan={4} className="px-6 py-20 text-center">
