import React from 'react';
import { X, Printer } from 'lucide-react';
import { SUBJECTS_BY_CLASS, STUDENTS_DATA } from '../constants';
import { Student } from '../types';

interface ReportPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedStudents?: Student[];
  currentTerm?: string;
  visibleColumns?: string[]; // New prop
}

const CORE_COMPETENCIES = [
  'Tự chủ và tự học',
  'Giao tiếp và hợp tác',
  'Giải quyết vấn đề và sáng tạo'
];

const KEY_QUALITIES = [
  'Yêu nước',
  'Nhân ái',
  'Chăm chỉ',
  'Trung thực',
  'Trách nhiệm'
];

const ReportPreviewModal: React.FC<ReportPreviewModalProps> = ({ 
  isOpen, 
  onClose, 
  selectedStudents = [], 
  currentTerm = 'Cuối kỳ 1',
  visibleColumns = ['gk1', 'ck1'] // Default if not provided
}) => {
  if (!isOpen) return null;

  const displayStudents = selectedStudents.length > 0 ? selectedStudents : [STUDENTS_DATA[0]];
  const isYearEnd = currentTerm === 'Cuối năm';

  // Define the column config
  const columnConfig = [
    { key: 'gk1', label: 'Giữa HK 1', bg: 'bg-gray-50' },
    { key: 'ck1', label: 'Cuối HK 1', bg: 'bg-gray-100' },
    { key: 'gk2', label: 'Giữa HK 2', bg: 'bg-gray-50' },
    { key: 'cn', label: 'Cuối Năm', bg: 'bg-gray-100' },
  ];

  // Filter columns to show based on prop
  const activeColumns = columnConfig.filter(col => visibleColumns.includes(col.key));

  const getSpecificCompetencies = (className: string) => {
    const basic = ['Ngôn ngữ', 'Tính toán', 'Khoa học', 'Thẩm mỹ', 'Thể chất'];
    if (className === '5A2') {
       return ['Ngôn ngữ', 'Tính toán', 'Khoa học', 'Công nghệ', 'Tin học', 'Thẩm mỹ', 'Thể chất'];
    }
    return basic;
  };

  const getDeterministicValue = (seed: string, offset: number, range: number) => {
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
      hash = (hash << 5) - hash + seed.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash + offset) % range;
  };

  const hasScoreForPeriod = (className: string, subject: string, period: string) => {
    if (className === '1A2') {
        if (!['Toán', 'Tiếng Việt'].includes(subject)) return false;
        return period.includes('Cuối'); 
    }
    if (className === '5A2') {
        if (['Toán', 'Tiếng Việt'].includes(subject)) return true; 
        if (['Khoa học', 'Lịch sử và Địa lý', 'Ngoại ngữ 1', 'Tin học và Công nghệ'].includes(subject)) {
            return period.includes('Cuối');
        }
        return false;
    }
    return false;
  };

  const generateGradeData = (student: Student, subjName: string) => {
    const seed = `${student.id}-${subjName}`;
    const levels = ['T', 'H'];

    // Map data keys to column keys
    const periods = [
        { key: 'gk1', label: 'Giữa kỳ 1' },
        { key: 'ck1', label: 'Cuối kỳ 1' },
        { key: 'gk2', label: 'Giữa kỳ 2' },
        { key: 'cn', label: 'Cuối năm' }
    ];

    const data: any = {};

    periods.forEach((p, idx) => {
        const hasScore = hasScoreForPeriod(student.className, subjName, p.label);
        data[p.key] = {
            m: levels[getDeterministicValue(seed, (idx + 1) * 10, 2)],
            d: hasScore ? (7 + getDeterministicValue(seed, (idx + 1) * 15, 30) / 10).toFixed(0) : ''
        };
    });

    data.kqgd = ['T', 'H'][getDeterministicValue(seed, 90, 2)];
    return data;
  };

  const generateCompetencyData = (student: Student, name: string) => {
    const seed = `${student.id}-${name}`;
    const levels = ['T', 'Đ', 'T']; 

    const gk1 = levels[getDeterministicValue(seed, 10, 3)];
    const ck1 = levels[getDeterministicValue(seed, 20, 3)];
    const gk2 = levels[getDeterministicValue(seed, 30, 3)];
    const cn = levels[getDeterministicValue(seed, 40, 3)];

    return { gk1, ck1, gk2, cn };
  };

  const getGroupComment = (student: Student, groupTitle: string) => {
      const seed = `${student.id}-${groupTitle}`;
      const goodComments = [
        "Hoàn thành tốt nhiệm vụ.",
        "Có ý thức tự giác, tích cực.",
        "Thực hiện tốt các yêu cầu.",
        "Năng nổ, chủ động trong học tập."
      ];
      const avgComments = [
        "Hoàn thành nhiệm vụ.",
        "Cần mạnh dạn hơn.",
        "Có cố gắng trong học tập.",
        "Thực hiện đầy đủ yêu cầu."
      ];

      const isGood = getDeterministicValue(seed, 25, 10) > 3;
      const pool = isGood ? goodComments : avgComments;

      return pool[getDeterministicValue(seed, 42, pool.length)];
  };

  const getOverallAssessment = (student: Student) => {
    const seed = student.id; 
    const val = getDeterministicValue(seed, 99, 10); 

    if (val >= 3) {
        return {
            khenThuong: "Học sinh Xuất sắc",
            kqgd: "Hoàn thành Xuất sắc",
            nhanXet: "Con ngoan, lễ phép, tiếp thu bài nhanh. Hoàn thành xuất sắc các nội dung học tập và rèn luyện.",
            trangThai: "Được lên lớp"
        };
    } else if (val >= 1) {
        return {
            khenThuong: "Học sinh Tiêu biểu",
            kqgd: "Hoàn thành Tốt",
            nhanXet: "Con chăm chỉ, có ý thức học tập tốt. Cần phát huy hơn nữa trong năm học tới.",
            trangThai: "Được lên lớp"
        };
    } else {
        return {
            khenThuong: "",
            kqgd: "Hoàn thành",
            nhanXet: "Con cần cố gắng rèn chữ viết và tính toán cẩn thận hơn.",
            trangThai: val === 0 ? "Rèn luyện lại trong hè" : "Được lên lớp"
        };
    }
  };

  const renderStudentReport = (student: Student, index: number) => {
    const className = student.className;
    const classSubjects = SUBJECTS_BY_CLASS[className] || SUBJECTS_BY_CLASS['1A2'];
    const specificCompetencies = getSpecificCompetencies(className);
    const overall = getOverallAssessment(student);

    const subjects = classSubjects.map((name, idx) => {
      const grades = generateGradeData(student, name);
      return {
        stt: idx + 1,
        name: name,
        ...grades, 
        note: grades.cn.m === 'T' ? 'Nắm vững kiến thức.' : 'Hoàn thành yêu cầu.'
      };
    });

    const groups = [
      { title: 'Năng lực chung', items: CORE_COMPETENCIES, startIdx: 1 },
      { title: 'Năng lực đặc thù', items: specificCompetencies, startIdx: 2 },
      { title: 'Phẩm chất chủ yếu', items: KEY_QUALITIES, startIdx: 3 }
    ];

    return (
      <div key={student.id} className={`flex flex-col items-center w-full ${index > 0 ? 'print:break-before-page mt-12 pt-12 border-t-2 border-dashed border-gray-300 print:border-none print:mt-0 print:pt-0' : ''}`}>
        <div className="w-full max-w-[900px] bg-white shadow-2xl p-8 md:p-12 min-h-[1100px] text-gray-900 font-serif leading-relaxed print:shadow-none print:p-0">
          <div className="text-center mb-6">
            <h2 className="text-[13px] font-bold uppercase tracking-wide mb-1 leading-none">SỞ GIÁO DỤC VÀ ĐÀO TẠO TP.HCM</h2>
            <h2 className="text-[13px] font-bold uppercase tracking-wide border-b border-black inline-block px-4 pb-1 mb-4 leading-none">TRƯỜNG TIỂU HỌC LAM SƠN</h2>

            <h1 className="text-xl md:text-2xl font-bold uppercase tracking-normal mb-1 text-[#1e293b]">PHIẾU BÁO KẾT QUẢ HỌC TẬP VÀ RÈN LUYỆN</h1>
            <p className="text-[14px] font-bold text-[#1e293b]">Năm học: 2025 - 2026</p>
            <p className="text-[14px] font-semibold italic text-blue-700">({isYearEnd ? 'Cuối năm học' : currentTerm})</p>
          </div>

          <div className="mb-4 text-[14px] font-serif">
            <div className="flex items-end mb-2">
              <span className="font-bold whitespace-nowrap mr-2">Họ và tên học sinh:</span>
              <span className="font-bold flex-1 border-b border-dotted border-gray-400 pb-0.5">{student.name}</span>
            </div>
            <div className="flex items-end gap-8">
                <div className="flex items-end w-[35%]">
                    <span className="font-bold whitespace-nowrap mr-2">Lớp:</span>
                    <span className="flex-1 border-b border-dotted border-gray-400 pb-0.5 pl-2">{className}</span>
                </div>
                <div className="flex items-end flex-1">
                    <span className="font-bold whitespace-nowrap mr-2">Ngày sinh:</span>
                    <span className="flex-1 border-b border-dotted border-gray-400 pb-0.5 pl-2">{student.dob}</span>
                </div>
            </div>
          </div>

          <h3 className="font-bold text-sm mb-4 font-sans uppercase text-blue-800">I. Các môn học và hoạt động giáo dục</h3>

          <table className="w-full border-collapse border border-gray-800 text-[12px] font-sans mb-6 table-fixed">
            <thead>
              <tr className="bg-gray-100/50">
                <th rowSpan={2} className="border border-gray-800 p-1 text-center w-8">STT</th>
                <th rowSpan={2} className="border border-gray-800 p-1 text-left w-32">Môn học và hoạt động giáo dục</th>

                {/* Dynamic Header Row 1: Periods */}
                {activeColumns.map(col => (
                    <th key={col.key} colSpan={2} className={`border border-gray-800 p-1 text-center ${col.bg}`}>
                        {col.label}
                    </th>
                ))}

                <th rowSpan={2} className="border border-gray-800 p-1 text-center">Nhận xét</th>
              </tr>
              <tr className="bg-gray-100/50">
                 {/* Dynamic Header Row 2: Level/Score */}
                 {activeColumns.map(col => (
                    <React.Fragment key={`${col.key}-sub`}>
                        <th className="border border-gray-800 p-0.5 text-center text-[10px] w-8">Mức</th>
                        <th className="border border-gray-800 p-0.5 text-center text-[10px] w-8">Điểm</th>
                    </React.Fragment>
                 ))}
              </tr>
            </thead>
            <tbody>
              {subjects.map((sub) => {
                  const cellClass = "border border-gray-800 p-1 text-center font-semibold text-[11px]";
                  const scoreClass = "border border-gray-800 p-1 text-center font-bold text-blue-700 text-[11px]";

                  return (
                    <tr key={sub.stt} className="hover:bg-gray-50/50">
                        <td className="border border-gray-800 p-1 text-center">{sub.stt}</td>
                        <td className="border border-gray-800 p-1 font-medium truncate">{sub.name}</td>

                        {/* Dynamic Body Cells */}
                        {activeColumns.map(col => {
                            const data = (sub as any)[col.key]; // Access dynamic key like sub.gk1
                            return (
                                <React.Fragment key={`${col.key}-${sub.stt}`}>
                                    <td className={`${cellClass} ${col.bg}`}>{data?.m}</td>
                                    <td className={`${scoreClass} ${col.bg}`}>{data?.d}</td>
                                </React.Fragment>
                            );
                        })}

                        <td className="border border-gray-800 p-1 text-[11px] align-middle italic text-gray-700 leading-tight">{sub.note}</td>
                    </tr>
                  )
              })}
            </tbody>
          </table>

          <div className="text-[11px] italic mb-8 font-sans flex flex-wrap gap-6 text-gray-600">
            <div><b>Mức đạt được:</b> T: Hoàn thành tốt, H: Hoàn thành, C: Chưa hoàn thành.</div>
            <div><b>KQGD:</b> Kết quả giáo dục (T/H/C).</div>
          </div>

          <div className="mb-4 font-sans print:break-before-page">
             <h3 className="font-bold text-sm mb-3 uppercase text-blue-800 pt-4 print:pt-8">II. Đánh giá phẩm chất và năng lực</h3>

             <table className="w-full border-collapse border border-gray-800 text-[12px] font-sans table-fixed">
              <thead>
                <tr className="bg-gray-100/50">
                  <th rowSpan={2} className="border border-gray-800 p-1 text-center w-8">STT</th>
                  <th rowSpan={2} className="border border-gray-800 p-1 text-center w-24">Nhóm năng lực</th>
                  <th rowSpan={2} className="border border-gray-800 p-1 text-left w-32">Tiêu chí đánh giá</th>

                  {/* Dynamic Header for Competencies */}
                  {activeColumns.map(col => (
                      <th key={col.key} className={`border border-gray-800 p-1 text-center ${col.bg} w-14`}>
                          {col.label}
                      </th>
                  ))}

                  <th rowSpan={2} className="border border-gray-800 p-1 text-center">Nhận xét</th>
                </tr>
                <tr className="bg-gray-100/50">
                  {/* Dynamic Sub-header for Competencies */}
                  {activeColumns.map(col => (
                      <th key={`${col.key}-sub`} className="border border-gray-800 p-1 text-center font-bold text-[10px]">Mức</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                  {groups.map((group) => {
                     const groupComment = getGroupComment(student, group.title);

                     return group.items.map((item, itemIdx) => {
                        const scores: any = generateCompetencyData(student, item); // returns {gk1, ck1...}
                        const isFirst = itemIdx === 0;
                        const rowSpan = group.items.length;

                        return (
                            <tr key={`${group.title}-${item}`} className="hover:bg-gray-50/50">
                                {isFirst && (
                                    <>
                                        <td rowSpan={rowSpan} className="border border-gray-800 p-1 text-center align-middle font-bold">{group.startIdx}</td>
                                        <td rowSpan={rowSpan} className="border border-gray-800 p-2 align-middle">
                                            <div className="font-bold uppercase text-[11px] text-blue-800">{group.title}</div>
                                        </td>
                                    </>
                                )}

                                <td className="border border-gray-800 p-1 align-middle pl-2 text-[11px]">
                                   - {item}
                                </td>

                                {/* Dynamic Body Cells for Competencies */}
                                {activeColumns.map(col => (
                                    <td key={col.key} className={`border border-gray-800 p-1 text-center align-middle text-[11px] font-semibold ${col.bg}`}>
                                        {scores[col.key]}
                                    </td>
                                ))}

                                {isFirst && (
                                    <td rowSpan={rowSpan} className="border border-gray-800 p-1 text-[11px] italic text-gray-700 align-middle text-left px-2">
                                        {groupComment}
                                    </td>
                                )}
                            </tr>
                        );
                     });
                  })}
              </tbody>
            </table>
          </div>

          {isYearEnd && (
             <div className="mb-6 text-[13px] font-sans px-1">
                <div className="grid grid-cols-2 gap-x-12 gap-y-3">
                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Khen thưởng:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 font-medium">
                         {overall.khenThuong}
                       </span>
                    </div>
                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Trạng thái:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 font-bold">
                         {overall.trangThai}
                       </span>
                    </div>

                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Đánh giá KQGD:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 font-bold uppercase">
                         {overall.kqgd}
                       </span>
                    </div>
                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Nhận xét:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 italic truncate">
                         {overall.nhanXet}
                       </span>
                    </div>
                </div>
             </div>
          )}

          <div className="grid grid-cols-2 gap-10 mt-10 text-center text-sm font-sans">
            <div className="flex flex-col items-center">
              <p className="italic mb-2 text-gray-500">.........., ngày ..... tháng ..... năm 2026</p>
              <p className="font-bold uppercase text-gray-800">PHỤ HUYNH HỌC SINH</p>
              <div className="h-24"></div>
              <p className="font-semibold text-gray-400 italic">(Ký và ghi rõ họ tên)</p>
            </div>
            <div className="flex flex-col items-center">
              <p className="italic mb-2 text-gray-500">TP.HCM, ngày {new Date().getDate()} tháng {new Date().getMonth() + 1} năm {new Date().getFullYear()}</p>
              <p className="font-bold uppercase text-gray-800">GIÁO VIÊN CHỦ NHIỆM</p>
              <div className="h-24"></div>
              <p className="font-bold text-gray-900 border-b border-gray-900 inline-block px-4">Nguyễn Thị Anh</p>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[9999] flex flex-col bg-gray-500/40 backdrop-blur-sm overflow-hidden animate-in fade-in duration-200">
      <div className="bg-white border-b border-gray-200 px-6 py-3 flex items-center justify-between shadow-md sticky top-0 z-10 print:hidden">
        <h2 className="text-gray-800 font-bold text-lg">Xem trước {displayStudents.length} Phiếu điểm - {currentTerm}</h2>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => window.print()}
            className="flex items-center gap-2 px-5 py-2 bg-[#2563eb] text-white rounded-md font-semibold hover:bg-blue-700 transition-colors shadow-sm"
          >
            <Printer size={18} />
            In Phiếu Điểm ({displayStudents.length})
          </button>
          <button 
            onClick={onClose}
            className="p-1.5 text-gray-500 hover:text-gray-800 hover:bg-gray-100 rounded-lg transition-all"
          >
            <X size={24} />
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-auto p-4 md:p-10 flex flex-col items-center bg-gray-200/50 custom-scrollbar">
        {displayStudents.map((student, index) => renderStudentReport(student, index))}
      </div>
    </div>
  );
};

export default ReportPreviewModal;

import React from 'react';
import { X, Printer } from 'lucide-react';
import { SUBJECTS_BY_CLASS, STUDENTS_DATA } from '../constants';
import { Student } from '../types';

interface ReportPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedStudents?: Student[];
  currentTerm?: string;
  visibleColumns?: string[]; // New prop
}

const CORE_COMPETENCIES = [
  'Tự chủ và tự học',
  'Giao tiếp và hợp tác',
  'Giải quyết vấn đề và sáng tạo'
];

const KEY_QUALITIES = [
  'Yêu nước',
  'Nhân ái',
  'Chăm chỉ',
  'Trung thực',
  'Trách nhiệm'
];

const ReportPreviewModal: React.FC<ReportPreviewModalProps> = ({ 
  isOpen, 
  onClose, 
  selectedStudents = [], 
  currentTerm = 'Cuối kỳ 1',
  visibleColumns = ['gk1', 'ck1'] // Default if not provided
}) => {
  if (!isOpen) return null;

  const displayStudents = selectedStudents.length > 0 ? selectedStudents : [STUDENTS_DATA[0]];
  const isYearEnd = currentTerm === 'Cuối năm';

  // Define the column config
  const columnConfig = [
    { key: 'gk1', label: 'Giữa HK 1', bg: 'bg-gray-50' },
    { key: 'ck1', label: 'Cuối HK 1', bg: 'bg-gray-100' },
    { key: 'gk2', label: 'Giữa HK 2', bg: 'bg-gray-50' },
    { key: 'cn', label: 'Cuối Năm', bg: 'bg-gray-100' },
  ];

  // Filter columns to show based on prop
  const activeColumns = columnConfig.filter(col => visibleColumns.includes(col.key));

  const getSpecificCompetencies = (className: string) => {
    const basic = ['Ngôn ngữ', 'Tính toán', 'Khoa học', 'Thẩm mỹ', 'Thể chất'];
    if (className === '5A2') {
       return ['Ngôn ngữ', 'Tính toán', 'Khoa học', 'Công nghệ', 'Tin học', 'Thẩm mỹ', 'Thể chất'];
    }
    return basic;
  };

  const getDeterministicValue = (seed: string, offset: number, range: number) => {
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
      hash = (hash << 5) - hash + seed.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash + offset) % range;
  };

  const hasScoreForPeriod = (className: string, subject: string, period: string) => {
    if (className === '1A2') {
        if (!['Toán', 'Tiếng Việt'].includes(subject)) return false;
        return period.includes('Cuối'); 
    }
    if (className === '5A2') {
        if (['Toán', 'Tiếng Việt'].includes(subject)) return true; 
        if (['Khoa học', 'Lịch sử và Địa lý', 'Ngoại ngữ 1', 'Tin học và Công nghệ'].includes(subject)) {
            return period.includes('Cuối');
        }
        return false;
    }
    return false;
  };

  const generateGradeData = (student: Student, subjName: string) => {
    const seed = `${student.id}-${subjName}`;
    const levels = ['T', 'H'];

    // Map data keys to column keys
    const periods = [
        { key: 'gk1', label: 'Giữa kỳ 1' },
        { key: 'ck1', label: 'Cuối kỳ 1' },
        { key: 'gk2', label: 'Giữa kỳ 2' },
        { key: 'cn', label: 'Cuối năm' }
    ];

    const data: any = {};

    periods.forEach((p, idx) => {
        const hasScore = hasScoreForPeriod(student.className, subjName, p.label);
        data[p.key] = {
            m: levels[getDeterministicValue(seed, (idx + 1) * 10, 2)],
            d: hasScore ? (7 + getDeterministicValue(seed, (idx + 1) * 15, 30) / 10).toFixed(0) : ''
        };
    });

    data.kqgd = ['T', 'H'][getDeterministicValue(seed, 90, 2)];
    return data;
  };

  const generateCompetencyData = (student: Student, name: string) => {
    const seed = `${student.id}-${name}`;
    const levels = ['T', 'Đ', 'T']; 

    const gk1 = levels[getDeterministicValue(seed, 10, 3)];
    const ck1 = levels[getDeterministicValue(seed, 20, 3)];
    const gk2 = levels[getDeterministicValue(seed, 30, 3)];
    const cn = levels[getDeterministicValue(seed, 40, 3)];

    return { gk1, ck1, gk2, cn };
  };

  const getGroupComment = (student: Student, groupTitle: string) => {
      const seed = `${student.id}-${groupTitle}`;
      const goodComments = [
        "Hoàn thành tốt nhiệm vụ.",
        "Có ý thức tự giác, tích cực.",
        "Thực hiện tốt các yêu cầu.",
        "Năng nổ, chủ động trong học tập."
      ];
      const avgComments = [
        "Hoàn thành nhiệm vụ.",
        "Cần mạnh dạn hơn.",
        "Có cố gắng trong học tập.",
        "Thực hiện đầy đủ yêu cầu."
      ];

      const isGood = getDeterministicValue(seed, 25, 10) > 3;
      const pool = isGood ? goodComments : avgComments;

      return pool[getDeterministicValue(seed, 42, pool.length)];
  };

  const getOverallAssessment = (student: Student) => {
    const seed = student.id; 
    const val = getDeterministicValue(seed, 99, 10); 

    if (val >= 3) {
        return {
            khenThuong: "Học sinh Xuất sắc",
            kqgd: "Hoàn thành Xuất sắc",
            nhanXet: "Con ngoan, lễ phép, tiếp thu bài nhanh. Hoàn thành xuất sắc các nội dung học tập và rèn luyện.",
            trangThai: "Được lên lớp"
        };
    } else if (val >= 1) {
        return {
            khenThuong: "Học sinh Tiêu biểu",
            kqgd: "Hoàn thành Tốt",
            nhanXet: "Con chăm chỉ, có ý thức học tập tốt. Cần phát huy hơn nữa trong năm học tới.",
            trangThai: "Được lên lớp"
        };
    } else {
        return {
            khenThuong: "",
            kqgd: "Hoàn thành",
            nhanXet: "Con cần cố gắng rèn chữ viết và tính toán cẩn thận hơn.",
            trangThai: val === 0 ? "Rèn luyện lại trong hè" : "Được lên lớp"
        };
    }
  };

  const renderStudentReport = (student: Student, index: number) => {
    const className = student.className;
    const classSubjects = SUBJECTS_BY_CLASS[className] || SUBJECTS_BY_CLASS['1A2'];
    const specificCompetencies = getSpecificCompetencies(className);
    const overall = getOverallAssessment(student);

    const subjects = classSubjects.map((name, idx) => {
      const grades = generateGradeData(student, name);
      return {
        stt: idx + 1,
        name: name,
        ...grades, 
        note: grades.cn.m === 'T' ? 'Nắm vững kiến thức.' : 'Hoàn thành yêu cầu.'
      };
    });

    const groups = [
      { title: 'Năng lực chung', items: CORE_COMPETENCIES, startIdx: 1 },
      { title: 'Năng lực đặc thù', items: specificCompetencies, startIdx: 2 },
      { title: 'Phẩm chất chủ yếu', items: KEY_QUALITIES, startIdx: 3 }
    ];

    return (
      <div key={student.id} className={`flex flex-col items-center w-full ${index > 0 ? 'print:break-before-page mt-12 pt-12 border-t-2 border-dashed border-gray-300 print:border-none print:mt-0 print:pt-0' : ''}`}>
        <div className="w-full max-w-[900px] bg-white shadow-2xl p-8 md:p-12 min-h-[1100px] text-gray-900 font-serif leading-relaxed print:shadow-none print:p-0">
          <div className="text-center mb-6">
            <h2 className="text-[13px] font-bold uppercase tracking-wide mb-1 leading-none">SỞ GIÁO DỤC VÀ ĐÀO TẠO TP.HCM</h2>
            <h2 className="text-[13px] font-bold uppercase tracking-wide border-b border-black inline-block px-4 pb-1 mb-4 leading-none">TRƯỜNG TIỂU HỌC LAM SƠN</h2>

            <h1 className="text-xl md:text-2xl font-bold uppercase tracking-normal mb-1 text-[#1e293b]">PHIẾU BÁO KẾT QUẢ HỌC TẬP VÀ RÈN LUYỆN</h1>
            <p className="text-[14px] font-bold text-[#1e293b]">Năm học: 2025 - 2026</p>
            <p className="text-[14px] font-semibold italic text-blue-700">({isYearEnd ? 'Cuối năm học' : currentTerm})</p>
          </div>

          <div className="mb-4 text-[14px] font-serif">
            <div className="flex items-end mb-2">
              <span className="font-bold whitespace-nowrap mr-2">Họ và tên học sinh:</span>
              <span className="font-bold flex-1 border-b border-dotted border-gray-400 pb-0.5">{student.name}</span>
            </div>
            <div className="flex items-end gap-8">
                <div className="flex items-end w-[35%]">
                    <span className="font-bold whitespace-nowrap mr-2">Lớp:</span>
                    <span className="flex-1 border-b border-dotted border-gray-400 pb-0.5 pl-2">{className}</span>
                </div>
                <div className="flex items-end flex-1">
                    <span className="font-bold whitespace-nowrap mr-2">Ngày sinh:</span>
                    <span className="flex-1 border-b border-dotted border-gray-400 pb-0.5 pl-2">{student.dob}</span>
                </div>
            </div>
          </div>

          <h3 className="font-bold text-sm mb-4 font-sans uppercase text-blue-800">I. Các môn học và hoạt động giáo dục</h3>

          <table className="w-full border-collapse border border-gray-800 text-[12px] font-sans mb-6 table-fixed">
            <thead>
              <tr className="bg-gray-100/50">
                {/* FIXED WIDTH COLUMNS */}
                <th rowSpan={2} className="border border-gray-800 p-1 text-center w-[35px]">STT</th>
                <th rowSpan={2} className="border border-gray-800 p-1 text-left w-[200px]">Môn học và hoạt động giáo dục</th>

                {/* Dynamic Header Row 1: Periods */}
                {activeColumns.map(col => (
                    <th key={col.key} colSpan={2} className={`border border-gray-800 p-1 text-center ${col.bg}`}>
                        {col.label}
                    </th>
                ))}

                {/* FLEXIBLE COMMENT COLUMN (No width set, auto expands) */}
                <th rowSpan={2} className="border border-gray-800 p-1 text-center">Nhận xét</th>
              </tr>
              <tr className="bg-gray-100/50">
                 {/* Dynamic Header Row 2: Level/Score - VERY COMPACT WIDTH */}
                 {activeColumns.map(col => (
                    <React.Fragment key={`${col.key}-sub`}>
                        <th className="border border-gray-800 p-0.5 text-center text-[10px] w-[45px]">Mức</th>
                        <th className="border border-gray-800 p-0.5 text-center text-[10px] w-[45px]">Điểm</th>
                    </React.Fragment>
                 ))}
              </tr>
            </thead>
            <tbody>
              {subjects.map((sub) => {
                  const cellClass = "border border-gray-800 p-1 text-center font-semibold text-[11px]";
                  const scoreClass = "border border-gray-800 p-1 text-center font-bold text-blue-700 text-[11px]";

                  return (
                    <tr key={sub.stt} className="hover:bg-gray-50/50">
                        <td className="border border-gray-800 p-1 text-center">{sub.stt}</td>
                        <td className="border border-gray-800 p-1 font-medium truncate text-left px-2">{sub.name}</td>

                        {/* Dynamic Body Cells */}
                        {activeColumns.map(col => {
                            const data = (sub as any)[col.key]; // Access dynamic key like sub.gk1
                            return (
                                <React.Fragment key={`${col.key}-${sub.stt}`}>
                                    <td className={`${cellClass} ${col.bg}`}>{data?.m}</td>
                                    <td className={`${scoreClass} ${col.bg}`}>{data?.d}</td>
                                </React.Fragment>
                            );
                        })}

                        {/* Comment Cell: Left aligned, padded, break-words */}
                        <td className="border border-gray-800 p-2 text-[11px] align-middle italic text-gray-700 leading-tight text-left break-words whitespace-normal">{sub.note}</td>
                    </tr>
                  )
              })}
            </tbody>
          </table>

          <div className="text-[11px] italic mb-8 font-sans flex flex-wrap gap-6 text-gray-600">
            <div><b>Mức đạt được:</b> T: Hoàn thành tốt, H: Hoàn thành, C: Chưa hoàn thành.</div>
            <div><b>KQGD:</b> Kết quả giáo dục (T/H/C).</div>
          </div>

          <div className="mb-4 font-sans print:break-before-page">
             <h3 className="font-bold text-sm mb-3 uppercase text-blue-800 pt-4 print:pt-8">II. Đánh giá phẩm chất và năng lực</h3>

             <table className="w-full border-collapse border border-gray-800 text-[12px] font-sans table-fixed">
              <thead>
                <tr className="bg-gray-100/50">
                  <th rowSpan={2} className="border border-gray-800 p-1 text-center w-[35px]">STT</th>
                  <th rowSpan={2} className="border border-gray-800 p-1 text-center w-[90px]">Nhóm năng lực</th>
                  <th rowSpan={2} className="border border-gray-800 p-1 text-left w-[180px]">Tiêu chí đánh giá</th>

                  {/* Dynamic Header for Competencies - FIXED WIDTH */}
                  {activeColumns.map(col => (
                      <th key={col.key} className={`border border-gray-800 p-1 text-center ${col.bg} w-[45px]`}>
                          {col.label}
                      </th>
                  ))}

                  <th rowSpan={2} className="border border-gray-800 p-1 text-center">Nhận xét</th>
                </tr>
                <tr className="bg-gray-100/50">
                  {/* Dynamic Sub-header for Competencies */}
                  {activeColumns.map(col => (
                      <th key={`${col.key}-sub`} className="border border-gray-800 p-1 text-center font-bold text-[10px]">Mức</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                  {groups.map((group) => {
                     const groupComment = getGroupComment(student, group.title);

                     return group.items.map((item, itemIdx) => {
                        const scores: any = generateCompetencyData(student, item); // returns {gk1, ck1...}
                        const isFirst = itemIdx === 0;
                        const rowSpan = group.items.length;

                        return (
                            <tr key={`${group.title}-${item}`} className="hover:bg-gray-50/50">
                                {isFirst && (
                                    <>
                                        <td rowSpan={rowSpan} className="border border-gray-800 p-1 text-center align-middle font-bold">{group.startIdx}</td>
                                        <td rowSpan={rowSpan} className="border border-gray-800 p-2 align-middle">
                                            <div className="font-bold uppercase text-[10px] text-blue-800">{group.title}</div>
                                        </td>
                                    </>
                                )}

                                <td className="border border-gray-800 p-1 align-middle pl-2 text-[11px] text-left">
                                   - {item}
                                </td>

                                {/* Dynamic Body Cells for Competencies */}
                                {activeColumns.map(col => (
                                    <td key={col.key} className={`border border-gray-800 p-1 text-center align-middle text-[11px] font-semibold ${col.bg}`}>
                                        {scores[col.key]}
                                    </td>
                                ))}

                                {isFirst && (
                                    <td rowSpan={rowSpan} className="border border-gray-800 p-2 text-[11px] italic text-gray-700 align-middle text-left px-2 break-words whitespace-normal">
                                        {groupComment}
                                    </td>
                                )}
                            </tr>
                        );
                     });
                  })}
              </tbody>
            </table>
          </div>

          {isYearEnd && (
             <div className="mb-6 text-[13px] font-sans px-1">
                <div className="grid grid-cols-2 gap-x-12 gap-y-3">
                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Khen thưởng:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 font-medium">
                         {overall.khenThuong}
                       </span>
                    </div>
                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Trạng thái:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 font-bold">
                         {overall.trangThai}
                       </span>
                    </div>

                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Đánh giá KQGD:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 font-bold uppercase">
                         {overall.kqgd}
                       </span>
                    </div>
                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Nhận xét:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 italic truncate">
                         {overall.nhanXet}
                       </span>
                    </div>
                </div>
             </div>
          )}

          <div className="grid grid-cols-2 gap-10 mt-10 text-center text-sm font-sans">
            <div className="flex flex-col items-center">
              <p className="italic mb-2 text-gray-500">.........., ngày ..... tháng ..... năm 2026</p>
              <p className="font-bold uppercase text-gray-800">PHỤ HUYNH HỌC SINH</p>
              <div className="h-24"></div>
              <p className="font-semibold text-gray-400 italic">(Ký và ghi rõ họ tên)</p>
            </div>
            <div className="flex flex-col items-center">
              <p className="italic mb-2 text-gray-500">TP.HCM, ngày {new Date().getDate()} tháng {new Date().getMonth() + 1} năm {new Date().getFullYear()}</p>
              <p className="font-bold uppercase text-gray-800">GIÁO VIÊN CHỦ NHIỆM</p>
              <div className="h-24"></div>
              <p className="font-bold text-gray-900 border-b border-gray-900 inline-block px-4">Nguyễn Thị Anh</p>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[9999] flex flex-col bg-gray-500/40 backdrop-blur-sm overflow-hidden animate-in fade-in duration-200">
      <div className="bg-white border-b border-gray-200 px-6 py-3 flex items-center justify-between shadow-md sticky top-0 z-10 print:hidden">
        <h2 className="text-gray-800 font-bold text-lg">Xem trước {displayStudents.length} Phiếu điểm - {currentTerm}</h2>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => window.print()}
            className="flex items-center gap-2 px-5 py-2 bg-[#2563eb] text-white rounded-md font-semibold hover:bg-blue-700 transition-colors shadow-sm"
          >
            <Printer size={18} />
            In Phiếu Điểm ({displayStudents.length})
          </button>
          <button 
            onClick={onClose}
            className="p-1.5 text-gray-500 hover:text-gray-800 hover:bg-gray-100 rounded-lg transition-all"
          >
            <X size={24} />
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-auto p-4 md:p-10 flex flex-col items-center bg-gray-200/50 custom-scrollbar">
        {displayStudents.map((student, index) => renderStudentReport(student, index))}
      </div>
    </div>
  );
};

export default ReportPreviewModal;

import React from 'react';
import { X, Printer } from 'lucide-react';
import { SUBJECTS_BY_CLASS, STUDENTS_DATA } from '../constants';
import { Student } from '../types';

interface ReportPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedStudents?: Student[];
  currentTerm?: string;
  visibleColumns?: string[]; // New prop
}

const CORE_COMPETENCIES = [
  'Tự chủ và tự học',
  'Giao tiếp và hợp tác',
  'Giải quyết vấn đề và sáng tạo'
];

const KEY_QUALITIES = [
  'Yêu nước',
  'Nhân ái',
  'Chăm chỉ',
  'Trung thực',
  'Trách nhiệm'
];

const ReportPreviewModal: React.FC<ReportPreviewModalProps> = ({ 
  isOpen, 
  onClose, 
  selectedStudents = [], 
  currentTerm = 'Cuối kỳ 1',
  visibleColumns = ['gk1', 'ck1'] // Default if not provided
}) => {
  if (!isOpen) return null;

  const displayStudents = selectedStudents.length > 0 ? selectedStudents : [STUDENTS_DATA[0]];
  const isYearEnd = currentTerm === 'Cuối năm';

  // Define the column config
  const columnConfig = [
    { key: 'gk1', label: 'Giữa HK 1', bg: 'bg-gray-50' },
    { key: 'ck1', label: 'Cuối HK 1', bg: 'bg-gray-100' },
    { key: 'gk2', label: 'Giữa HK 2', bg: 'bg-gray-50' },
    { key: 'cn', label: 'Cuối Năm', bg: 'bg-gray-100' },
  ];

  // Filter columns to show based on prop
  const activeColumns = columnConfig.filter(col => visibleColumns.includes(col.key));

  const getSpecificCompetencies = (className: string) => {
    const basic = ['Ngôn ngữ', 'Tính toán', 'Khoa học', 'Thẩm mỹ', 'Thể chất'];
    if (className === '5A2') {
       return ['Ngôn ngữ', 'Tính toán', 'Khoa học', 'Công nghệ', 'Tin học', 'Thẩm mỹ', 'Thể chất'];
    }
    return basic;
  };

  const getDeterministicValue = (seed: string, offset: number, range: number) => {
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
      hash = (hash << 5) - hash + seed.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash + offset) % range;
  };

  const hasScoreForPeriod = (className: string, subject: string, period: string) => {
    if (className === '1A2') {
        if (!['Toán', 'Tiếng Việt'].includes(subject)) return false;
        return period.includes('Cuối'); 
    }
    if (className === '5A2') {
        if (['Toán', 'Tiếng Việt'].includes(subject)) return true; 
        if (['Khoa học', 'Lịch sử và Địa lý', 'Ngoại ngữ 1', 'Tin học và Công nghệ'].includes(subject)) {
            return period.includes('Cuối');
        }
        return false;
    }
    return false;
  };

  const generateGradeData = (student: Student, subjName: string) => {
    const seed = `${student.id}-${subjName}`;
    const levels = ['T', 'H'];

    // Map data keys to column keys
    const periods = [
        { key: 'gk1', label: 'Giữa kỳ 1' },
        { key: 'ck1', label: 'Cuối kỳ 1' },
        { key: 'gk2', label: 'Giữa kỳ 2' },
        { key: 'cn', label: 'Cuối năm' }
    ];

    const data: any = {};

    periods.forEach((p, idx) => {
        const hasScore = hasScoreForPeriod(student.className, subjName, p.label);
        data[p.key] = {
            m: levels[getDeterministicValue(seed, (idx + 1) * 10, 2)],
            d: hasScore ? (7 + getDeterministicValue(seed, (idx + 1) * 15, 30) / 10).toFixed(0) : ''
        };
    });

    data.kqgd = ['T', 'H'][getDeterministicValue(seed, 90, 2)];
    return data;
  };

  const generateCompetencyData = (student: Student, name: string) => {
    const seed = `${student.id}-${name}`;
    const levels = ['T', 'Đ', 'T']; 

    const gk1 = levels[getDeterministicValue(seed, 10, 3)];
    const ck1 = levels[getDeterministicValue(seed, 20, 3)];
    const gk2 = levels[getDeterministicValue(seed, 30, 3)];
    const cn = levels[getDeterministicValue(seed, 40, 3)];

    return { gk1, ck1, gk2, cn };
  };

  const getGroupComment = (student: Student, groupTitle: string) => {
      const seed = `${student.id}-${groupTitle}`;
      const goodComments = [
        "Hoàn thành tốt nhiệm vụ.",
        "Có ý thức tự giác, tích cực.",
        "Thực hiện tốt các yêu cầu.",
        "Năng nổ, chủ động trong học tập."
      ];
      const avgComments = [
        "Hoàn thành nhiệm vụ.",
        "Cần mạnh dạn hơn.",
        "Có cố gắng trong học tập.",
        "Thực hiện đầy đủ yêu cầu."
      ];

      const isGood = getDeterministicValue(seed, 25, 10) > 3;
      const pool = isGood ? goodComments : avgComments;

      return pool[getDeterministicValue(seed, 42, pool.length)];
  };

  const getOverallAssessment = (student: Student) => {
    const seed = student.id; 
    const val = getDeterministicValue(seed, 99, 10); 

    if (val >= 3) {
        return {
            khenThuong: "Học sinh Xuất sắc",
            kqgd: "Hoàn thành Xuất sắc",
            nhanXet: "Con ngoan, lễ phép, tiếp thu bài nhanh. Hoàn thành xuất sắc các nội dung học tập và rèn luyện.",
            trangThai: "Được lên lớp"
        };
    } else if (val >= 1) {
        return {
            khenThuong: "Học sinh Tiêu biểu",
            kqgd: "Hoàn thành Tốt",
            nhanXet: "Con chăm chỉ, có ý thức học tập tốt. Cần phát huy hơn nữa trong năm học tới.",
            trangThai: "Được lên lớp"
        };
    } else {
        return {
            khenThuong: "",
            kqgd: "Hoàn thành",
            nhanXet: "Con cần cố gắng rèn chữ viết và tính toán cẩn thận hơn.",
            trangThai: val === 0 ? "Rèn luyện lại trong hè" : "Được lên lớp"
        };
    }
  };

  const renderStudentReport = (student: Student, index: number) => {
    const className = student.className;
    const classSubjects = SUBJECTS_BY_CLASS[className] || SUBJECTS_BY_CLASS['1A2'];
    const specificCompetencies = getSpecificCompetencies(className);
    const overall = getOverallAssessment(student);

    const subjects = classSubjects.map((name, idx) => {
      const grades = generateGradeData(student, name);
      return {
        stt: idx + 1,
        name: name,
        ...grades, 
        note: grades.cn.m === 'T' ? 'Nắm vững kiến thức.' : 'Hoàn thành yêu cầu.'
      };
    });

    const groups = [
      { title: 'Năng lực chung', items: CORE_COMPETENCIES, startIdx: 1 },
      { title: 'Năng lực đặc thù', items: specificCompetencies, startIdx: 2 },
      { title: 'Phẩm chất chủ yếu', items: KEY_QUALITIES, startIdx: 3 }
    ];

    return (
      <div key={student.id} className={`flex flex-col items-center w-full ${index > 0 ? 'print:break-before-page mt-12 pt-12 border-t-2 border-dashed border-gray-300 print:border-none print:mt-0 print:pt-0' : ''}`}>
        <div className="w-full max-w-[900px] bg-white shadow-2xl p-8 md:p-12 min-h-[1100px] text-gray-900 font-serif leading-relaxed print:shadow-none print:p-0">
          <div className="text-center mb-6">
            <h2 className="text-[13px] font-bold uppercase tracking-wide mb-1 leading-none">SỞ GIÁO DỤC VÀ ĐÀO TẠO TP.HCM</h2>
            <h2 className="text-[13px] font-bold uppercase tracking-wide border-b border-black inline-block px-4 pb-1 mb-4 leading-none">TRƯỜNG TIỂU HỌC LAM SƠN</h2>

            <h1 className="text-xl md:text-2xl font-bold uppercase tracking-normal mb-1 text-[#1e293b]">PHIẾU BÁO KẾT QUẢ HỌC TẬP VÀ RÈN LUYỆN</h1>
            <p className="text-[14px] font-bold text-[#1e293b]">Năm học: 2025 - 2026</p>
            <p className="text-[14px] font-semibold italic text-blue-700">({isYearEnd ? 'Cuối năm học' : currentTerm})</p>
          </div>

          <div className="mb-4 text-[14px] font-serif">
            <div className="flex items-end mb-2">
              <span className="font-bold whitespace-nowrap mr-2">Họ và tên học sinh:</span>
              <span className="font-bold flex-1 border-b border-dotted border-gray-400 pb-0.5">{student.name}</span>
            </div>
            <div className="flex items-end gap-8">
                <div className="flex items-end w-[35%]">
                    <span className="font-bold whitespace-nowrap mr-2">Lớp:</span>
                    <span className="flex-1 border-b border-dotted border-gray-400 pb-0.5 pl-2">{className}</span>
                </div>
                <div className="flex items-end flex-1">
                    <span className="font-bold whitespace-nowrap mr-2">Ngày sinh:</span>
                    <span className="flex-1 border-b border-dotted border-gray-400 pb-0.5 pl-2">{student.dob}</span>
                </div>
            </div>
          </div>

          <h3 className="font-bold text-sm mb-4 font-sans uppercase text-blue-800">I. Các môn học và hoạt động giáo dục</h3>

          <table className="w-full border-collapse border border-gray-800 text-[12px] font-sans mb-6 table-fixed">
            <thead>
              <tr className="bg-gray-100/50">
                {/* 1. FIXED SMALL STT */}
                <th rowSpan={2} className="border border-gray-800 p-1 text-center w-[30px]">STT</th>
                {/* 2. FIXED MEDIUM SUBJECT */}
                <th rowSpan={2} className="border border-gray-800 p-1 text-left w-[180px]">Môn học và hoạt động giáo dục</th>

                {/* Dynamic Header Row 1: Periods */}
                {activeColumns.map(col => (
                    <th key={col.key} colSpan={2} className={`border border-gray-800 p-1 text-center ${col.bg}`}>
                        {col.label}
                    </th>
                ))}

                {/* 3. FLEXIBLE LARGE COMMENT COLUMN */}
                <th rowSpan={2} className="border border-gray-800 p-1 text-center">Nhận xét</th>
              </tr>
              <tr className="bg-gray-100/50">
                 {/* 4. FIXED TINY SCORE/LEVEL COLUMNS */}
                 {activeColumns.map(col => (
                    <React.Fragment key={`${col.key}-sub`}>
                        <th className="border border-gray-800 p-0.5 text-center text-[10px] w-[35px]">Mức</th>
                        <th className="border border-gray-800 p-0.5 text-center text-[10px] w-[35px]">Điểm</th>
                    </React.Fragment>
                 ))}
              </tr>
            </thead>
            <tbody>
              {subjects.map((sub) => {
                  const cellClass = "border border-gray-800 p-1 text-center font-semibold text-[11px]";
                  const scoreClass = "border border-gray-800 p-1 text-center font-bold text-blue-700 text-[11px]";

                  return (
                    <tr key={sub.stt} className="hover:bg-gray-50/50">
                        <td className="border border-gray-800 p-1 text-center">{sub.stt}</td>
                        <td className="border border-gray-800 p-1 font-medium truncate text-left px-2">{sub.name}</td>

                        {/* Dynamic Body Cells */}
                        {activeColumns.map(col => {
                            const data = (sub as any)[col.key]; // Access dynamic key like sub.gk1
                            return (
                                <React.Fragment key={`${col.key}-${sub.stt}`}>
                                    <td className={`${cellClass} ${col.bg}`}>{data?.m}</td>
                                    <td className={`${scoreClass} ${col.bg}`}>{data?.d}</td>
                                </React.Fragment>
                            );
                        })}

                        {/* Comment Cell: Auto Width */}
                        <td className="border border-gray-800 p-2 text-[11px] align-middle italic text-gray-700 leading-tight text-left break-words whitespace-normal">{sub.note}</td>
                    </tr>
                  )
              })}
            </tbody>
          </table>

          <div className="text-[11px] italic mb-8 font-sans flex flex-wrap gap-6 text-gray-600">
            <div><b>Mức đạt được:</b> T: Hoàn thành tốt, H: Hoàn thành, C: Chưa hoàn thành.</div>
            <div><b>KQGD:</b> Kết quả giáo dục (T/H/C).</div>
          </div>

          <div className="mb-4 font-sans print:break-before-page">
             <h3 className="font-bold text-sm mb-3 uppercase text-blue-800 pt-4 print:pt-8">II. Đánh giá phẩm chất và năng lực</h3>

             <table className="w-full border-collapse border border-gray-800 text-[12px] font-sans table-fixed">
              <thead>
                <tr className="bg-gray-100/50">
                  {/* SAME FIXED WIDTHS AS TABLE ABOVE */}
                  <th rowSpan={2} className="border border-gray-800 p-1 text-center w-[30px]">STT</th>
                  <th rowSpan={2} className="border border-gray-800 p-1 text-center w-[80px]">Nhóm năng lực</th>
                  <th rowSpan={2} className="border border-gray-800 p-1 text-left w-[180px]">Tiêu chí đánh giá</th>

                  {/* Dynamic Header for Competencies */}
                  {activeColumns.map(col => (
                      <th key={col.key} className={`border border-gray-800 p-1 text-center ${col.bg} w-[35px]`}>
                          {col.label}
                      </th>
                  ))}

                  <th rowSpan={2} className="border border-gray-800 p-1 text-center">Nhận xét</th>
                </tr>
                <tr className="bg-gray-100/50">
                  {/* Dynamic Sub-header for Competencies */}
                  {activeColumns.map(col => (
                      <th key={`${col.key}-sub`} className="border border-gray-800 p-1 text-center font-bold text-[10px]">Mức</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                  {groups.map((group) => {
                     const groupComment = getGroupComment(student, group.title);

                     return group.items.map((item, itemIdx) => {
                        const scores: any = generateCompetencyData(student, item); // returns {gk1, ck1...}
                        const isFirst = itemIdx === 0;
                        const rowSpan = group.items.length;

                        return (
                            <tr key={`${group.title}-${item}`} className="hover:bg-gray-50/50">
                                {isFirst && (
                                    <>
                                        <td rowSpan={rowSpan} className="border border-gray-800 p-1 text-center align-middle font-bold">{group.startIdx}</td>
                                        <td rowSpan={rowSpan} className="border border-gray-800 p-2 align-middle">
                                            <div className="font-bold uppercase text-[10px] text-blue-800">{group.title}</div>
                                        </td>
                                    </>
                                )}

                                <td className="border border-gray-800 p-1 align-middle pl-2 text-[11px] text-left">
                                   - {item}
                                </td>

                                {/* Dynamic Body Cells for Competencies */}
                                {activeColumns.map(col => (
                                    <td key={col.key} className={`border border-gray-800 p-1 text-center align-middle text-[11px] font-semibold ${col.bg}`}>
                                        {scores[col.key]}
                                    </td>
                                ))}

                                {isFirst && (
                                    <td rowSpan={rowSpan} className="border border-gray-800 p-2 text-[11px] italic text-gray-700 align-middle text-left px-2 break-words whitespace-normal">
                                        {groupComment}
                                    </td>
                                )}
                            </tr>
                        );
                     });
                  })}
              </tbody>
            </table>
          </div>

          {isYearEnd && (
             <div className="mb-6 text-[13px] font-sans px-1">
                <div className="grid grid-cols-2 gap-x-12 gap-y-3">
                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Khen thưởng:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 font-medium">
                         {overall.khenThuong}
                       </span>
                    </div>
                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Trạng thái:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 font-bold">
                         {overall.trangThai}
                       </span>
                    </div>

                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Đánh giá KQGD:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 font-bold uppercase">
                         {overall.kqgd}
                       </span>
                    </div>
                    <div className="flex items-end gap-2">
                       <span className="font-bold whitespace-nowrap min-w-[80px]">Nhận xét:</span>
                       <span className="flex-1 border-b border-dotted border-gray-500 pb-0.5 text-gray-800 italic truncate">
                         {overall.nhanXet}
                       </span>
                    </div>
                </div>
             </div>
          )}

          <div className="grid grid-cols-2 gap-10 mt-10 text-center text-sm font-sans">
            <div className="flex flex-col items-center">
              <p className="italic mb-2 text-gray-500">.........., ngày ..... tháng ..... năm 2026</p>
              <p className="font-bold uppercase text-gray-800">PHỤ HUYNH HỌC SINH</p>
              <div className="h-24"></div>
              <p className="font-semibold text-gray-400 italic">(Ký và ghi rõ họ tên)</p>
            </div>
            <div className="flex flex-col items-center">
              <p className="italic mb-2 text-gray-500">TP.HCM, ngày {new Date().getDate()} tháng {new Date().getMonth() + 1} năm {new Date().getFullYear()}</p>
              <p className="font-bold uppercase text-gray-800">GIÁO VIÊN CHỦ NHIỆM</p>
              <div className="h-24"></div>
              <p className="font-bold text-gray-900 border-b border-gray-900 inline-block px-4">Nguyễn Thị Anh</p>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[9999] flex flex-col bg-gray-500/40 backdrop-blur-sm overflow-hidden animate-in fade-in duration-200">
      <div className="bg-white border-b border-gray-200 px-6 py-3 flex items-center justify-between shadow-md sticky top-0 z-10 print:hidden">
        <h2 className="text-gray-800 font-bold text-lg">Xem trước {displayStudents.length} Phiếu điểm - {currentTerm}</h2>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => window.print()}
            className="flex items-center gap-2 px-5 py-2 bg-[#2563eb] text-white rounded-md font-semibold hover:bg-blue-700 transition-colors shadow-sm"
          >
            <Printer size={18} />
            In Phiếu Điểm ({displayStudents.length})
          </button>
          <button 
            onClick={onClose}
            className="p-1.5 text-gray-500 hover:text-gray-800 hover:bg-gray-100 rounded-lg transition-all"
          >
            <X size={24} />
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-auto p-4 md:p-10 flex flex-col items-center bg-gray-200/50 custom-scrollbar">
        {displayStudents.map((student, index) => renderStudentReport(student, index))}
      </div>
    </div>
  );
};

export default ReportPreviewModal;

import React, { useState, useRef, useEffect } from 'react';
import { ViewFilter, Student } from '../types';
import { STUDENTS_DATA } from '../constants';
import { Printer, Lock, Unlock, AlertTriangle, Check, X, LockOpen, Info, ChevronUp, ChevronDown } from 'lucide-react';
import ReportPreviewModal from './ReportPreviewModal';
import StudentPrintSelectModal from './StudentPrintSelectModal';

interface FilterBarProps {
  viewFilter: ViewFilter;
  setViewFilter: (filter: ViewFilter) => void;
  term: string;
  setTerm: (term: string) => void;
  selectedClass: string;
  setSelectedClass: (className: string) => void;
  isLocked?: boolean;
  setIsLocked?: (locked: boolean) => void;
}

const FilterBar: React.FC<FilterBarProps> = ({ 
  viewFilter, 
  setViewFilter, 
  term, 
  setTerm, 
  selectedClass, 
  setSelectedClass,
  isLocked = false,
  setIsLocked
}) => {
  const [showPrintDropdown, setShowPrintDropdown] = useState(false);
  const [isPrintSelectOpen, setIsPrintSelectOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [selectedStudents, setSelectedStudents] = useState<Student[]>([]);
  const [isNoteExpanded, setIsNoteExpanded] = useState(true);
  const [showInstructions, setShowInstructions] = useState(true);

  // Modal states
  const [showLockModal, setShowLockModal] = useState(false);
  const [showRequestUnlockModal, setShowRequestUnlockModal] = useState(false);
  const [showUnlockSuccessModal, setShowUnlockSuccessModal] = useState(false);
  const [unlockReason, setUnlockReason] = useState('');
  const [showReasonError, setShowReasonError] = useState(false);

  const dropdownRef = useRef<HTMLDivElement>(null);

  const tabs: { label: string; value: ViewFilter }[] = [
    { value: 'all', label: 'Tất cả thông tin' },
    { value: 'skills', label: 'Năng lực' },
    { value: 'qualities', label: 'Phẩm chất' },
  ];

  const filteredStudents = STUDENTS_DATA.filter(s => s.className === selectedClass);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowPrintDropdown(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleConfirmStudents = (students: Student[]) => {
    if (students.length > 0) {
      setSelectedStudents(students);
      setIsPrintSelectOpen(false);
      setIsPreviewOpen(true);
    }
  };

  const handleLockClick = () => {
    setShowLockModal(true);
  };

  const confirmLock = () => {
    setIsLocked?.(true);
    setShowLockModal(false);
  };

  const handleUnlockClick = () => {
    setUnlockReason('');
    setShowReasonError(false);
    setShowRequestUnlockModal(true);
  };

  const handleSendUnlockRequest = () => {
    if (!unlockReason.trim()) {
      setShowReasonError(true);
      return;
    }
    setShowRequestUnlockModal(false);
    setTimeout(() => {
        setShowUnlockSuccessModal(true);
    }, 200);
  };

  const handleCloseSuccessModal = () => {
    setShowUnlockSuccessModal(false);
    setIsLocked?.(false);
  };

  return (
    <div className="flex flex-col gap-5 mb-2 relative">
       {/* ROW 1: Filters (Left) & Print Dropdown (Right) */}
       <div className="flex flex-wrap items-end justify-between gap-4">
          {/* Filters Group */}
          <div className="flex flex-wrap gap-4">
              <div className="flex flex-col gap-1">
                <label className="text-xs font-semibold text-gray-600">Năm học</label>
                <select className="px-3 py-2 border border-gray-300 rounded bg-white text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 w-32 shadow-sm">
                   <option>2025-2026</option>
                   <option>2024-2025</option>
                </select>
              </div>
