                                {/* Dynamic Body Cells for Competencies - Minimal Padding */}
                                {activeColumns.map(col => (
                                    <td key={col.key} className={`border border-gray-800 p-[2px] text-center align-middle text-[11px] font-semibold ${col.bg}`}>
                                        {scores[col.key]}
                                    </td>
                                ))}

                                {isFirst && (
                                    <td rowSpan={rowSpan} className="border border-gray-800 p-2 text-[11px] italic text-gray-700 align-middle text-left px-2 break-words whitespace-normal">
                                        {groupComment}
