import React, { useState, useMemo } from 'react';
import { FileSpreadsheet, Info, Filter, BookOpen, BrainCircuit, HeartHandshake } from 'lucide-react';

// --- CONSTANTS & CONFIGURATION ---

const SUBJECTS_LIST = [
  'Tiếng Việt', 'Toán', 'Đạo đức', 'Tự nhiên và Xã hội', 
  'Âm nhạc', 'Mỹ thuật', 'Giáo dục thể chất', 'Hoạt động trải nghiệm'
];

const COMPETENCIES_GENERAL = [
  'Tự chủ và tự học', 'Giao tiếp và hợp tác', 'Giải quyết vấn đề và sáng tạo'
];

const COMPETENCIES_SPECIFIC = [
  'Ngôn ngữ', 'Tính toán', 'Khoa học', 'Thẩm mỹ', 'Thể chất'
];

const QUALITIES_LIST = [
  'Yêu nước', 'Nhân ái', 'Chăm chỉ', 'Trung thực', 'Trách nhiệm'
];

// --- MOCK DATA GENERATOR ---

const generateClassData = (className: string, total: number) => {
  const getRandomStats = (max: number) => {
    const t = Math.floor(Math.random() * (max * 0.6)) + (max * 0.3); // ~30-90%
    const h = Math.floor(Math.random() * (max - t));
    const c = max - t - h;
    return { t, h, c }; // h/d depends on context, we map later
  };

  return {
    className,
    total,
    subjects: SUBJECTS_LIST.reduce((acc, sub) => ({ ...acc, [sub]: getRandomStats(total) }), {} as any),
    competencies: [...COMPETENCIES_GENERAL, ...COMPETENCIES_SPECIFIC].reduce((acc, comp) => ({ ...acc, [comp]: getRandomStats(total) }), {} as any),
    qualities: QUALITIES_LIST.reduce((acc, qual) => ({ ...acc, [qual]: getRandomStats(total) }), {} as any),
  };
};

const REPORT_DATA = [
  generateClassData('1A1', 35),
  generateClassData('1A2', 32),
  generateClassData('1A3', 34),
  generateClassData('1A4', 33),
  generateClassData('1A5', 36),
  generateClassData('1A6', 35),
  generateClassData('1A7', 31),
];

type TabType = 'subjects' | 'competencies' | 'qualities';

const StatisticsReport: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>('subjects');
  const [selectedTerm, setSelectedTerm] = useState('Cuối năm');

  // --- CALCULATE TOTALS ---
  const totals = useMemo(() => {
    const initTotal = { t: 0, h: 0, c: 0 }; // t=Tốt, h=Hoàn thành/Đạt, c=Cần cố gắng

    // Helper to sum deep objects
    const sumDeep = (list: string[], type: 'subjects' | 'competencies' | 'qualities') => {
        return list.reduce((acc, item) => {
            acc[item] = REPORT_DATA.reduce((sum, row) => ({
                t: sum.t + row[type][item].t,
                h: sum.h + row[type][item].h,
                c: sum.c + row[type][item].c,
            }), { ...initTotal });
            return acc;
        }, {} as any);
    };

    return {
        totalStudents: REPORT_DATA.reduce((sum, row) => sum + row.total, 0),
        subjects: sumDeep(SUBJECTS_LIST, 'subjects'),
        competencies: sumDeep([...COMPETENCIES_GENERAL, ...COMPETENCIES_SPECIFIC], 'competencies'),
        qualities: sumDeep(QUALITIES_LIST, 'qualities'),
    };
  }, []);

  // --- RENDER HELPERS ---

  // Determines styles based on active tab
  const getTheme = () => {
      switch (activeTab) {
          case 'subjects': return {
              bg: 'bg-blue-50', text: 'text-blue-800', border: 'border-blue-200', 
              headerBg: 'bg-blue-100', accent: 'bg-blue-600', subHeader: 'bg-blue-50/50'
          };
          case 'competencies': return {
              bg: 'bg-orange-50', text: 'text-orange-900', border: 'border-orange-200',
              headerBg: 'bg-orange-100', accent: 'bg-orange-600', subHeader: 'bg-orange-50/50'
